INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000003', 'en', 'EV Two-Wheeler Service Specialist', 'Diagnoses, services, and repairs electric scooters, BLDC hub motors, lithium-ion battery packs, and regenerative controllers.', 'Running OBD fault diagnostics, checking Battery Management System (BMS) cell balance, replacing throttle/controller harnesses, and servicing brakes.', '10th Pass + ITI Mechanic -> ASDC EV Service Technician Course -> NAPS Apprenticeship at EV Dealership -> Certified EV Specialist.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000003', 'te', 'ఈవీ టూ-వీలర్ సర్వీస్ స్పెషలిస్ట్ (EV Service Specialist)', 'ఎలక్ట్రిక్ స్కూటర్లు, BLDC హబ్ మోటార్లు, లిథియం-అయాన్ బ్యాటరీ ప్యాక్‌లు మరియు కంట్రోలర్‌లను పరీక్షించి మరమ్మతు చేసే నిపుణుడు.', 'OBD స్కానర్ ద్వారా లోపాలు గుర్తించడం, BMS బ్యాటరీ సెల్ వోల్టేజ్ తనిఖీ, మోటార్ కంట్రోలర్ వైరింగ్ మరియు సర్వీసింగ్ చేయడం.', '10వ తరగతి + ఐటిఐ మెకానిక్ -> ASDC EV సర్వీస్ కోర్సు -> ఈవీ షోరూమ్‌లో అప్రెంటిస్‌షిప్ -> సర్టిఫైడ్ ఈవీ టెక్నీషియన్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000003', 'hi', 'ईवी टू-व्हीलर सर्विस विशेषज्ञ (EV Service Specialist)', 'इलेक्ट्रिक स्कूटर, बीएलडीसी मोटर, लिथियम-आयन बैटरी पैक और मोटर कंट्रोलर की जांच और मरम्मत करता है।', 'ओबीडी स्कैनर से फॉल्ट कोड जांचना, बैटरी मैनेजमेंट सिस्टम (BMS) संतुलन देखना, कंट्रोलर वायरिंग और सर्विसिंग करना।', '10वीं पास + आईटीआई मोटर मैकेनिक -> एएसडीसी ईवी सर्विस कोर्स -> ईवी शोरूम अप्रेंटिसशिप -> प्रमाणित ईवी तकनीशियन।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000004', 'en', 'Rural Community Health Facilitator', 'Supports primary health centers and village wellness clinics with vitals screening, immunization outreach, maternal care tracking, and telemedicine.', 'Recording blood pressure, blood sugar, and body temperature, updating ABHA digital health cards, assisting ANMs, and running village hygiene awareness camps.', '12th Pass -> 6-Month HSSC General Duty / Community Health Training -> Primary Health Center Internship -> Village Health Facilitator.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000004', 'te', 'గ్రామీణ కమ్యూనిటీ హెల్త్ ఫెసిలిటేటర్', 'గ్రామ ఆరోగ్య కేంద్రాలు మరియు ప్రాథమిక ఆరోగ్య కేంద్రాలలో రక్తపోటు, షుగర్ పరీక్షలు, టీకాల కార్యక్రమం మరియు టెలిమెడిసిన్ సేవల్లో సహాయం చేస్తుంది.', 'రోగుల వైటల్స్ (BP, పల్స్, గ్లూకోజ్) నమోదు చేయడం, ABHA హెల్త్ కార్డుల అప్‌డేట్, గర్భిణీ స్త్రీలకు మరియు పిల్లలకు ఆరోగ్య అవగాహన కల్పించడం.', '12వ తరగతి -> 6 నెలల HSSC కమ్యూనిటీ హెల్త్ ట్రైనింగ్ -> PHC ఇంటర్న్‌షిప్ -> గ్రామీణ ఆరోగ్య సహాయకులు.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000004', 'hi', 'ग्रामीण सामुदायिक स्वास्थ्य सहायक', 'ग्रामीण स्वास्थ्य केंद्रों में प्राथमिक जांच, टीकाकरण अभियान, मातृ एवं शिशु स्वास्थ्य रिकॉर्ड और टेलीमेडिसिन सेवाओं में सहायता करता है।', 'बीपी, शुगर और तापमान जांचना, आयुष्मान भारत डिजिटल हेल्थ कार्ड (ABHA) अपडेट करना, और ग्रामीण स्वास्थ्य शिविरों का समन्वय करना।', '12वीं पास -> 6 महीने का एचएसएससी सामुदायिक स्वास्थ्य प्रशिक्षण -> प्राथमिक स्वास्थ्य केंद्र इंटर्नशिप -> स्वास्थ्य सहायक।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000005', 'en', 'Village CSC Digital Services Operator', 'Delivers e-Governance, banking, passport, PAN, Aadhaar update, PM-KISAN, and insurance certificates to rural citizens via Common Service Centres.', 'Operating DigiSeva portals, biometric DigiPay cash withdrawals, scanning/uploading citizen forms, utility bill payments, and railway ticketing.', '10th / 12th Pass -> Basic Computer & TEC Certificate -> CSC VLE / Operator Registration -> Self-Employed Digital Seva Kendra Owner.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000005', 'te', 'విలేజ్ సిఎస్సి డిజిటల్ సర్వీసెస్ ఆపరేటర్', 'గ్రామ కామన్ సర్వీస్ సెంటర్ (CSC / మీ-సేవ) ద్వారా పౌరులకు ఆధార్, పాన్ కార్డు, కుల/ఆదాయ ధృవీకరణ పత్రాలు, PM-KISAN మరియు బ్యాంకింగ్ సేవలు అందిస్తారు.', 'డిజిసేవా పోర్టల్ నిర్వహణ, బయోమెట్రిక్ బ్యాంకింగ్ లావాదేవీలు, దరఖాస్తుల స్కానింగ్, విద్యుత్ బిల్లుల చెల్లింపు మరియు రైల్వే టికెట్ బుకింగ్.', '10వ/12వ తరగతి -> కంప్యూటర్ & TEC సర్టిఫికెట్ -> CSC VLE రిజిస్ట్రేషన్ -> స్వయం ఉపాధి డిజిటల్ సేవా కేంద్రం.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000005', 'hi', 'ग्रामीण सीएससी डिजिटल सेवा ऑपरेटर (VLE)', 'कॉमन सर्विस सेंटर (जन सेवा केंद्र) के माध्यम से ग्रामीण नागरिकों को ई-गवर्नेंस, बैंकिंग, पैन कार्ड, प्रमाण-पत्र और सरकारी योजनाओं की सेवाएं देता है।', 'डिजिटल सेवा पोर्टल चलाना, डिजीपे से आधार बैंकिंग, दस्तावेज़ स्कैनिंग, आय/निवास प्रमाण पत्र आवेदन और ऑनलाइन बिल भुगतान।', '10वीं/12वीं पास -> बेसिक कंप्यूटर व टीईसी सर्टिफिकेट -> सीएससी पंजीकरण -> स्वरोजगार डिजिटल सेवा केंद्र।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000025', 'en', 'Agricultural Drone Operator (Kisan Drone Pilot)', 'Pilots DGCA-certified unmanned aircraft systems (Kisan Drones) for precision nano-urea spraying, foliar nutrition, and crop health surveying.', 'Pre-flight calibration, autonomous GPS field mapping, mixing agri-inputs safely, battery bank charging, and maintaining DGCA flight logs.', '10th Pass -> DGCA Approved RPTO Training (15 Days) -> ASCI Kisan Drone Certification -> Custom Hiring Center Drone Entrepreneur.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000025', 'te', 'అగ్రికల్చరల్ డ్రోన్ ఆపరేటర్ (కిసాన్ డ్రోన్ పైలట్)', 'వ్యవసాయ భూములలో నానో యూరియా పిచికారీ, పంట ఆరోగ్య సర్వే కోసం DGCA ఆమోదిత కిసాన్ డ్రోన్‌లను నడిపే సాంకేతిక నిపుణుడు.', 'ఫ్లైట్ కాలిబ్రేషన్, GPS ద్వారా పొలం మ్యాపింగ్, పిచికారీ మందుల మిశ్రమం, బ్యాటరీ నిర్వహణ మరియు లాగ్ బుక్ నమోదు.', '10వ తరగతి -> DGCA ఆమోదిత RPTO శిక్షణ -> కిసాన్ డ్రోన్ సర్టిఫికేట్ -> రైతు సహకార డ్రోన్ సెంటర్ ఉపాధి.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000025', 'hi', 'कृषि ड्रोन ऑपरेटर (किसान ड्रोन पायलट)', 'खेतों में नैनो यूरिया छिड़काव, फसल निगरानी और सटीक खेती के लिए डीजीसीए प्रमाणित किसान ड्रोन का संचालन करता है।', 'प्री-फ्लाइट जांच, जीपीएस फील्ड मैपिंग, सुरक्षित दवा मिश्रण, बैटरी चार्जिंग और उड़ान लॉग का रखरखाव।', '10वीं पास -> डीजीसीए अनुमोदित ड्रोन पायलट प्रशिक्षण -> एएससीआई प्रमाणन -> कस्टम हायरिंग केंद्र उद्यमी।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000026', 'en', 'CNC Machine Operator & Turner', 'Sets up and operates Computer Numerical Control (CNC) lathes and VMC milling machines to manufacture precision automotive and industrial parts.', 'Reading engineering drawings, setting tool offsets, loading metal workpieces, inspecting finished tolerances with micrometers, and adjusting G-code parameters.', '10th Pass -> ITI Machinist / Turner or PMKVY CNC Operator -> NAPS Factory Apprenticeship -> CNC Setter / Programmer.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000026', 'te', 'సీఎన్‌సీ మెషిన్ ఆపరేటర్ & టర్నర్ (CNC Operator)', 'ఆటోమొబైల్ మరియు పారిశ్రామిక విడిభాగాల తయారీలో కంప్యూటర్ ఆధారిత CNC లేత్ మరియు మిల్లింగ్ యంత్రాలను నడిపే నిపుణుడు.', 'డ్రాయింగ్‌లు చదవడం, టూల్ ఆఫ్‌సెట్‌లు సెట్ చేయడం, మైక్రోమీటర్‌తో కొలతలు తనిఖీ చేయడం మరియు G-కోడ్ మార్పులు చేయడం.', '10వ తరగతి -> ఐటిఐ మెషినిస్ట్ / టర్నర్ -> NAPS ఫ్యాక్టరీ అప్రెంటిస్‌షిప్ -> సీనియర్ CNC సెట్టర్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000026', 'hi', 'सीएनसी मशीन ऑपरेटर एवं टर्नर (CNC Operator)', 'ऑटोमोबाइल और औद्योगिक पुर्जे बनाने के लिए कंप्यूटर नियंत्रित सीएनसी लेथ और मिलिंग मशीनों का संचालन करता है।', 'इंजीनियरिंग ड्राइंग पढ़ना, टूल ऑफसेट सेट करना, माइक्रोमीटर से सटीकता मापना और जी-कोड प्रोग्राम जांचना।', '10वीं पास -> आईटीआई मशीनिस्ट / टर्नर -> नैप्स फैक्ट्री अप्रेंटिसशिप -> सीएनसी प्रोग्रामर।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000027', 'en', 'Medical Laboratory Technician (DMLT)', 'Collects blood, urine, and tissue samples and runs hematology, biochemistry, and microbiology diagnostic tests in hospitals and diagnostic labs.', 'Performing venipuncture sample collection, operating automated blood analyzers, staining slides for microscopy, sterilizing glassware, and logging test reports.', '12th Science -> 2-Year DMLT Diploma -> Hospital Clinical Internship -> Certified Diagnostic Lab Technician.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000027', 'te', 'మెడికల్ ల్యాబొరేటరీ టెక్నీషియన్ (DMLT)', 'ఆసుపత్రులు మరియు డయాగ్నస్టిక్ కేంద్రాలలో రక్త, మూత్ర నమూనాలను సేకరించి వ్యాధి నిర్ధారణ పరీక్షలు చేసే వైద్య సహాయ నిపుణుడు.', 'రక్త నమూనాలు సేకరించడం, బయోకెమిస్ట్రీ & హెమటాలజీ యంత్రాలను నడపడం, మైక్రోస్కోప్ పరీక్షలు మరియు రిపోర్టులు తయారు చేయడం.', 'ఇంటర్ బైపీసీ -> 2 ఏళ్ల DMLT డిప్లొమా -> ఆసుపత్రి క్లినికల్ ఇంటర్న్‌షిప్ -> ల్యాబ్ టెక్నీషియన్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000027', 'hi', 'मेडिकल लैबोरेटरी तकनीशियन (DMLT)', 'अस्पतालों और पैथोलॉजी लैब में रक्त, मूत्र और ऊतक के नमूने लेकर हेमेटोलॉजी और माइक्रोबायोलॉजी जांच करता है।', 'ब्लड सैंपल कलेक्शन, ऑटोमेटेड एनालाइजर चलाना, माइक्रोस्कोप स्लाइड जांच, लैब कीटाणुशोधन और टेस्ट रिपोर्ट बनाना।', '12वीं विज्ञान (जीव विज्ञान) -> डीएमएलटी डिप्लोमा -> अस्पताल इंटर्नशिप -> प्रमाणित लैब तकनीशियन।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000028', 'en', 'Hospital Nursing Assistant / General Duty Assistant', 'Provides essential bedside patient care, vitals monitoring, hygiene assistance, and ward support alongside doctors and staff nurses in hospitals and clinics.', 'Monitoring blood pressure and temperature, assisting patient feeding and mobility, preparing surgical beds, and handling emergency first aid.', '10th / 12th Pass -> Free PMKVY General Duty Assistant (GDA) Course -> Clinical Ward Training -> Hospital Nursing Care Assistant.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000028', 'te', 'హాస్పిటల్ నర్సింగ్ అసిస్టెంట్ / జనరల్ డ్యూటీ అసిస్టెంట్ (GDA)', 'ఆసుపత్రులు మరియు నర్సింగ్ హోమ్‌లలో డాక్టర్లు, నర్సులతో కలిసి రోగులకు ప్రాథమిక సంరక్షణ, వైటల్స్ తనిఖీ మరియు వార్డు సేవలు అందిస్తారు.', 'బీపీ మరియు జ్వరం నమోదు, రోగుల కదలికలు మరియు శుభ్రతలో సహాయం, మందుల సమయపాలన మరియు వార్డు సంరక్షణ.', '10వ/12వ తరగతి -> ఉచిత PMKVY GDA శిక్షణ -> ఆసుపత్రి ప్రాక్టికల్స్ -> సర్టిఫైడ్ నర్సింగ్ అసిస్టెంట్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000028', 'hi', 'हॉस्पिटल नर्सिंग असिस्टेंट / जनरल ड्यूटी असिस्टेंट (GDA)', 'अस्पतालों और क्लीनिकों में डॉक्टरों व नर्सों के साथ मिलकर मरीजों की देखभाल, वाइटल जांच और वार्ड सहायता सेवाएं प्रदान करता है।', 'बीपी, पल्स और तापमान की निगरानी, मरीज की स्वच्छता व भोजन में सहायता, बिस्तर तैयार करना और प्राथमिक उपचार।', '10वीं/12वीं पास -> मुफ्त पीएमकेवीवाई जीडीए प्रशिक्षण -> अस्पताल वार्ड अनुभव -> प्रमाणित नर्सिंग सहायक।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000029', 'en', 'Smartphone & Electronics Repair Technician', 'Diagnoses hardware faults, replaces cracked displays and charging ICs using SMD micro-soldering stations, and resolves Android/iOS software issues.', 'Board-level schematic tracing with digital multimeters, SMD BGA rework with hot air guns, battery replacement, and firmware flashing.', '10th Pass -> 3-Month PMKVY Mobile Phone Hardware Repair Course -> Local Service Center Apprenticeship -> Own Mobile Repair Enterprise (MUDRA Loan).') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000029', 'te', 'స్మార్ట్‌ఫోన్ & ఎలక్ట్రానిక్స్ రిపేర్ టెక్నీషియన్', 'స్మార్ట్‌ఫోన్ల మదర్‌బోర్డ్ లోపాలు, డిస్‌ప్లే మార్పిడి, మైక్రో-సోల్డరింగ్ మరియు సాఫ్ట్‌వేర్ సమస్యలను పరిష్కరించే సాంకేతిక నిపుణుడు.', 'మల్టీమీటర్‌తో బోర్డు ట్రేసింగ్, హాట్ ఎయిర్ గన్‌తో IC రిపేర్, ఛార్జింగ్ పిన్/డిస్‌ప్లే మార్పు మరియు సాఫ్ట్‌వేర్ ఫ్లాషింగ్.', '10వ తరగతి -> 3 నెలల PMKVY మొబైల్ రిపేర్ కోర్సు -> సర్వీస్ సెంటర్ అనుభవం -> సొంత మొబైల్ షాప్ (ముద్ర లోన్).') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000029', 'hi', 'स्मार्टफोन और इलेक्ट्रॉनिक्स रिपेयर तकनीशियन', 'माइक्रो-सोल्डरिंग और डिजिटल मल्टीमीटर की मदद से मोबाइल फोन के हार्डवेयर, डिस्प्ले, बैटरी और सॉफ्टवेयर की मरम्मत करता है।', 'मदरबोर्ड फॉल्ट ट्रेसिंग, एसएमडी आईसी रिप्लेसमेंट, टूटी स्क्रीन बदलना और एंड्रॉइड सॉफ्टवेयर फ्लैशिंग।', '10वीं पास -> 3 महीने का पीएमकेवीवाई मोबाइल हार्डवेयर कोर्स -> सर्विस सेंटर अनुभव -> स्वयं का रिपेयर सेंटर (मुद्रा ऋण)।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000030', 'en', 'HVAC & Refrigeration Technician', 'Installs, commissions, and services split/inverter air conditioners, deep freezers, cold storage units, and commercial HVAC plants.', 'Copper tube flaring and brazing, nitrogen leak testing, vacuum pump evacuation, R32/R410A refrigerant charging, and inverter PCB troubleshooting.', '10th Pass -> ITI RAC or PMKVY Field Technician AC -> NAPS Dealership Apprenticeship -> Independent HVAC Contractor.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000030', 'te', 'హెచ్‌వీఏసీ & రిఫ్రిజిరేషన్ టెక్నీషియన్ (AC & Fridge Mechanic)', 'స్ప్లిట్ ఇన్వర్టర్ ఏసీలు, రిఫ్రిజిరేటర్లు మరియు కోల్డ్ స్టోరేజ్ యూనిట్లను అమర్చి సర్వీసింగ్ చేసే సాంకేతిక నిపుణుడు.', 'కాపర్ పైపుల బ్రేజింగ్, గ్యాస్ లీకేజీ పరీక్ష, వాక్యూమ్ పంప్ వినియోగం, రిఫ్రిజెరాంట్ గ్యాస్ ఫిల్లింగ్ మరియు ఇన్వర్టర్ PCB రిపేర్.', '10వ తరగతి -> ఐటిఐ RAC లేదా PMKVY AC కోర్సు -> NAPS అప్రెంటిస్‌షిప్ -> సొంత సర్వీస్ సెంటర్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000030', 'hi', 'एचवीएसी और रेफ्रिजरेशन तकनीशियन (AC व फ्रिज मैकेनिक)', 'घरों, दुकानों और कोल्ड स्टोरेज में स्प्लिट/इन्वर्टर एसी, फ्रिज और कूलिंग सिस्टम की स्थापना व मरम्मत करता है।', 'कॉपर पाइप ब्रेजिंग, लीक टेस्टिंग, वैक्यूम करना, सुरक्षित रेफ्रिजरेंट गैस चार्जिंग और इन्वर्टर पीसीबी की जांच।', '10वीं पास -> आईटीआई आरएसी / पीएमकेवीवाई एसी कोर्स -> नैप्स अप्रेंटिसशिप -> स्वतंत्र एचवीएसी तकनीशियन।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000031', 'en', 'Dairy Farm & Livestock Supervisor', 'Manages scientific cattle nutrition, clean milking parlors, milk fat/SNF quality testing, silage preservation, and rural dairy cooperative collection centers.', 'Operating automatic milk analyzers, balancing green/dry fodder rations, maintaining cattle shed hygiene, and coordinating veterinary vaccination schedules.', '10th Pass -> Free RSETI / NDDB Dairy Entrepreneurship Training -> Cooperative Society Milk Tester or MUDRA Dairy Farm Unit.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000031', 'te', 'డెయిరీ ఫామ్ & పశుపోషణ పర్యవేక్షకుడు', 'పాల ఉత్పత్తి కేంద్రాలు, పశువుల దాణా సమతుల్యత, పాల కొవ్వు/SNF పరీక్షలు మరియు పాల సహకార సంఘాలను నిర్వహించే నిపుణుడు.', 'మిల్క్ అనలైజర్‌తో పాల నాణ్యత పరీక్ష, సైలేజ్ పశుగ్రాసం తయారీ, షెడ్ శుభ్రత మరియు వ్యాధి నిరోధక టీకాల నిర్వహణ.', '10వ తరగతి -> RSETI / NDDB ఉచిత డెయిరీ శిక్షణ -> పాల సేకరణ కేంద్రం లేదా ముద్ర లోన్ డెయిరీ ఫామ్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000031', 'hi', 'डेयरी फार्म और पशुधन पर्यवेक्षक', 'वैज्ञानिक पशु आहार, स्वच्छ दुग्ध उत्पादन, दूध की फैट/एसएनएफ जांच और ग्रामीण डेयरी सहकारी केंद्रों का संचालन करता है।', 'मिल्क एनालाइजर से दूध परीक्षण, हरा चारा व साइलेज प्रबंधन, पशुशाला स्वच्छता और टीकाकरण समन्वय।', '10वीं पास -> आरसेटी (RSETI) / एनडीडीबी डेयरी प्रशिक्षण -> दुग्ध संग्रह केंद्र या मुद्रा ऋण डेयरी व्यवसाय।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000032', 'en', 'EV Battery & Charging Station Technician', 'Installs, commissions, and maintains public AC/DC Electric Vehicle charging stations, high-voltage power electronics, and lithium battery packs.', 'Mounting Type-2 AC and CCS2 DC fast chargers, verifying chemical earthing and surge protection, configuring OCPP cloud connectivity, and BMS cell testing.', 'ITI Electrical / Diploma -> ASDC EV Charging Infrastructure Course -> NAPS Apprenticeship with CPOs -> Certified EV Infra Engineer.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000032', 'te', 'ఈవీ బ్యాటరీ & ఛార్జింగ్ స్టేషన్ టెక్నీషియన్', 'ఎలక్ట్రిక్ వాహనాల పబ్లిక్ AC/DC ఫాస్ట్ ఛార్జింగ్ స్టేషన్లు, హై-వోల్టేజ్ ఎలక్ట్రానిక్స్ మరియు లిథియం బ్యాటరీ ప్యాక్‌లను అమర్చి నిర్వహిస్తారు.', 'Type-2 AC & CCS2 DC ఛార్జర్ల ఏర్పాటు, ఎర్తింగ్ మరియు సర్జ్ ప్రొటెక్షన్ తనిఖీ, OCPP కనెక్టివిటీ మరియు BMS పరీక్షలు.', 'ఐటిఐ ఎలక్ట్రికల్ / డిప్లొమా -> ASDC EV ఛార్జింగ్ కోర్సు -> NAPS అప్రెంటిస్‌షిప్ -> ఈవీ ఛార్జింగ్ టెక్నీషియన్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000032', 'hi', 'ईवी बैटरी और चार्जिंग स्टेशन तकनीशियन', 'इलेक्ट्रिक वाहनों के पब्लिक एसी/डीसी फास्ट चार्जिंग स्टेशन, हाई-वोल्टेज पावर सिस्टम और लिथियम बैटरी पैक की स्थापना व रखरखाव करता है।', 'टाइप-2 और सीसीएस-2 चार्जर लगाना, अर्थिंग व सुरक्षा जांच, ओसीपीपी नेटवर्क सेटअप और बीएमएस सेल परीक्षण।', 'आईटीआई इलेक्ट्रिकल / डिप्लोमा -> एएसडीसी ईवी चार्जिंग प्रशिक्षण -> नैप्स अप्रेंटिसशिप -> प्रमाणित ईवी तकनीशियन।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000033', 'en', 'IT Helpdesk & Hardware Support Technician', 'Configures office desktops, installs Windows/Linux OS, resolves Wi-Fi/LAN network issues, manages printers, and handles L1 IT support tickets.', 'Troubleshooting hardware/OS crashes, crimping Ethernet RJ45 cables, configuring routers and email clients, and logging support tickets.', '12th Pass / ITI COPA -> Cisco IT Essentials & PMKVY Helpdesk Certification -> IT Support Internship -> System Administrator.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000033', 'te', 'ఐటీ హెల్ప్‌డెస్క్ & హార్డ్‌వేర్ సపోర్ట్ టెక్నీషియన్', 'కార్యాలయాల్లో కంప్యూటర్ హార్డ్‌వేర్, Windows/Linux OS ఇన్‌స్టాలేషన్, వై-ఫై/LAN నెట్‌వర్క్ సమస్యలు మరియు L1 IT సపోర్ట్ టికెట్లను పరిష్కరిస్తారు.', 'డెస్క్‌టాప్/ల్యాప్‌టాప్ రిపేర్, RJ45 నెట్‌వర్క్ కేబులింగ్, రౌటర్ & ప్రింటర్ సెటప్ మరియు యూజర్ టెక్నికల్ సపోర్ట్.', '12వ తరగతి / ITI COPA -> సిస్కో ఐటీ బేసిక్స్ సర్టిఫికెట్ -> IT ఇంటర్న్‌షిప్ -> సిస్టమ్ అడ్మినిస్ట్రేటర్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000033', 'hi', 'आईटी हेल्पडेस्क एवं हार्डवेयर सपोर्ट तकनीशियन', 'कार्यालयों में कंप्यूटर हार्डवेयर, विंडोज/लिनक्स ओएस, वाई-फाई/लैन नेटवर्क और प्रिंटर समस्याओं का समाधान करता है।', 'पीसी असेंबलिंग, नेटवर्क केबलिंग, राउटर सेटअप, सॉफ्टवेयर इंस्टॉलेशन और तकनीकी सहायता टिकट हल करना।', '12वीं पास / आईटीआई कोपा -> सिस्को आईटी एसेंशियल्स कोर्स -> आईटी सपोर्ट इंटर्नशिप -> सिस्टम एडमिनिस्ट्रेटर।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000034', 'en', 'Gramin Dak Sevak (India Post BPM / ABPM)', 'Manages village Branch Post Offices and delivers registered mail, India Post Payments Bank (IPPB) digital banking, and Sukanya Samriddhi savings schemes.', 'Operating Darpan handheld biometric devices, processing Aadhaar AePS cash payouts, booking speed post parcels, and promoting postal life insurance.', '10th Class High Score -> Online Application at indiapostgdsonline.gov.in -> Document Verification -> Promotion Exam to Postman / MTS.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000034', 'te', 'గ్రామీణ డాక్ సేవక్ (ఇండియా పోస్ట్ BPM / ABPM)', 'గ్రామ బ్రాంచ్ పోస్ట్ ఆఫీసులను నిర్వహిస్తూ ఉత్తరాలు, ఇండియా పోస్ట్ పేమెంట్స్ బ్యాంక్ (IPPB) డిజిటల్ బ్యాంకింగ్ మరియు పొదుపు ఖాతాల సేవలు అందిస్తారు.', 'దర్పణ్ బయోమెట్రిక్ పరికరం ద్వారా డబ్బు చెల్లింపులు, స్పీడ్ పోస్ట్ బుకింగ్, సుకన్య సమృద్ధి మరియు పోస్టల్ బీమా సేవలు.', '10వ తరగతి మెరిట్ -> indiapostgdsonline.gov.in లో దరఖాస్తు -> సర్టిఫికెట్ వెరిఫికేషన్ -> పోస్ట్‌మ్యాన్ / MTS ప్రమోషన్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000034', 'hi', 'ग्रामीण डाक सेवक (इंडिया पोस्ट BPM / ABPM)', 'ग्रामीण शाखा डाकघरों का संचालन करते हुए डाक वितरण, इंडिया पोस्ट पेमेंट्स बैंक (IPPB) और सुकन्या समृद्धि बचत योजना सेवाएं प्रदान करता है।', 'दर्पण हैंडहेल्ड डिवाइस चलाना, आधार एईपीएस (AePS) भुगतान, स्पीड पोस्ट बुकिंग और ग्रामीण डाक जीवन बीमा संभालना।', '10वीं कक्षा मेरिट -> indiapostgdsonline.gov.in आवेदन -> दस्तावेज़ सत्यापन -> विभागीय परीक्षा से पोस्टमैन पदोन्नति।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000035', 'en', 'Solar Water Pump & Micro-Irrigation Installer', 'Installs DC/AC solar agricultural water pumps (2HP to 10HP) under PM-KUSUM and integrates them directly with drip and sprinkler farm pipelines.', 'Erecting tracker solar mounting poles, lowering borewell submersible pumps, wiring solar VFD pump controllers, and tuning drip water discharge.', '10th Pass -> SCGJ Solar Water Pump Technician Course -> PM-KUSUM Vendor Field Team -> District Agri-Solar Contractor.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000035', 'te', 'సోలార్ వాటర్ పంప్ & మైక్రో-ఇరిగేషన్ ఇన్‌స్టాలర్', 'పీఎం-కుసుమ్ (PM-KUSUM) పథకం క్రింద వ్యవసాయ బోర్లకు సోలార్ వాటర్ పంపులను అమర్చి డ్రిప్/స్ప్రింక్లర్ పైపులతో అనుసంధానం చేస్తారు.', 'సోలార్ ప్యానెల్ స్టాండ్ నిర్మాణం, సబ్‌మెర్సిబుల్ పంప్ అమరిక, VFD కంట్రోలర్ వైరింగ్ మరియు డ్రిప్ నీటి ప్రెషర్ సెటప్.', '10వ తరగతి -> SCGJ సోలార్ పంప్ శిక్షణ -> PM-KUSUM కంపెనీలో ఫీల్డ్ ఉద్యోగం -> గ్రామీణ సోలార్ కాంట్రాక్టర్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000035', 'hi', 'सोलर वॉटर पंप और सूक्ष्म सिंचाई तकनीशियन', 'पीएम-कुसुम योजना के तहत खेतों में 2 से 10 एचपी सोलर कृषि पंप लगाता है और उन्हें ड्रिप व स्प्रिंकलर सिंचाई से जोड़ता है।', 'सोलर पैनल पोल लगाना, बोरवेल में सबमर्सिबल पंप उतारना, वीएफडी कंट्रोलर वायरिंग और ड्रिप पाइप प्रेशर सेट करना।', '10वीं पास -> एससीजीजे सोलर पंप कोर्स -> पीएम-कुसुम कंपनी में नौकरी -> कृषि-सोलर सेवा उद्यमी।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000036', 'en', 'Plumber & Rural Water Supply Technician (Nal Jal Mitra)', 'Installs and maintains HDPE rural pipeline networks, overhead water tank valves, domestic sanitary fittings, and tap connections under Jal Jeevan Mission.', 'Cutting and fusion-joining HDPE/UPVC pipelines, repairing leaking gate valves, checking residual chlorine levels, and installing household water meters.', '10th Pass -> Free Jal Jeevan Mission Nal Jal Mitra / ITI Plumber -> Gram Panchayat Maintenance Contract or Private Plumbing Contractor.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000036', 'te', 'ప్లంబర్ & గ్రామీణ నీటి సరఫరా టెక్నీషియన్ (నల్ జల్ మిత్ర)', 'జల్ జీవన్ మిషన్ (హర్ ఘర్ జల్) క్రింద గ్రామ పైప్‌లైన్లు, ఓవర్‌హెడ్ ట్యాంక్ వాల్వ్‌లు మరియు ఇంటింటి కుళాయి కనెక్షన్లను నిర్వహిస్తారు.', 'HDPE & UPVC పైపుల జాయింటింగ్, లీకేజీ మరమ్మతు, నీటి శుద్ధత క్లోరినేషన్ పరీక్ష మరియు ఇంటి నల్లా ఫిట్టింగ్‌లు.', '10వ తరగతి -> ఉచిత నల్ జల్ మిత్ర / ఐటిఐ ప్లంబర్ శిక్షణ -> గ్రామ పంచాయతీ నీటి సరఫరా టెక్నీషియన్.') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_translations (career_id, language_code, title, description, job_responsibilities, pathway_summary) VALUES ('a1000000-0000-0000-0000-000000000036', 'hi', 'प्लंबर एवं ग्रामीण जल आपूर्ति तकनीशियन (नल जल मित्र)', 'जल जीवन मिशन के अंतर्गत ग्रामीण पेयजल पाइपलाइन नेटवर्क, ओवरहेड टैंक वाल्व और घरेलू नल कनेक्शन की स्थापना व रखरखाव करता है।', 'एचडीपीई/यूपीवीसी पाइप जोड़ना, लीकेज सुधारना, क्लोरीनेशन जांच करना और घरेलू नल व सैनिटरी फिटिंग लगाना।', '10वीं पास -> मुफ्त नल जल मित्र / आईटीआई प्लंबर कोर्स -> ग्राम पंचायत जल रखरखाव व अनुबंध रोजगार।') ON CONFLICT (career_id, language_code) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, job_responsibilities = EXCLUDED.job_responsibilities, pathway_summary = EXCLUDED.pathway_summary;
INSERT INTO public.career_skills (career_id, skill_id, importance) VALUES ('a1000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000130', 'recommended') ON CONFLICT (career_id, skill_id) DO UPDATE SET importance = EXCLUDED.importance;
INSERT INTO public.career_skills (career_id, skill_id, importance) VALUES ('a1000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000010', 'recommended') ON CONFLICT (career_id, skill_id) DO UPDATE SET importance = EXCLUDED.importance;
