INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000006', 'Personalized Frontend Developer Learning Pathway', 7, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000011', r.id, 1, 'Web Fundamentals & Semantic HTML5', 'वेब फंडामेंटल्स और सिमेंटिक HTML5', 'వెబ్ బేసిక్స్ & సిమాంటిక్ HTML5', 'Understand how the internet, DNS, HTTP, and browser rendering work. Master semantic HTML tags, accessible forms, audio/video embeds, and SEO markup.', 'इंटरनेट और ब्राउज़र कैसे काम करते हैं समझें। सिमेंटिक HTML टैग, फॉर्म, ऑडियो/वीडियो और एसईओ मार्कअप सीखें।', 'ఇంటర్నెట్ మరియు బ్రౌజర్ ఎలా పనిచేస్తాయో తెలుసుకోండి. సిమాంటిక్ HTML ట్యాగ్‌లు, ఫారమ్‌లు మరియు యాక్సెసిబిలిటీ నేర్చుకోండి.', 'Build a Personal Bio & Registration Form Page', '["Skill India Digital Hub Free Web Certification"]'::jsonb, '["HTTP client-server model","Semantic HTML5 tags (header, nav, main, article)","Accessible web forms & input validation","SEO meta tags"]'::jsonb, '3 Weeks', '[{"title":"freeCodeCamp: Responsive Web Design - HTML","url":"https://www.freecodecamp.org/learn/2022/responsive-web-design","provider":"freeCodeCamp","is_free":true},{"title":"MDN Web Docs: HTML Basics","url":"https://developer.mozilla.org/en-US/docs/Learn/HTML","provider":"MDN","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000006' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000012', r.id, 2, 'CSS3, Modern Flexbox & Responsive Grid', 'CSS3, फ्लेक्सबॉक्स और रिस्पॉन्सिव ग्रिड डिज़ाइन', 'CSS3, ఫ్లెక్స్‌బాక్స్ & రెస్పాన్సివ్ గ్రిడ్ డిజైన్', 'Master CSS selectors, Box Model, Flexbox alignment, CSS Grid, media queries for mobile-first layouts, and modern CSS variables.', 'सीएसएस बॉक्स मॉडल, फ्लेक्सबॉक्स, सीएसएस ग्रिड और मोबाइल-फर्स्ट रिस्पॉन्सिव लेआउट्स में महारत हासिल करें।', 'బాక్స్ మోడల్, ఫ్లెక్స్‌బాక్స్, గ్రిడ్ మరియు మొబైల్ అనుకూల లేఅవుట్‌లను రూపొందించడంలో నైపుణ్యం సాధించండి.', 'Style a Responsive Multi-Column Product Landing Page', '[]'::jsonb, '["CSS Box Model (margin, border, padding)","Flexbox layout and axis alignment","CSS Grid 2D layout systems","Mobile-first media queries"]'::jsonb, '3 Weeks', '[{"title":"freeCodeCamp: CSS Flexbox & Grid Labs","url":"https://www.freecodecamp.org/learn/2022/responsive-web-design","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000006' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000013', r.id, 3, 'JavaScript Core: Logic, DOM Manipulation & Fetch API', 'जावास्क्रिप्ट कोर: लॉजिक, डीओएम और फेच एपीआई', 'జావాస్క్రిప్ట్ కోర్: లాజిక్, DOM మానిప్యులేషన్ & Fetch API', 'Learn variables, data structures (arrays/objects), ES6 arrow functions, array methods (map, filter, reduce), DOM events, and async fetch requests.', 'वेरिएबल्स, एरे/ऑब्जेक्ट्स, ES6 फीचर्स, इवेंट हैंडलिंग, प्रॉमिस और फेच एपीआई के जरिए लाइव डेटा लाना सीखें।', 'వేరియబుల్స్, అర్రే మెథడ్స్, DOM ఈవెంట్లు, అసింక్రోనస్ ప్రామిసెస్ మరియు లైవ్ API కాల్స్ చేయడం నేర్చుకోండి.', 'Build an Interactive Weather / Currency Converter App', '[]'::jsonb, '["ES6+ syntax & scope","Array transformation (map, filter, reduce)","DOM selection and event listeners","Async/Await & REST API fetch calls"]'::jsonb, '4 Weeks', '[{"title":"freeCodeCamp: JavaScript Algorithms & Data Structures","url":"https://www.freecodecamp.org/learn/javascript-algorithms-and-data-structures-v8","provider":"freeCodeCamp","is_free":true},{"title":"MDN Web Docs: JavaScript Guide","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide","provider":"MDN","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000006' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000014', r.id, 4, 'Version Control with Git & Collaborative GitHub', 'गिट (Git) और गिटहब (GitHub) से वर्जन कंट्रोल', 'గిట్ (Git) & గిట్‌హబ్ (GitHub) ద్వారా కోడ్ నిర్వహణ', 'Initialize repositories, write meaningful commit messages, branch features, resolve merge conflicts, and collaborate using GitHub pull requests.', 'गिट रिपॉजिटरी बनाना, कमिट, ब्रांचिंग, मर्ज कॉन्फ्लिक्ट्स सुलझाना और गिटहब पर कोड होस्ट करना सीखें।', 'రిపోజిటరీలను సృష్టించడం, బ్రాంచ్‌లు తయారు చేయడం, కోడ్ పుష్ చేయడం మరియు ప్రాజెక్ట్ సహకారం అందించడం.', 'Publish your project repositories on GitHub with Markdown READMEs', '[]'::jsonb, '["Git commands (init, add, commit, push, pull)","Branching, merging, and PR reviews","Hosting projects on GitHub Pages","README documentation"]'::jsonb, '2 Weeks', '[{"title":"freeCodeCamp: Git and GitHub for Beginners","url":"https://www.freecodecamp.org/news/git-and-github-for-beginners","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000006' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000015', r.id, 5, 'React.js Component Architecture, State & Hooks', 'रिएक्ट (React.js): कॉम्पोनेंट्स, स्टेट और हुक्स', 'రియాక్ట్ (React.js): కాంపోనెంట్లు, స్టేట్ & హుక్స్', 'Build single-page web applications using React functional components, JSX, props, useState, useEffect, custom hooks, and React Router.', 'रिएक्ट कॉम्पोनेंट्स, जेएसएक्स, स्टेट मैनेजमेंट, कस्टम हुक्स और मल्टी-पेज नेविगेशन सीखें।', 'ఫంక్షనల్ కాంపోనెంట్లు, స్టేట్ నిర్వహణ, useEffect మరియు పేజీ నావిగేషన్ నేర్చుకోండి.', 'Build an E-Commerce Cart or Interactive Job Search Board', '[]'::jsonb, '["Functional components & JSX syntax","Props and State management with useState","Side-effects & lifecycle with useEffect","Client-side routing with React Router"]'::jsonb, '4 Weeks', '[{"title":"React Official Documentation (Learn React)","url":"https://react.dev/learn","provider":"React Open Source","is_free":true},{"title":"freeCodeCamp: React Full Tutorial","url":"https://www.freecodecamp.org/news/learn-react-course","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000006' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000016', r.id, 6, 'Production Projects & Responsive Design Optimization', 'लाइव प्रोजेक्ट्स और परफॉर्मेंस ऑप्टिमाइजेशन', 'లైవ్ ప్రాజెక్ట్‌లు & పెర్ఫార్మెన్స్ ఆప్టిమైజేషన్', 'Build full production-ready web apps with Tailwind CSS or CSS Modules, clean UI states (loading, empty, error), and deploy to Vercel/Netlify.', 'लोडिंग और एरर स्टेट्स के साथ संपूर्ण प्रोडक्शन ऐप्स बनाएं और उन्हें वर्सेल/नेटलिफाई पर ऑनलाइन होस्ट करें।', 'పూర్తి స్థాయి లైవ్ వెబ్ ప్రాజెక్ట్‌ను పూర్తి చేసి క్లౌడ్‌లో (Vercel/Netlify) హోస్ట్ చేయండి.', 'Deploy two fully functional portfolio projects on custom URLs', '[]'::jsonb, '["Styling with Tailwind CSS / CSS Modules","Handling async loading and error UI states","Lighthouse web performance optimization","Free cloud continuous deployment (Vercel/Netlify)"]'::jsonb, '3 Weeks', '[{"title":"Vercel Deployment Guide","url":"https://vercel.com/docs","provider":"Vercel","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000006' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000017', r.id, 7, 'Portfolio Showcase, Resume & Internship Applications', 'पोर्टफोलियो वेबसाइट, रिज्यूमे और इंटर्नशिप आवेदन', 'పోర్ట్‌ఫోలియో వెబ్‌సైట్, రెజ్యూమ్ & ఇంటర్న్‌షిప్ అప్లికేషన్లు', 'Design a clean developer portfolio showcasing your deployed apps, draft an ATS-friendly technical resume, and apply on Internshala, LinkedIn, and NCS.', 'एक शानदार डेवलपर पोर्टफोलियो बनाएं, तकनीकी रिज्यूमे तैयार करें और इंटर्नशाला और लिंक्डइन पर आवेदन करें।', 'మీ ప్రాజెక్ట్‌లతో కూడిన పోర్ట్‌ఫోలియో సైట్ తయారు చేసి, ఇంటర్న్‌షిప్‌లకు దరఖాస్తు చేసుకోండి.', 'Apply to verified Junior Frontend internships and track applications', '["NAPS 2.0 Apprenticeship Stipend","AICTE Internship Schemes"]'::jsonb, '["Hosting a live developer portfolio site","ATS-friendly software resume formatting","Technical interview coding challenges","Applying to 10+ entry-level internships"]'::jsonb, '2 Weeks', '[{"title":"Internshala Frontend Internships","url":"https://internshala.com","provider":"Internshala","is_free":true},{"title":"National Career Service Portal","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000006' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000007', 'Personalized Backend Developer Learning Pathway', 7, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000021', r.id, 1, 'Backend Fundamentals, HTTP Protocol & Node.js Runtime', 'बैकएंड फंडामेंटल्स और नोड.जेएस (Node.js) रनटाइम', 'బ్యాకెండ్ బేసిక్స్ & నోడ్ జెఎస్ (Node.js) రన్‌టైమ్', 'Understand client-server architecture, HTTP request/response headers, status codes, asynchronous event loop, and Node.js file system/streams.', 'क्लाइंट-सर्वर मॉडल, एचटीटीपी स्टेटस कोड, नोड इवेंट लूप और फाइल सिस्टम सीखें।', 'సర్వర్ నిర్మాణం, HTTP స్టేటస్ కోడ్‌లు, నోడ్ ఈవెంట్ లూప్ మరియు మాడ్యూల్స్ నేర్చుకోండి.', 'Build a command-line file processing and logging utility in Node', '[]'::jsonb, '["HTTP protocol (GET, POST, PUT, DELETE)","Node.js event loop & non-blocking I/O","Node Core Modules (fs, path, http)","npm package management"]'::jsonb, '3 Weeks', '[{"title":"Node.js Official Documentation","url":"https://nodejs.org/en/docs","provider":"Node.js Foundation","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000007' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000022', r.id, 2, 'RESTful API Engineering with Express.js Framework', 'एक्सप्रेस जेएस (Express.js) से RESTful API निर्माण', 'ఎక్స్‌ప్రెస్ జెఎస్ (Express.js) తో REST API ల రూపకల్పన', 'Design modular REST APIs in Express.js, implement custom routing, middleware pipeline, request validation with Zod, and centralized error handling.', 'एक्सप्रेस में मॉड्यूलर एपीआई बनाएं, मिडलवेयर पाइपलाइन, डेटा वैलिडेशन और त्रुटि प्रबंधन सीखें।', 'ఎక్స్‌ప్రెస్‌లో REST API లను డిజైన్ చేయడం, మిడిల్‌వేర్ రాయడం మరియు ఎర్రర్ హ్యాండ్లింగ్ నేర్చుకోండి.', 'Build an Express CRUD API with input validation and automated tests', '[]'::jsonb, '["Express routing & URL parameters","Middleware creation (auth, logging, rate-limiting)","Payload validation using Zod/Joi","Consistent JSON error responses"]'::jsonb, '3 Weeks', '[{"title":"MDN: Express/Node introduction","url":"https://developer.mozilla.org/en-US/docs/Learn/Server-side/Express_Nodejs","provider":"MDN","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000007' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000023', r.id, 3, 'Relational Database Design with PostgreSQL & SQL', 'पोस्टग्रेएसक्यूएल (PostgreSQL) और डेटाबेस डिज़ाइन', 'పోస్ట్‌గ్రేఎస్క్యుఎల్ (PostgreSQL) & రిలేషనల్ డేటాబేస్ డిజైన్', 'Master relational schema design, 1:1, 1:N and N:M foreign key relationships, indexes, ACID transactions, complex joins, and query optimization.', 'रिलेशनल डेटाबेस स्कीमा, विदेशी कुंजियाँ (Foreign Keys), इंडेक्सिंग, एसीआईडी लेनदेन और जटिल जॉइन्स सीखें।', 'టేబుల్స్ డిజైన్ చేయడం, ఫారిన్ కీలు, ఇండెక్సింగ్, ట్రాన్సాక్షన్స్ మరియు SQL జాయిన్స్ నేర్చుకోండి.', 'Design and populate a normalized relational database schema for a hospital or school', '[]'::jsonb, '["Data normalization (1NF, 2NF, 3NF)","Complex multi-table SQL queries (INNER, LEFT JOIN)","Indexes and query execution plans","ACID transactions and row locking"]'::jsonb, '4 Weeks', '[{"title":"freeCodeCamp: Relational Database Course","url":"https://www.freecodecamp.org/learn/relational-database","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000007' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000024', r.id, 4, 'Authentication, Security & Password Hashing', 'प्रमाणीकरण (Authentication), पासवर्ड सुरक्षा और टोकन', 'ఆథెంటికేషన్, భద్రత & పాస్‌వర్డ్ హాషింగ్ (JWT & Bcrypt)', 'Implement secure user registration, bcrypt password hashing, JSON Web Token (JWT) session generation, role-based access control (RBAC), and CORS protection.', 'उपयोगकर्ता सुरक्षा, bcrypt पासवर्ड हैशिंग, JWT टोकन सत्यापन और भूमिका-आधारित एक्सेस कंट्रोल सीखें।', 'యూజర్ రిజిస్ట్రేషన్, పాస్‌వర్డ్ సెక్యూరిటీ, JWT టోకెన్ వెరిఫికేషన్ మరియు రోల్ బేస్డ్ యాక్సెస్ అమలు చేయండి.', 'Implement a secure auth microservice with register, login, refresh, and role protection', '[]'::jsonb, '["Salted password hashing with bcrypt","JWT creation, expiry, and signature verification","Role-Based Access Control (RBAC) middleware","CORS, helmet, and rate-limiting security headers"]'::jsonb, '3 Weeks', '[{"title":"OWASP REST Security Cheat Sheet","url":"https://cheatsheetseries.owasp.org","provider":"OWASP","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000007' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000025', r.id, 5, 'ORMs, Database Migrations & Database Pooling', 'ओआरएम (Prisma/TypeORM) और डेटाबेस माइग्रेशन', 'ORM (Prisma/Drizzle) & డేటాబేస్ మైగ్రేషన్లు', 'Learn modern Object-Relational Mappers (Prisma or Drizzle), manage declarative database migrations, and handle connection pooling for high concurrency.', 'प्रिज्मा ओआरएम, स्कीमा माइग्रेशन और डेटाबेस कनेक्शन पूलिंग में दक्षता प्राप्त करें।', 'ORM టూల్స్ ద్వారా టైప్-సేఫ్ డేటాబేస్ క్వెరీలు మరియు మైగ్రేషన్స్ నిర్వహించడం.', 'Refactor an Express API to use Prisma ORM and automated migrations', '[]'::jsonb, '["Type-safe querying with Prisma/Drizzle","Declarative schema migrations","Connection pool configuration","Automated seed data scripts"]'::jsonb, '3 Weeks', '[{"title":"Prisma Getting Started Guide","url":"https://www.prisma.io/docs","provider":"Prisma","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000007' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000026', r.id, 6, 'Linux Server Administration, Docker & Cloud Deployment', 'लिनक्स सर्वर, डॉकर (Docker) और क्लाउड डिप्लॉयमेंट', 'లైనక్స్ సర్వర్, డాకర్ (Docker) & క్లౌడ్ హోస్టింగ్', 'Containerize backend applications with Docker multi-stage builds, manage environment variables, and deploy to AWS EC2 or Render cloud servers.', 'डॉकर के साथ ऐप्स को कंटेनराइज करें, एनवायरनमेंट वेरिएबल्स प्रबंधित करें और क्लाउड पर डिप्लॉय करें।', 'డాకర్ కంటైనర్లను నిర్మించడం మరియు క్లౌడ్ సర్వర్లలో బ్యాకెండ్ API లను రన్ చేయడం.', 'Deploy a live Dockerized Express + PostgreSQL API to a public cloud URL', '[]'::jsonb, '["Dockerfile creation and multi-stage builds","Docker compose for app + PostgreSQL database","Linux systemd and PM2 process manager","Free tier cloud hosting (Render/Railway/AWS)"]'::jsonb, '3 Weeks', '[{"title":"Docker Official Getting Started","url":"https://docs.docker.com/get-started","provider":"Docker","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000007' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000027', r.id, 7, 'API Documentation (Swagger/OpenAPI) & Job Applications', 'एपीआई दस्तावेज़ीकरण और बैकएंड नौकरी आवेदन', 'API డాక్యుమెంటేషన్ (Swagger) & ఉద్యోగ దరఖాస్తులు', 'Document your APIs using OpenAPI / Swagger interactive UI, test with Postman collections, build your backend portfolio, and apply for junior roles.', 'स्वैगर के साथ इंटरएक्टिव एपीआई दस्तावेज बनाएं, पोस्टमैन कलेक्शन साझा करें और नौकरी आवेदन करें।', 'Swagger ద్వారా మీ API లను డాక్యుమెంట్ చేసి, జూనియర్ బ్యాకెండ్ ఉద్యోగాలకు దరఖాస్తు చేయండి.', 'Share an interactive Swagger documentation link and Postman collection with recruiters', '["NAPS Apprenticeship Scheme"]'::jsonb, '["OpenAPI 3.0 specification & Swagger UI","Postman test suites & environment variables","System design interview fundamentals","Applying to 15+ backend developer openings"]'::jsonb, '2 Weeks', '[{"title":"NCS IT Job Listings","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true},{"title":"Foundit India Tech Jobs","url":"https://www.foundit.in","provider":"Foundit","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000007' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000010', 'Personalized Data Analyst Learning Pathway', 7, '5 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000031', r.id, 1, 'Advanced Microsoft Excel for Business Analytics', 'बिजनेस एनालिटिक्स के लिए एडवांस्ड माइक्रोसॉफ्ट एक्सेल', 'బిజినెస్ అనలిటిక్స్ కోసం అడ్వాన్స్‌డ్ ఎక్సెల్', 'Master XLOOKUP, INDEX/MATCH, dynamic array formulas, nested IF-AND logic, conditional formatting, and interactive Pivot Tables.', 'XLOOKUP, इंडेक्स-मैच, डायनामिक फॉर्मूले और पिवट टेबल्स द्वारा व्यावसायिक डेटा विश्लेषण सीखें।', 'XLOOKUP, పివోట్ టేబుల్స్ మరియు డేటా అనాలిసిస్ ఫార్ములాలను సమగ్రంగా నేర్చుకోండి.', 'Build an automated sales tracking spreadsheet with interactive pivot charts', '[]'::jsonb, '["Lookup formulas (XLOOKUP, INDEX-MATCH)","Pivot Tables and Pivot Charts","Data validation and error checking","Building automated financial spreadsheets"]'::jsonb, '3 Weeks', '[{"title":"Microsoft Excel Training Center","url":"https://support.microsoft.com/en-us/excel","provider":"Microsoft","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000010' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000032', r.id, 2, 'SQL for Data Analysis & Business Intelligence', 'डेटा विश्लेषण और रिपोर्टिंग के लिए एसक्यूएल (SQL)', 'డేటా అనాలిసిస్ & బిజినెస్ ఇంటెలిజెన్స్ కోసం SQL', 'Extract and aggregate enterprise records using SELECT, WHERE, GROUP BY, HAVING, subqueries, and window functions (ROW_NUMBER, RANK, LAG).', 'एसक्यूएल क्वेरीज़, ग्रुप बाय, विंडो फंक्शंस और डेटाबेस से सार्थक रिपोर्ट निकालना सीखें।', 'SQL క్వెరీలు, జాయిన్స్, సబ్‌క్వెరీలు మరియు విండో ఫంక్షన్ల ద్వారా నివేదికలు తయారు చేయండి.', 'Answer 25 complex business questions using SQL queries on a retail dataset', '[]'::jsonb, '["Data aggregation & GROUP BY filters","Multi-table INNER and OUTER joins","Window functions (RANK, DENSE_RANK, OVER)","Common Table Expressions (CTEs)"]'::jsonb, '3 Weeks', '[{"title":"freeCodeCamp: SQL for Beginners","url":"https://www.freecodecamp.org/news/sql-and-databases-full-course","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000010' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000033', r.id, 3, 'Applied Business Statistics & Exploratory Data Analysis', 'व्यावसायिक सांख्यिकी और डेटा एक्सप्लोरेशन', 'బిజినెస్ స్టాటిస్టిక్స్ & ఎక్స్‌ప్లోరేటరీ డేటా అనాలిసిస్', 'Understand central tendency, standard deviation, normal distributions, correlation vs causation, hypothesis testing, and A/B test analysis.', 'माध्य, विचलन, सामान्य वितरण, सहसंबंध और परिकल्पना परीक्षण (A/B टेस्टिंग) के नियम समझें।', 'మీన్, స్టాండర్డ్ డీవియేషన్, కోరిలేషన్ మరియు ప్రాబబిలిటీ కాన్సెప్ట్‌లను నేర్చుకోండి.', 'Conduct statistical correlation analysis on customer churn data', '[]'::jsonb, '["Descriptive statistics metrics","Probability distributions and percentiles","Correlation coefficients and scatter trends","Hypothesis testing and p-values"]'::jsonb, '3 Weeks', '[{"title":"Khan Academy: High School Statistics","url":"https://www.khanacademy.org/math/statistics-probability","provider":"Khan Academy","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000010' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000034', r.id, 4, 'Python for Data Analysis (Pandas & NumPy)', 'पायथन फॉर डेटा एनालिसिस (Pandas और NumPy)', 'డేటా అనాలిసిస్ కోసం పైథాన్ (Pandas & NumPy)', 'Read and clean dirty datasets using Pandas DataFrames, handle null values, format dates, and perform group aggregations in Jupyter Notebooks.', 'जुपीटर नोटबुक में पांडास और नम्पाय द्वारा डेटा क्लीनिंग, डेटा फिल्टरिंग और ट्रांसफॉर्मेशन सीखें।', 'పాండాస్ మరియు నంపై ద్వారా డేటాను ఫిల్టర్ చేయడం, శుభ్రపరచడం మరియు విశ్లేషించడం.', 'Clean and explore an Indian Census or Agriculture dataset in Jupyter Notebook', '[]'::jsonb, '["NumPy arrays and vectorized calculations","Pandas DataFrame manipulation and filtering","Handling missing data and data type casting","Grouping, pivoting, and merging dataframes"]'::jsonb, '4 Weeks', '[{"title":"NPTEL: Data Analytics with Python","url":"https://nptel.ac.in/courses/106107220","provider":"NPTEL","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000010' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000035', r.id, 5, 'Data Visualization & Storytelling (Matplotlib & Seaborn)', 'डेटा विज़ुअलाइज़ेशन और चार्ट्स (Matplotlib व Seaborn)', 'డేటా విజువలైజేషన్ & చార్ట్‌ల రూపకల్పన (Matplotlib & Seaborn)', 'Choose the correct chart for the question: bar charts, histograms, heatmaps, box plots, and line charts with clear labeling and color theory.', 'प्रभावी चार्ट चुनना, हीटमैप्स, बॉक्स प्लॉट्स और विजुअल रिपोर्टिंग के जरिए निष्कर्ष समझाना।', 'సరైన చార్ట్‌లను ఎంచుకోవడం, హీట్‌మ్యాప్స్ మరియు గ్రాఫ్‌ల ద్వారా డేటాను దృశ్యరూపంలో చూపించడం.', 'Create an infographic report showing socio-economic trends in rural districts', '[]'::jsonb, '["Principles of visual data storytelling","Plotting categorical and continuous variables","Heatmaps for correlation matrices","Exporting high-resolution presentation charts"]'::jsonb, '2 Weeks', '[{"title":"freeCodeCamp: Data Analysis with Python","url":"https://www.freecodecamp.org/learn/data-analysis-with-python","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000010' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000036', r.id, 6, 'Business Intelligence Dashboards with Microsoft Power BI', 'माइक्रोसॉफ्ट पावर बीआई (Power BI) से इंटरएक्टिव डैशबोर्ड', 'పవర్ బిఐ (Power BI) ద్వారా ఇంటరాక్టివ్ డాష్‌బోర్డులు', 'Model data schemas in Power BI, write DAX measure calculations (CALCULATE, SUMX, RELATED), and publish responsive executive dashboards.', 'पावर बीआई में डेटा मॉडलिंग, डैक्स (DAX) फॉर्मूले लिखना और लाइव डैशबोर्ड बनाना सीखें।', 'పవర్ బిఐ లో డేటా మోడలింగ్, DAX సూత్రాలు మరియు ఇంటరాక్టివ్ డాష్‌బోర్డులను పబ్లిష్ చేయడం.', 'Publish an interactive multi-tab Power BI portfolio dashboard on GitHub / NovyPro', '[]'::jsonb, '["Power Query ETL data transformation","Star schema data relationships","DAX measures and calculated columns","Interactive slicers, drill-throughs, and KPIs"]'::jsonb, '3 Weeks', '[{"title":"Microsoft Learn: Power BI Analyst Path","url":"https://learn.microsoft.com/training/paths/data-analytics-microsoft","provider":"Microsoft","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000010' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000037', r.id, 7, 'Analytics Portfolio & Job Placement Applications', 'डेटा एनालिस्ट पोर्टफोलियो और नौकरी आवेदन', 'డేటా అనలిస్ట్ పోర్ట్‌ఫోలియో & రిక్రూట్‌మెంట్ దరఖాస్తులు', 'Document your analytical case studies on GitHub and LinkedIn, prepare for SQL whiteboard questions, and apply for Junior Data Analyst openings.', 'गिटहब पर केस स्टडीज साझा करें, एसक्यूएल इंटरव्यू की तैयारी करें और नौकरियों के लिए आवेदन करें।', 'మీ విశ్లేషణ కేస్ స్టడీలను గిట్‌హబ్‌లో పోస్ట్ చేసి, అనలిస్ట్ ఉద్యోగాలకు అప్లై చేయండి.', 'Apply to verified Junior Data Analyst positions with your Power BI portfolio link', '["NAPS Apprenticeship in IT/ITeS"]'::jsonb, '["Writing business problem-solving case studies","SQL technical screening test mastery","Communicating quantitative insights clearly","Applying on Naukri, Indeed, and LinkedIn"]'::jsonb, '2 Weeks', '[{"title":"Naukri.com Data Analyst Jobs","url":"https://www.naukri.com","provider":"Naukri","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000010' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000012', 'Personalized Cybersecurity Analyst Learning Pathway', 7, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000041', r.id, 1, 'Computer Networking Architecture & Protocol Analysis', 'कंप्यूटर नेटवर्किंग और प्रोटोकॉल विश्लेषण (Wireshark)', 'కంప్యూటర్ నెట్‌వర్కింగ్ & ప్రోటోకాల్ అనాలిసిస్', 'Understand the OSI 7-layer model, TCP/IP handshake, IP addressing, Subnetting, DNS, DHCP, and inspect live packet traffic using Wireshark.', 'ओएसआई 7-लेयर मॉडल, टीसीपी/आईपी, सबनेटिंग, डीएनएस और वायरशार्क से नेटवर्क ट्रैफिक जांचना सीखें।', 'OSI మోడల్, IP అడ్రసింగ్, సబ్‌నెట్టింగ్ మరియు Wireshark ద్వారా నెట్‌వర్క్ ప్యాకెట్లను విశ్లేషించడం.', 'Capture and analyze an HTTP vs HTTPS network handshake in Wireshark', '[]'::jsonb, '["OSI and TCP/IP stack fundamentals","IPv4 addressing and CIDR notation","Wireshark packet capture and protocol inspection","Network troubleshooting tools (ping, traceroute, netstat)"]'::jsonb, '4 Weeks', '[{"title":"Cisco Networking Academy: Networking Basics","url":"https://www.netacad.com/courses/networking/networking-basics","provider":"Cisco","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000012' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000042', r.id, 2, 'Linux Operating System Administration & Shell Security', 'लिनक्स ऑपरेटिंग सिस्टम और शेल सुरक्षा', 'లైనక్స్ ఆపరేటింగ్ సిస్టమ్ & సెక్యూరిటీ కాన్ఫిగరేషన్', 'Install and configure Linux (Ubuntu/Debian), master terminal navigation, file permissions (chmod, chown), user accounts, and SSH key authentication.', 'लिनक्स टर्मिनल कमांड्स, फाइल अनुमतियां, उपयोगकर्ता प्रबंधन और एसएसएच सुरक्षा सीखें।', 'లైనక్స్ కమాండ్లు, ఫైల్ పర్మిషన్లు, యూజర్ అకౌంట్స్ మరియు SSH సెక్యూరిటీ నిర్వహణ.', 'Set up an Ubuntu virtual machine with hardened SSH and UFW firewall rules', '[]'::jsonb, '["Linux directory hierarchy and bash navigation","Permissions and ownership (chmod, chown, sudo)","SSH key-pair authentication and firewall (ufw)","Process monitoring and cron automation"]'::jsonb, '3 Weeks', '[{"title":"Linux Journey Interactive Guide","url":"https://linuxjourney.com","provider":"Linux Journey","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000012' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000043', r.id, 3, 'Cyber Threat Landscapes, Malware & CIA Triad', 'साइबर खतरे, मैलवेयर और सीआईए ट्रायड (CIA Triad)', 'సైబర్ ముప్పులు, మాల్వేర్ & CIA ట్రైయాడ్ భద్రత', 'Learn the core CIA triad (Confidentiality, Integrity, Availability), common attack vectors (Phishing, Ransomware, Man-in-the-Middle, DDoS), and mitigation.', 'सीआईए ट्रायड, फ़िशिंग, रैंसमवेयर, डीडीओएस और सामान्य साइबर हमलों से बचाव के तरीके सीखें।', 'కాన్ఫిడెన్షియాలిటీ, ఇంటిగ్రిటీ, అవైలబిలిటీ మరియు హ్యాకింగ్ దాడుల రకాలు, వాటి నివారణ.', 'Conduct a simulated phishing detection audit and document findings', '[]'::jsonb, '["CIA Triad and defence-in-depth principles","Social engineering, phishing, and payload delivery","Malware categories (worms, trojans, ransomware)","Basic cryptography (symmetric, asymmetric, hashing)"]'::jsonb, '3 Weeks', '[{"title":"Cisco: Introduction to Cybersecurity","url":"https://www.netacad.com/courses/cybersecurity/introduction-cybersecurity","provider":"Cisco","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000012' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000044', r.id, 4, 'Security Information & Event Management (SIEM) Monitoring', 'एसआईईएम (SIEM) लॉग निगरानी और सुरक्षा विश्लेषण', 'SIEM సెక్యూరిటీ లాగ్ పర్యవేక్షణ & విశ్లేషణ (Splunk/Wazuh)', 'Set up open-source SIEM platforms (Splunk / Wazuh / ELK), ingest auth and system logs, write detection queries, and identify suspicious brute-force attempts.', 'स्प्लंक या वज़ूह में सुरक्षा लॉग्स का विश्लेषण करना, संदिग्ध गतिविधियों को पहचानना और अलर्ट बनाना।', 'సిస్టమ్ లాగ్స్ విశ్లేషించడం, అనుమానాస్పద సైబర్ దాడులను గుర్తించడం మరియు అలర్ట్స్ రూపొందించడం.', 'Identify 5 unauthorized SSH brute-force attempts in a sample Wazuh log file', '[]'::jsonb, '["Log collection and aggregation protocols (Syslog)","Writing search queries to detect unauthorized logins","Building SOC incident dashboards","Creating automated detection alert triggers"]'::jsonb, '4 Weeks', '[{"title":"TryHackMe: SOC Level 1 Learning Path","url":"https://tryhackme.com","provider":"TryHackMe","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000012' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000045', r.id, 5, 'Vulnerability Assessment & Network Scanning (Nmap & Nessus)', 'कमजोरी मूल्यांकन और नेटवर्क स्कैनिंग (Nmap)', 'నెట్‌వర్క్ స్కానింగ్ & వల్నరబిలిటీ అసెస్‌మెంట్ (Nmap)', 'Scan authorized lab targets using Nmap, identify open ports, service versions, outdated software versions, and perform vulnerability scoring (CVSS).', 'Nmap से नेटवर्क पोर्ट स्कैनिंग, पुरानी सर्विस पहचानना और सीवीएसएस स्कोरिंग सीखना।', 'Nmap ద్వారా ఓపెన్ పోర్టులను స్కాన్ చేయడం, సెక్యూరిటీ లోపాలను గుర్తించడం మరియు CVSS రేటింగ్ ఇవ్వడం.', 'Run a vulnerability assessment report on an authorized lab virtual machine', '[]'::jsonb, '["Nmap scanning flags (SYN scan, version detect, OS probe)","Understanding CVE and CVSS vulnerability metrics","Remediation patch recommendations","Writing vulnerability assessment reports"]'::jsonb, '3 Weeks', '[{"title":"Nmap Network Scanning Reference Guide","url":"https://nmap.org/book/man.html","provider":"Nmap.org","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000012' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000046', r.id, 6, 'Incident Response & Digital Forensics Fundamentals', 'इंसिडेंट रिस्पांस और डिजिटल फोरेंसिक्स मूल बातें', 'ఇన్సిడెంట్ రెస్పాన్స్ & డిజిటల్ ఫోరెన్సిక్స్ బేసిక్స్', 'Follow the NIST Incident Response lifecycle (Preparation, Detection, Containment, Eradication, Recovery), preserve digital evidence, and draft incident reports.', 'NIST इंसिडेंट रिस्पांस चरण, डिजिटल साक्ष्य संरक्षण और घटना रिपोर्ट तैयार करना।', 'సైబర్ దాడి జరిగినప్పుడు తీసుకోవాల్సిన చర్యలు (NIST మార్గదర్శకాలు) మరియు డిజిటల్ సాక్ష్యాల సేకరణ.', 'Draft a complete containment and recovery plan for a simulated ransomware incident', '[]'::jsonb, '["NIST SP 800-61 Incident Handling Guide","Isolating compromised network endpoints","Memory acquisition and volatile evidence preservation","Post-incident lessons learned reporting"]'::jsonb, '3 Weeks', '[{"title":"CISA Incident Response Resources","url":"https://www.cisa.gov","provider":"CISA","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000012' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000047', r.id, 7, 'SOC Analyst Certification Prep & Job Placement', 'एसओसी विश्लेषक साक्षात्कार तैयारी और नौकरी आवेदन', 'SOC అనలిస్ట్ ఇంటర్వ్యూ ప్రిపరేషన్ & ఉద్యోగ దరఖాస్తులు', 'Prepare for entry-level SOC Analyst Tier-1 interviews, showcase hands-on lab writeups on GitHub, and apply on NCS and tech job portals.', 'एसओसी एनालिस्ट टीयर-1 इंटरव्यू प्रश्न तैयार करें और सुरक्षा टीमों में जूनियर पदों के लिए आवेदन करें।', 'SOC అనలిస్ట్ ఇంటర్వ్యూ ప్రశ్నలను సాధన చేసి, ఐటీ సెక్యూరిటీ ఉద్యోగాలకు దరఖాస్తు చేయండి.', 'Apply to verified Junior SOC Analyst positions with your lab portfolio', '["NAPS Apprenticeship in Cybersecurity"]'::jsonb, '["Answering technical network defense questions","Presenting lab reports and TryHackMe profile badges","Understanding compliance frameworks (ISO 27001, Indian CERT-In)","Applying for 10+ SOC Tier-1 roles"]'::jsonb, '2 Weeks', '[{"title":"National Career Service Portal","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000012' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001', 'Personalized Solar PV Systems Technician Pathway', 6, '4 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000051', r.id, 1, 'Electrical Safety, Basic Circuit Theory & Multimeter Mastery', 'विद्युत सुरक्षा, बेसिक सर्किट थ्योरी और मल्टीमीटर का उपयोग', 'ఎలక్ట్రికల్ భద్రత, బేసిక్ సర్క్యూట్ థియరీ & మల్టీమీటర్ వాడకం', 'Understand AC and DC voltage, current, resistance (Ohm law), power calculation, electrical safety equipment (PPE), and multimeter measurements.', 'एसी/डीसी वोल्टेज, करंट, प्रतिरोध (ओम का नियम), सुरक्षा उपकरण और मल्टीमीटर से टेस्टिंग सीखें।', 'AC/DC విద్యుత్, రెసిస్టెన్స్, భద్రతా నియమాలు (PPE) మరియు మల్టీమీటర్ పరీక్షలు నేర్చుకోండి.', 'Measure voltage and continuity across three sample circuits with 100% safety', '["PMKVY 4.0 Free Training"]'::jsonb, '["Ohm law and power calculations (Watts = Volts x Amps)","DC versus AC circuit characteristics","Personal Protective Equipment (PPE) & shock safety","Measuring voltage, current, and continuity with a digital multimeter"]'::jsonb, '3 Weeks', '[{"title":"Bharat Skills Electrician Safety Material","url":"https://bharatskills.gov.in","provider":"Bharat Skills","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000001' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000052', r.id, 2, 'Solar Photovoltaic Principles, Module Types & Tilt Angles', 'सोलर पीवी सिद्धांत, मॉड्यूल प्रकार और कोण (Tilt Angle)', 'సోలార్ పివి సూత్రాలు, ప్యానెల్ రకాలు & టిల్ట్ యాంగిల్స్', 'Learn how solar cells generate electricity, monocrystalline vs polycrystalline panels, solar irradiance calculation, and optimal rooftop orientation.', 'सौर सेल कैसे काम करते हैं, मोनोक्रिस्टलाइन व पॉलीक्रिस्टलाइन पैनल, और छत पर सही दिशा व कोण निर्धारण।', 'సోలార్ సెల్స్ ఎలా పనిచేస్తాయి, ప్యానెల్ రకాలు మరియు సూర్యరశ్మికి అనుగుణంగా యాంగిల్ అమర్చడం.', 'Calculate the optimal tilt angle for your district rooftop coordinates', '["Suryamitra Skill Development Program"]'::jsonb, '["Photovoltaic effect and cell efficiency","Monocrystalline, polycrystalline, and bifacial panels","Calculating latitude tilt angle and azimuth orientation for Indian states","Shading analysis and sun path calculation"]'::jsonb, '2 Weeks', '[{"title":"NISE Suryamitra Technical Course Module 1","url":"https://nise.res.in/suryamitra","provider":"NISE","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000001' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000053', r.id, 3, 'Rooftop Mounting Structures & Civil Structural Installation', 'छत पर माउंटिंग स्ट्रक्चर और सिविल इंस्टॉलेशन', 'రూఫ్‌టాప్ మౌంటింగ్ స్ట్రక్చర్స్ & సివిల్ ఇన్‌స్టాలేషన్', 'Mount galvanized iron (GI) / aluminium rails on flat concrete roofs and tin sheds, use anchoring bolts, verify wind load resilience, and align arrays.', 'कंक्रीट और टिन शेड की छतों पर जीआई/एल्यूमीनियम संरचना लगाना, एंकर बोल्ट और हवा के दबाव की जांच।', 'కాంక్రీట్ పైకప్పులపై స్ట్రక్చర్ ఏర్పాటు చేయడం, బోల్ట్‌లతో బిగించడం మరియు గాలి తాకిడిని తట్టుకునేలా చూడటం.', 'Assemble a 2-panel mock rooftop mounting structure with correct torque specification', '[]'::jsonb, '["Selecting GI vs aluminium mounting hardware","Chemical and mechanical anchor fastening","Waterproofing roof penetrations","Array alignment and torque wrench tightening standards"]'::jsonb, '3 Weeks', '[{"title":"Skill India Solar PV Installer QP Guide","url":"https://www.skillindiadigital.gov.in","provider":"Skill India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000001' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000054', r.id, 4, 'DC/AC Wiring, Inverter Installation & Battery Bank Storage', 'डीसी/एसी वायरिंग, इन्वर्टर कनेक्शन और बैटरी बैंक', 'DC/AC వైరింగ్, ఇన్వర్టర్ కనెక్షన్ & బ్యాటరీ స్టోరేజ్', 'Route solar DC cables with MC4 crimped connectors, wire DC combiner boxes (fuses, surge protection devices), connect grid-tied inverters, and battery banks.', 'एमसी4 कनेक्टर्स के साथ डीसी केबल वायरिंग, डीसीडीबी/एसीडीबी बॉक्स, ग्रिड-टाई इन्वर्टर और बैटरी कनेक्शन।', 'MC4 కనెక్టర్లు, DC/AC డిస్ట్రిబ్యూషన్ బాక్స్‌లు, గ్రిడ్ ఇన్వర్టర్లు మరియు బ్యాటరీ వైరింగ్ చేయడం.', 'Complete wiring of a 1kW solar PV array through DCDB to an off-grid inverter', '["PM Surya Ghar Muft Bijli Yojana"]'::jsonb, '["Crimping MC4 waterproof solar connectors","Wiring DC Distribution Box (DCDB) with SPDs and fuses","Grid-tied string inverter connections","Battery bank series-parallel wiring calculations"]'::jsonb, '3 Weeks', '[{"title":"NISE Solar Inverter Connection Manual","url":"https://nise.res.in","provider":"NISE","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000001' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000055', r.id, 5, 'Earthing Systems, Lightning Arresters & Grid Net-Metering', 'अर्थिंग सिस्टम, तड़ित चालक और नेट-मीटरिंग प्रक्रिया', 'ఎర్తింగ్ సిస్టమ్స్, మెరుపు నిరోధకం & నెట్-మీటరింగ్ విధానం', 'Install chemical earthing electrodes, verify resistance (< 5 Ohms), install lightning arresters (LA), and submit DISCOM net-metering synchronization forms.', 'केमिकल अर्थिंग लगाना, 5 ओम से कम प्रतिरोध मापना, लाइटनिंग अरेस्टर और बिजली विभाग में नेट-मीटरिंग आवेदन।', 'ఎర్తింగ్ గుంతలు తవ్వడం, రెసిస్టెన్స్ పరీక్షించడం, లైట్నింగ్ అరెస్టర్ అమర్చడం మరియు నెట్-మీటరింగ్ దరఖాస్తు.', 'Perform a live earth resistance test and fill a DISCOM net-metering commissioning report', '[]'::jsonb, '["Chemical earthing installation with bentonite compound","Earth resistance measurement with megger testing kit","Installing dedicated earthing for inverter, body, and LA","State DISCOM inspection and bi-directional net-meter synchronization"]'::jsonb, '3 Weeks', '[{"title":"APCPDCL / AP Discom Net Metering Guidelines","url":"https://jnanabhumi.ap.gov.in","provider":"AP Govt","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000001' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000056', r.id, 6, 'Skill Council Certification & Paid NAPS Apprenticeship', 'स्किल काउंसिल प्रमाणन और सवेतन ऑन-जॉब अप्रेंटिसशिप', 'గ్రీన్ జాబ్స్ కౌన్సిల్ సర్టిఫికేషన్ & NAPS అప్రెంటిస్‌షిప్', 'Clear the Skill Council for Green Jobs (SCGJ) practical exam, register on Apprenticeship India (NAPS 2.0), and secure a field solar installer job.', 'ग्रीन जॉब्स स्किल काउंसिल (SCGJ) परीक्षा उत्तीर्ण करें, नैप्स पोर्टल पर रजिस्टर करें और सौर कंपनी में नौकरी पाएं।', 'ప్రభుత్వ గుర్తింపు పొందిన పరీక్ష పాస్ అవ్వడం, NAPS లో నమోదు కావడం మరియు సోలార్ టెక్నీషియన్ ఉద్యోగం పొందడం.', 'Register as candidate on apprenticeshipindia.gov.in and apply to 3 local solar EPC openings', '["NAPS 2.0 Direct Benefit Transfer Stipend","PM Surya Ghar Vendor Empanelment"]'::jsonb, '["Passing SCGJ assessment standards","Registering on Apprenticeship India with Aadhaar eKYC","Securing employer interviews under PM Surya Ghar contractors","Receiving monthly direct benefit transfer (DBT) stipend"]'::jsonb, '2 Weeks', '[{"title":"Apprenticeship India Portal","url":"https://www.apprenticeshipindia.gov.in","provider":"Apprenticeship India","is_free":true},{"title":"National Career Service Portal","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000001' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000013', 'Personalized Cloud Support Associate Learning Pathway', 6, '5 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000061', r.id, 1, 'Virtualization & Networking for Cloud Infrastructure', 'वर्चुअलाइजेशन और क्लाउड नेटवर्किंग मूल बातें', 'వర్చువలైజేషన్ & క్లౌడ్ నెట్‌వర్కింగ్ కాన్సెప్ట్స్', 'Understand hypervisors, virtual machines, VPCs, subnets, internet gateways, route tables, and security groups.', 'हाइपरवाइजर, वीएम, वीपीसी (VPC), सबनेट, राउट टेबल और सिक्योरिटी ग्रुप्स की अवधारणा समझें।', 'వర్చువల్ మెషీన్స్, VPC నెట్‌వర్కింగ్, సబ్‌నెట్స్ మరియు ఫైర్‌వాల్ సెక్యూరిటీ గ్రూపులు నేర్చుకోండి.', 'Design a private/public dual-subnet cloud network diagram in draw.io', '[]'::jsonb, '["Virtualization principles","VPC and private/public subnetting","Security groups and network ACLs","DNS resolution and Elastic IPs"]'::jsonb, '3 Weeks', '[{"title":"Microsoft Learn: Cloud Concepts","url":"https://learn.microsoft.com/training/paths/microsoft-azure-fundamentals-describe-cloud-concepts","provider":"Microsoft","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000013' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000062', r.id, 2, 'Compute Instances & Linux Server Provisioning', 'क्लाउड कंप्यूट (EC2/Azure VM) और लिनक्स कॉन्फ़िगरेशन', 'క్లౌడ్ కంప్యూట్ (VMs) & లైనక్స్ సర్వర్ మేనేజ్‌మెంట్', 'Launch virtual compute instances (AWS EC2 / Azure VMs), attach SSD storage volumes, connect via SSH keys, and install Nginx web servers.', 'ईसी2 या एज़्योर वीएम लॉन्च करना, एसएसएच कनेक्शन, वेब सर्वर इंस्टॉल करना और सुरक्षा जांच।', 'క్లౌడ్ సర్వర్లను ప్రారంభించడం, SSH ద్వారా కనెక్ట్ అవ్వడం మరియు వెబ్ సర్వర్లను కాన్ఫిగర్ చేయడం.', 'Launch a cloud virtual server hosting a live custom HTML status page', '[]'::jsonb, '["Instance sizing and lifecycle","Attaching and partitioning block storage (EBS)","Deploying Nginx and configuring reverse proxies","Automating bootstrap startup scripts"]'::jsonb, '3 Weeks', '[{"title":"freeCodeCamp: AWS Certified Cloud Practitioner","url":"https://www.freecodecamp.org/news/aws-certified-cloud-practitioner-training-course","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000013' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000063', r.id, 3, 'Cloud Storage & Managed Database Services', 'क्लाउड स्टोरेज (S3/Blob) और प्रबंधित डेटाबेस (RDS)', 'క్లౌడ్ స్టోరేజ్ (S3) & మేనేజ్డ్ డేటాబేస్ (RDS)', 'Store static assets in S3 buckets with IAM access policies, configure managed PostgreSQL/MySQL instances, and configure automated backups.', 'एस3 स्टोरेज बकेट्स, डेटाबेस बैकअप और मैनेज्ड पोस्टग्रेएसक्यूएल सेवाएं प्रबंधित करना।', 'S3 బకెట్లలో ఫైల్స్ నిల్వ చేయడం, ఆటోమేటిక్ బ్యాకప్‌లు మరియు క్లౌడ్ డేటాబేస్‌లను నిర్వహించడం.', 'Host a static website on cloud object storage with public SSL and CDN', '[]'::jsonb, '["Object storage vs block storage vs file systems","Bucket policies and public vs private access","Managed relational database provisioning","Point-in-time recovery and snapshot replication"]'::jsonb, '3 Weeks', '[{"title":"AWS Skill Builder Free Tier","url":"https://explore.skillbuilder.aws","provider":"AWS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000013' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000064', r.id, 4, 'Identity and Access Management (IAM) & Security Hardening', 'आईएएम (IAM) सुरक्षा नीतियां और एक्सेस कंट्रोल', 'IAM సెక్యూరిటీ పాలసీలు & యూజర్ పర్మిషన్లు', 'Apply the principle of least privilege: create IAM users, custom policy documents, roles for cloud instances, and enforce Multi-Factor Authentication (MFA).', 'न्यूनतम विशेषाधिकार का सिद्धांत, एमएफए लागू करना, आईएएम भूमिकाएं और अनुमतियां।', 'IAM యూజర్లను సృష్టించడం, MFA అమలు చేయడం మరియు సురక్షిత అనుమతులు ఇవ్వడం.', 'Audit an IAM account and create granular read-only vs admin roles', '[]'::jsonb, '["IAM users, groups, and roles","Writing JSON IAM policy statements","Enforcing root-account protection & MFA","Rotating access keys safely"]'::jsonb, '3 Weeks', '[{"title":"Microsoft Learn: Azure Identity Management","url":"https://learn.microsoft.com","provider":"Microsoft","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000013' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000065', r.id, 5, 'Cloud Monitoring, Metrics & Incident Troubleshooting', 'क्लाउड मॉनिटरिंग (CloudWatch) और समस्या निवारण', 'క్లౌడ్ మానిటరింగ్ (CloudWatch) & ట్రబుల్షూటింగ్', 'Configure CloudWatch/Azure Monitor alarms for CPU, RAM, disk usage, analyze error logs, and troubleshoot network routing issues.', 'क्लाउडवॉच अलार्म सेट करना, सीपीयू/मेमोरी स्पाइक का विश्लेषण और लॉग इन्वेस्टिगेशन।', 'సర్వర్ పనితీరును మానిటర్ చేయడం, అలర్ట్స్ సెట్ చేయడం మరియు ఎర్రర్ లాగ్స్ పరిష్కరించడం.', 'Simulate a high-CPU spike on an instance and receive an automated email alert', '[]'::jsonb, '["Metric thresholds and alert notification routing","Centralized log aggregation and grep searching","Diagnosing connection timeouts & 5xx errors","Writing root cause analysis (RCA) incident summaries"]'::jsonb, '3 Weeks', '[{"title":"AWS CloudWatch Documentation","url":"https://docs.aws.amazon.com/cloudwatch","provider":"AWS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000013' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000066', r.id, 6, 'Cloud Fundamentals Certification (AZ-900 / AWS CCP) & Jobs', 'क्लाउड सर्टिफिकेशन परीक्षा और जॉब प्लेसमेंट', 'క్లౌడ్ సర్టిఫికేషన్ పరీక్ష & ఉద్యోగ దరఖాస్తులు', 'Complete practice exams for AWS Cloud Practitioner or Azure Fundamentals (AZ-900), and apply for Cloud Support Associate positions on Naukri and LinkedIn.', 'क्लाउड सर्टिफिकेशन अभ्यास परीक्षा पास करें और क्लाउड सपोर्ट एसोसिएट पदों के लिए आवेदन करें।', 'క్లౌడ్ సర్టిఫికేషన్ పూర్తి చేసి, ఐటీ కంపెనీలలో క్లౌడ్ ఉద్యోగాలకు దరఖాస్తు చేసుకోండి.', 'Apply to verified Cloud Support Associate vacancies with your certificate badge', '["NAPS IT/ITeS Apprenticeship"]'::jsonb, '["Passing AZ-900 / AWS CCP practice tests with 85%+","Showcasing cloud architecture labs on LinkedIn","Troubleshooting interview roleplay practice","Applying to 15+ cloud support openings"]'::jsonb, '2 Weeks', '[{"title":"Naukri Cloud Support Roles","url":"https://www.naukri.com","provider":"Naukri","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000013' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000016', 'Personalized UI/UX Designer Learning Pathway', 6, '4 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000071', r.id, 1, 'Design Fundamentals: Typography, Color Theory & Grid Systems', 'डिज़ाइन सिद्धांत: टाइपोग्राफी, रंग सिद्धांत और ग्रिड', 'డిజైన్ సూత్రాలు: టైపోగ్రఫీ, రంగుల సిద్ధాంతం & గ్రిడ్స్', 'Learn visual hierarchy, 8pt spatial grid system, contrast ratios for accessibility (WCAG AA), font pairings, and psychological color harmony.', 'विज़ुअल पदानुक्रम, 8pt ग्रिड सिस्टम, सुलभता के लिए कंट्रास्ट अनुपात और रंग संयोजन सीखें।', 'విజువల్ ప్రాధాన్యత, 8pt స్పేసింగ్ గ్రిడ్, కలర్ కాంట్రాస్ట్ మరియు ఫాంట్ స్టైల్స్ ఎంపిక.', 'Design a clean typography hierarchy poster with 8pt grid alignment', '[]'::jsonb, '["8pt spacing system in mobile design","WCAG color contrast ratios","Typography scale (H1 through caption)","Visual balance, alignment, and whitespace"]'::jsonb, '2 Weeks', '[{"title":"freeCodeCamp: UI/UX Design for Beginners","url":"https://www.freecodecamp.org/news/ui-ux-design-tutorial-for-beginners","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000016' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000072', r.id, 2, 'User Research, Empathy Mapping & Personas', 'यूजर रिसर्च, एम्पेथी मैपिंग और यूजर पर्सोना', 'యూజర్ రీసెర్చ్ & పర్సోనా డిజైన్', 'Conduct semi-structured user interviews with rural smartphone users, document pain points, map empathy matrices, and build realistic user personas.', 'उपयोगकर्ता साक्षात्कार, दर्द बिंदु (Pain points) पहचानना और यथार्थवादी यूजर पर्सोना बनाना।', 'వినియోగదారులను ఇంటర్వ్యూ చేయడం, వారి సమస్యలను గుర్తించడం మరియు యూజర్ ప్రొఫైల్స్ తయారు చేయడం.', 'Create 2 user personas for a rural job-seeker app and map their user journey', '[]'::jsonb, '["User interview methodology","Empathy mapping (Says, Thinks, Does, Feels)","Constructing target user personas","Mapping end-to-end user journey flows"]'::jsonb, '3 Weeks', '[{"title":"Interaction Design Foundation Open Guides","url":"https://www.interaction-design.org","provider":"IDF","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000016' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000073', r.id, 3, 'Information Architecture & Low-Fidelity Wireframing', 'इन्फॉर्मेशन आर्किटेक्चर और लो-फिडेलिटी वायरफ्रेमिंग', 'ఇన్ఫర్మేషన్ ఆర్కిటెక్చర్ & వైర్‌ఫ్రేమింగ్', 'Organize app navigation hierarchies, draft sitemaps, sketch pencil wireframes, and translate them into greyscale layout wireframes in Figma.', 'ऐप नेविगेशन स्ट्रक्चर, साइटमैप और फिग्मा में ग्रे-स्केल वायरफ्रेम्स तैयार करना।', 'యాప్ పేజీల నిర్మాణం, సైట్‌మ్యాప్ మరియు ఫిగ్మా లో ప్రాథమిక వైర్‌ఫ్రేమ్‌లు రూపొందించడం.', 'Build a 5-screen wireframe flow for a multilingual student scholarship portal', '[]'::jsonb, '["Card sorting and content categorization","Drafting clear app navigation sitemaps","Rapid paper prototyping and sketching","Figma vector wireframing"]'::jsonb, '3 Weeks', '[{"title":"Figma for Beginners Tutorial","url":"https://help.figma.com/hc/en-us/categories/360002051613","provider":"Figma","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000016' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000074', r.id, 4, 'High-Fidelity UI Design & Design Systems in Figma', 'फिग्मा में हाई-फिडेलिटी यूआई और डिज़ाइन सिस्टम', 'ఫిగ్మా లో హై-ఫిడెలిటీ డిజైన్ & డిజైన్ సిస్టమ్స్', 'Master Figma Auto-Layout 5.0, responsive components, variants, properties, design tokens (colors, spacing, shadows), and interactive animations.', 'फिग्मा ऑटो-लेआउट, रीउज़ेबल कॉम्पोनेंट्स, वेरिएंट्स और संपूर्ण डिज़ाइन सिस्टम का निर्माण।', 'ఫిగ్మా ఆటో-లేఅవుట్, పునర్వినియోగ కాంపోనెంట్లు మరియు రంగులు/ఫాంట్ల డిజైన్ సిస్టమ్ నిర్మాణం.', 'Design a complete 8-screen mobile application UI with an organized Figma design system', '[]'::jsonb, '["Figma Auto-Layout (flex direction, padding, gap)","Creating component variants and boolean properties","Color and typography token management","Micro-interactions and smart animations"]'::jsonb, '4 Weeks', '[{"title":"Figma YouTube Official Channel","url":"https://www.youtube.com/@Figma","provider":"Figma","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000016' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000075', r.id, 5, 'Usability Testing & Developer Handoff', 'उपयोगिता परीक्षण (Usability Testing) और डेवलपर हैंडऑफ', 'యూజబిలిటీ టెస్టింగ్ & డెవలపర్ హ్యాండ్‌ఆఫ్', 'Run prototype usability tests on mobile devices, record task completion rates, iterate based on feedback, and inspect CSS specs for developer handoff.', 'मोबाइल प्रोटोटाइप परीक्षण, उपयोगकर्ता फीडबैक के आधार पर सुधार और डेवलपर हैंडऑफ।', 'మొబైల్ ఫోన్లలో ప్రోటోటైప్ పరీక్షలు నిర్వహించి, డెవలపర్లకు కొలతలు, CSS కోడ్ అందించడం.', 'Conduct a usability test with 3 users on your interactive Figma prototype', '[]'::jsonb, '["Writing usability task scenarios","Conducting think-aloud test sessions","Figma Dev Mode specs and asset export","Redline documentation and spacing guidelines"]'::jsonb, '2 Weeks', '[{"title":"Nielsen Norman Group Usability Basics","url":"https://www.nngroup.com/articles/usability-101-introduction-to-usability","provider":"NNGroup","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000016' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000076', r.id, 6, 'Design Case Study Portfolio (Behance/Dribbble) & Hiring', 'केस स्टडी पोर्टफोलियो और यूआई डिज़ाइनर नौकरी आवेदन', 'డిజైన్ కేస్ స్టడీ పోర్ట్‌ఫోలియో (Behance) & ఉద్యోగ అప్లికేషన్లు', 'Write 2 thorough end-to-end design case studies detailing problem statement, user research, wireframes, and final UI screens on Behance and apply for roles.', 'बेहेंस पर 2 विस्तृत केस स्टडीज प्रकाशित करें और जूनियर यूआई/यूएक्स डिजाइनर पदों के लिए आवेदन करें।', 'Behance లో 2 పూర్తి కేస్ స్టడీలను ప్రదర్శించి, జూనియర్ UI డిజైనర్ ఉద్యోగాలకు దరఖాస్తు చేయండి.', 'Publish two detailed UI/UX case studies with mobile prototypes on Behance', '[]'::jsonb, '["Formatting comprehensive UX case studies","Crafting eye-catching presentation mockups","Preparing design critique and whiteboard challenges","Applying to agencies and tech startups"]'::jsonb, '2 Weeks', '[{"title":"Behance Design Portfolios","url":"https://www.behance.net","provider":"Behance","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000016' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000017', 'Personalized Digital Marketing Specialist Learning Pathway', 6, '4 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000081', r.id, 1, 'Digital Marketing Fundamentals & Consumer Funnel Strategy', 'डिजिटल मार्केटिंग मूल बातें और मार्केटिंग फ़नल', 'డిజిటల్ మార్కెటింగ్ బేసిక్స్ & మార్కెటింగ్ ఫన్నెల్', 'Understand marketing channels (Organic, Paid, Social, Email), consumer awareness-consideration-conversion funnels, customer acquisition cost (CAC), and ROI.', 'ऑर्गेनिक और पेड मार्केटिंग, मार्केटिंग फनल (AIDA मॉडल), ग्राहक अधिग्रहण लागत (CAC) और आरओआई समझें।', 'డిజిటల్ మార్కెటింగ్ ఛానెల్స్, సేల్స్ ఫన్నెల్ మరియు బ్రాండ్ ప్రమోషన్ వ్యూహాలను నేర్చుకోండి.', 'Map a complete digital marketing funnel strategy for a local agricultural or retail business', '[]'::jsonb, '["Inbound versus outbound marketing","AIDA funnel model (Awareness, Interest, Decision, Action)","Core metrics: CTR, CPC, CPM, CPA, ROAS","Customer persona segmentation"]'::jsonb, '2 Weeks', '[{"title":"Google Digital Garage: Fundamentals of Digital Marketing","url":"https://learndigital.withgoogle.com","provider":"Google","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000017' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000082', r.id, 2, 'Search Engine Optimization (SEO: On-Page, Off-Page & Technical)', 'सर्च इंजन ऑप्टिमाइजेशन (एसईओ: ऑन-पेज और ऑफ-पेज)', 'సెర్చ్ ఇంజిన్ ఆప్టిమైజేషన్ (SEO: ఆన్-పేజ్ & ఆఫ్-పేజ్)', 'Conduct keyword research using free tools, optimize meta titles/descriptions, write SEO-rich articles, build quality backlinks, and resolve technical crawl errors.', 'कीवर्ड रिसर्च, ऑन-पेज कंटेंट ऑप्टिमाइजेशन, बैकलिंक्स और गूगल सर्च कंसोल का उपयोग सीखें।', 'కీవర్డ్ రీసెర్చ్, గూగుల్ ర్యాంకింగ్ టెక్నిక్స్, మెటా ట్యాగ్‌లు మరియు బ్యాక్‌లింక్స్ నిర్మించడం.', 'Optimize an article to rank for a low-competition regional keyword', '[]'::jsonb, '["Keyword research & search intent analysis","On-page title, H1-H3, image alt, and URL structure","Technical SEO (XML sitemaps, robots.txt, Core Web Vitals)","Google Search Console setup and indexing checks"]'::jsonb, '3 Weeks', '[{"title":"Moz Beginner Guide to SEO","url":"https://moz.com/beginners-guide-to-seo","provider":"Moz","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000017' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000083', r.id, 3, 'Social Media Marketing (Meta, Instagram & YouTube Content)', 'सोशल मीडिया मार्केटिंग (इंस्टाग्राम, फेसबुक और यूट्यूब)', 'సోషల్ మీడియా మార్కెటింగ్ (ఇన్‌స్టాగ్రామ్, ఫేస్‌బుక్ & యూట్యూబ్)', 'Craft social media content calendars, design banners in Canva, optimize short-form video reels, manage community engagement, and grow organic followers.', 'कंटेंट कैलेंडर बनाना, कैनवा में पोस्ट डिजाइन करना, रील्स/शॉर्ट्स रणनीति और ऑर्गेनिक ग्रोथ।', 'కంటెంట్ క్యాలెండర్ తయారీ, కాన్వా లో పోస్టర్లు డిజైన్ చేయడం మరియు సోషల్ మీడియా గ్రోత్.', 'Create a 14-day social media visual campaign for a rural vocational training center', '[]'::jsonb, '["Organic content strategy across Instagram, LinkedIn, and YouTube","Canva social media graphics and visual branding","Community engagement, comments, and DMs response strategy","Short-form video scriptwriting and engagement hooks"]'::jsonb, '3 Weeks', '[{"title":"HubSpot Social Media Certification","url":"https://academy.hubspot.com/courses/social-media","provider":"HubSpot Academy","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000017' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000084', r.id, 4, 'Paid Advertising (Meta Ads Manager & Google Search Ads)', 'पेड विज्ञापन (मेटा ऐड्स और गूगल सर्च एडवरटाइजिंग)', 'పెయిడ్ ప్రకటనలు (Meta Ads & Google Ads)', 'Set up Meta Business Suite, configure custom audiences and pixel tracking, write high-converting ad copy, and structure Google Search campaign budgets.', 'मेटा ऐड्स मैनेजर, ऑडियंस टारगेटिंग, गूगल सर्च कैंपेन और विज्ञापन बजट प्रबंधन सीखें।', 'గూగుల్ మరియు ఫేస్‌బుక్ యాడ్స్ మేనేజర్ ద్వారా టార్గెటెడ్ ప్రకటనలు నడపడం మరియు బడ్జెట్ నిర్వహణ.', 'Build and simulate a ₹5,000 lead-generation ad campaign with copy and targeting parameters', '[]'::jsonb, '["Meta Ads Manager campaign objectives (Leads, Traffic, Sales)","Audience demographic and interest targeting","Google Ads keyword match types (Exact, Phrase, Broad)","A/B testing ad creatives and landing page copy"]'::jsonb, '3 Weeks', '[{"title":"Google Skillshop Google Ads Search Certification","url":"https://skillshop.withgoogle.com","provider":"Google","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000017' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000085', r.id, 5, 'Web Analytics (Google Analytics 4 & Tag Manager)', 'वेब एनालिटिक्स (Google Analytics 4 और डेटा ट्रैकिंग)', 'వెబ్ అనలిటిక్స్ (Google Analytics 4 & ట్రాకింగ్)', 'Set up GA4 properties, configure conversion events (form submits, button clicks), track traffic sources (UTM parameters), and build executive marketing reports.', 'GA4 सेटअप, रूपांतरण (Conversions) ट्रैक करना, यूटीएम पैरामीटर और मार्केटिंग रिपोर्टिंग।', 'గూగుల్ అనలిటిక్స్ 4 ద్వారా వెబ్‌సైట్ ట్రాఫిక్, యూజర్ ప్రవర్తన మరియు లీడ్స్ ట్రాక్ చేయడం.', 'Build an interactive Looker Studio dashboard tracking mock website traffic and conversion rates', '[]'::jsonb, '["GA4 event-driven measurement model","UTM campaign tracking URLs","Analyzing acquisition channels and bounce rates","Building custom Looker Studio performance dashboards"]'::jsonb, '3 Weeks', '[{"title":"Google Skillshop: Google Analytics 4 Certification","url":"https://skillshop.withgoogle.com","provider":"Google","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000017' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000086', r.id, 6, 'Certifications, Freelance Pitching & Agency Job Placement', 'डिजिटल मार्केटिंग प्रमाणन, फ्रीलांसिंग और नौकरी आवेदन', 'సర్టిఫికేషన్లు, ఫ్రీలాన్సింగ్ & ఏజెన్సీ ఉద్యోగ దరఖాస్తులు', 'Earn Google and HubSpot free certifications, compile a campaign portfolio with clear metrics, and apply for specialist roles in marketing agencies and startups.', 'गूगल प्रमाणन अर्जित करें, पोर्टफोलियो बनाएं और मार्केटिंग एजेंसियों में आवेदन करें।', 'గూగుల్ సర్టిఫికేషన్ పూర్తి చేసి, మార్కెటింగ్ ఏజెన్సీలలో ఉద్యోగాలకు దరఖాస్తు చేయండి.', 'Apply to verified Digital Marketing Executive roles with your campaign case study', '["NAPS Apprenticeship in Marketing"]'::jsonb, '["Earning Google Search Ads and GA4 credentials","Packaging client case studies with ROAS proof","Pitching freelance digital marketing services","Applying on Internshala, LinkedIn, and Naukri"]'::jsonb, '2 Weeks', '[{"title":"Internshala Digital Marketing Openings","url":"https://internshala.com","provider":"Internshala","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000017' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000018', 'Personalized Accountant Learning Pathway', 6, '4 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000091', r.id, 1, 'Double-Entry Bookkeeping Principles & Journal Entries', 'दोहरा लेखा प्रणाली (Double-Entry) और जर्नल प्रविष्टियां', 'డబుల్ ఎంట్రీ బుక్‌కీపింగ్ & జర్నల్ ఎంట్రీలు', 'Master the golden rules of accounting (Real, Personal, Nominal accounts), journalizing transactions, ledger posting, and generating preliminary Trial Balances.', 'लेखांकन के सुनहरे नियम, जर्नल प्रविष्टियां, लेजर पोस्टिंग और तलपट (Trial Balance) तैयार करना।', 'అకౌంటింగ్ ప్రాథమిక నియమాలు, జర్నల్ ఎంట్రీలు రాయడం మరియు లెడ్జర్ ఖాతాల నిర్వహణ.', 'Record 30 diverse business transactions in a journal and balance the trial balance', '[]'::jsonb, '["3 Golden rules of accounting","Journalizing cash, bank, credit sales, and purchases","Posting entries to general ledgers","Preparing trial balance to verify debit-credit equality"]'::jsonb, '3 Weeks', '[{"title":"SWAYAM: Financial Accounting Course","url":"https://swayam.gov.in","provider":"SWAYAM","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000018' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000092', r.id, 2, 'Tally Prime Mastery: Company Creation & Voucher Entries', 'टैली प्राइम (Tally Prime): कंपनी निर्माण और वाउचर एंट्री', 'ట్యాలీ ప్రైమ్ (Tally Prime): కంపెనీ క్రియేషన్ & వోచర్లు', 'Set up companies in Tally Prime, create ledgers with appropriate groups, record Payment, Receipt, Contra, Sales, Purchase, and Journal vouchers.', 'टैली प्राइम में कंपनी बनाना, लेजर ग्रुप्स, और बिक्री/खरीद/भुगतान वाउचर प्रविष्टियां दर्ज करना।', 'ట్యాలీ లో కంపెనీని సెటప్ చేయడం, సేల్స్, పర్చేస్, పేమెంట్ వోచర్లను రికార్డ్ చేయడం.', 'Enter 1 month of business operational vouchers in Tally Prime and reconcile bank accounts', '[]'::jsonb, '["Company configuration & Chart of Accounts in Tally","Recording Payment (F5), Receipt (F6), Contra (F4) vouchers","Sales (F8) and Purchase (F9) voucher entry","Generating Daybook and Cash Flow reports"]'::jsonb, '3 Weeks', '[{"title":"Tally Education Self-Learning Guides","url":"https://tallyeducation.com","provider":"Tally Solutions","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000018' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000093', r.id, 3, 'Goods and Services Tax (GST) Compliance & Returns', 'जीएसटी (GST) अनुपालन, इनपुट टैक्स क्रेडिट और रिटर्न फाइलिंग', 'జీఎస్టీ (GST) నిబంధనలు, ఇన్‌పుట్ ట్యాక్స్ క్రెడిట్ & రిటర్న్స్', 'Understand CGST, SGST, IGST, HSN/SAC codes, invoice requirements, Input Tax Credit (ITC) reconciliation, and filing GSTR-1 & GSTR-3B.', 'सीजीएसटी, एसजीएसटी, आईजीएसटी, इनपुट टैक्स क्रेडिट (ITC) और जीएसटीआर-1/3बी रिटर्न फाइलिंग नियम।', 'CGST, SGST, IGST లెక్కలు, ఇన్వాయిస్ తయారీ, ITC క్లెయిమ్ చేయడం మరియు GST పోర్టల్ ఫైలింగ్.', 'Generate a GST tax invoice and prepare a monthly GSTR-3B summary report', '[]'::jsonb, '["Structure of GST rates and HSN code classification","Generating GST-compliant tax invoices in Tally","Reconciling GSTR-2B purchase invoices with books","Filing monthly GSTR-1 outward and GSTR-3B summary returns"]'::jsonb, '3 Weeks', '[{"title":"GST Official Portal Guides","url":"https://www.gst.gov.in","provider":"GSTN","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000018' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000094', r.id, 4, 'Tax Deducted at Source (TDS), Payroll & Provident Fund', 'टीडीएस (TDS), पेरोल वेतन और पीएफ/ईएसआई अनुपालन', 'TDS తగ్గింపులు, పేరోల్ జీతాల బిల్లులు & PF/ESI', 'Compute TDS deductions on salary (192), contracts (194C), professional fees (194J), manage salary pay slips, and calculate EPF and ESIC statutory contributions.', 'टीडीएस धाराएं, वेतन पेरोल तैयार करना, और पीएफ/ईएसआई योगदान की गणना।', 'ఉద్యోగుల జీతాల నుండి TDS, PF, ESI మినహాయింపులను లెక్కించడం మరియు పే-స్లిప్స్ తయారు చేయడం.', 'Compute monthly payroll with TDS, EPF, and professional tax for a 10-person firm', '[]'::jsonb, '["Key TDS sections (192, 194C, 194J, 194I)","Payroll attendance and salary slip calculation in Excel/Tally","Employee Provident Fund (EPF 12%) computation","Filing quarterly TDS Form 24Q and 26Q"]'::jsonb, '3 Weeks', '[{"title":"Income Tax Department Tutorials","url":"https://incometaxindia.gov.in","provider":"CBDT","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000018' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000095', r.id, 5, 'Financial Statements: Balance Sheet & Profit & Loss Account', 'वित्तीय विवरण: लाभ-हानि खाता और बैलेंस शीट', 'ఫైనాన్షియల్ స్టేట్‌మెంట్స్: లాభనష్టాల ఖాతా & బ్యాలెన్స్ షీట్', 'Prepare year-end adjusting entries (depreciation, outstanding expenses, prepaid expenses), Trading and Profit & Loss accounts, and classified Balance Sheets.', 'साल के अंत की प्रविष्टियां (मूल्यह्रास, बकाया खर्चे), लाभ-हानि खाता और बैलेंस शीट तैयार करना।', 'డిప్రిసియేషన్ ఎంట్రీలు, వార్షిక లాభనష్టాల నివేదిక మరియు బ్యాలెన్స్ షీట్ ఆడిట్ సిద్ధం చేయడం.', 'Finalize and balance a year-end Profit & Loss statement and Balance Sheet in Excel', '[]'::jsonb, '["Year-end adjustment entries and accruals","Depreciation calculation methods (Straight Line vs WDV)","Drafting Trading and Profit & Loss statement","Classified Balance Sheet layout and financial ratios"]'::jsonb, '3 Weeks', '[{"title":"Khan Academy: Balance Sheet & Income Statement","url":"https://www.khanacademy.org","provider":"Khan Academy","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000018' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000096', r.id, 6, 'Accounts Executive Placement & CA Firm Internship', 'अकाउंट्स एक्जीक्यूटिव साक्षात्कार और सीए फर्म में प्लेसमेंट', 'అకౌంట్స్ ఎగ్జిక్యూటివ్ ఉద్యోగాలు & CA ఫర్మ్ ప్రాక్టీస్', 'Prepare for practical accounting interview tests in Tally and Excel, compile sample audit portfolios, and apply for roles in local SMEs, retail, or CA firms.', 'टैली और एक्सेल में प्रैक्टिकल टेस्ट की तैयारी करें और सीए फर्मों व कंपनियों में आवेदन करें।', 'ట్యాలీ ప్రాక్టికల్ టెస్ట్ సాధన చేసి, వ్యాపార సంస్థలు మరియు CA ఆఫీసులలో అకౌంటెంట్‌గా చేరండి.', 'Apply to verified Junior Accountant / Accounts Assistant openings', '["NAPS Apprenticeship in Banking & Accounting"]'::jsonb, '["Clearing Tally operational practical speed tests","Answering tax and GST reconciliation viva questions","Writing a professional commerce resume","Applying to 15+ accounting openings on NCS and Naukri"]'::jsonb, '2 Weeks', '[{"title":"National Career Service Accounting Jobs","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000018' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000008', 'Personalized Full Stack Developer Learning Pathway', 7, '7 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000101', r.id, 1, 'Modern Frontend Foundation: Semantic HTML, Modern CSS & Tailwind', 'मॉडर्न फ्रंटएंड: एचटीएमएल5, आधुनिक सीएसएस और टेलविंड', 'ఆధునిక ఫ్రంటెండ్: HTML5, CSS & టెయిల్‌విండ్ CSS', 'Build responsive, accessible user interfaces using semantic HTML5, Flexbox, CSS Grid, and utility-first Tailwind CSS.', 'सिमेंटिक HTML, फ्लेक्सबॉक्स, ग्रिड और टेलविंड सीएसएस से मोबाइल-फ्रेंडली यूआई बनाना सीखें।', 'HTML5, రెస్పాన్సివ్ CSS మరియు టెయిల్‌విండ్ CSS ద్వారా వెబ్ స్క్రీన్‌లను నిర్మించండి.', 'Build a fully responsive landing page using Tailwind CSS', '[]'::jsonb, '["Semantic markup & web accessibility standards","Flexbox & CSS Grid alignment systems","Utility-first styling with Tailwind CSS","Mobile-first responsive design principles"]'::jsonb, '3 Weeks', '[{"title":"freeCodeCamp: Responsive Web Design","url":"https://www.freecodecamp.org/learn/2022/responsive-web-design","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000008' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000102', r.id, 2, 'JavaScript Deep Dive & Asynchronous Programming', 'जावास्क्रिप्ट गहन अध्ययन और एसिंक्रोनस प्रोग्रामिंग', 'జావాస్క్రిప్ట్ అడ్వాన్స్‌డ్ కాన్సెప్ట్స్ & Async ప్రోగ్రామింగ్', 'Master closures, scope, array transformations, promises, async/await, DOM events, and modules in modern ES6+ JavaScript.', 'क्लोजर, स्कोप, प्रॉमिस, async/await और ES6+ मॉड्यूल्स में विशेषज्ञता हासिल करें।', 'క్లోజర్స్, ప్రామిసెస్, అసింక్/అవైట్ మరియు ఆధునిక జావాస్క్రిప్ట్ ఫీచర్స్ నేర్చుకోండి.', 'Build an interactive dashboard consuming live public government/weather APIs', '[]'::jsonb, '["Closures, execution context, and event loop","ES6+ modules and destructuring","Async/await error handling with try-catch","Fetch API and consuming third-party REST services"]'::jsonb, '4 Weeks', '[{"title":"MDN: JavaScript Guide","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide","provider":"MDN","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000008' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000103', r.id, 3, 'React.js Component Architecture & Client State Management', 'रिएक्ट.जेएस (React.js) कॉम्पोनेंट्स और स्टेट मैनेजमेंट', 'రియాక్ట్ జెఎస్ (React.js) ఆర్కిటెక్చర్ & స్టేట్ మేనేజ్‌మెంట్', 'Build single-page applications with React functional components, hooks (useState, useEffect, useMemo), Context API, and client routing.', 'रिएक्ट कॉम्पोनेंट्स, स्टेट हुक्स, कॉन्टेक्स्ट एपीआई और क्लाइंट-साइड राउटिंग सीखें।', 'రియాక్ట్ ఫంక్షనల్ కాంపోనెంట్లు, కస్టమ్ హుక్స్ మరియు పేజీల నావిగేషన్ రూపొందించండి.', 'Build a multi-page interactive web application with React Router and state management', '[]'::jsonb, '["Decomposing UIs into reusable React components","Props passing and unidirectional data flow","Managing global state with Context API / Zustand","Routing with React Router v6"]'::jsonb, '4 Weeks', '[{"title":"React Official Documentation","url":"https://react.dev/learn","provider":"React Open Source","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000008' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000104', r.id, 4, 'Backend API Engineering with Node.js & Express', 'नोड.जेएस और एक्सप्रेस से बैकएंड एपीआई निर्माण', 'నోడ్ జెఎస్ & ఎక్స్‌ప్రెస్ ద్వారా బ్యాకెండ్ API ల నిర్మాణం', 'Build modular REST APIs in Node.js, create middleware pipelines, validate request bodies, handle file uploads, and handle errors.', 'एक्सप्रेस में सुरक्षित REST API बनाएं, मिडलवेयर पाइपलाइन और अनुरोध सत्यापन सीखें।', 'నోడ్ మరియు ఎక్స్‌ప్రెస్‌లో REST API లను డిజైన్ చేయడం మరియు మిడిల్‌వేర్ రాయడం.', 'Build a complete backend REST API for an online course or job portal', '[]'::jsonb, '["Express REST routing architecture","Middleware pipeline design","Payload validation with Zod","Centralized error handling and logging"]'::jsonb, '3 Weeks', '[{"title":"MDN: Express/Node Guide","url":"https://developer.mozilla.org","provider":"MDN","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000008' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000105', r.id, 5, 'PostgreSQL Relational Databases, Schemas & Prisma ORM', 'पोस्टग्रेएसक्यूएल डेटाबेस, स्कीमा और प्रिज्मा ओआरएम', 'పోస్ట్‌గ్రేఎస్క్యుఎల్ డేటాబేస్, రిలేషన్లు & ప్రిస్మా ORM', 'Design normalized relational databases, define foreign key relations, write complex SQL queries, and manage migrations with Prisma ORM.', 'पोस्टग्रेएसक्यूएल स्कीमा, रिलेशनल डेटाबेस डिजाइन और प्रिज्मा ओआरएम से माइग्रेशन संभालना।', 'రిలేషనల్ డేటాబేస్ టేబుల్స్ డిజైన్ చేయడం, SQL క్వెరీలు మరియు ప్రిస్మా ORM వాడకం.', 'Connect your Express backend to a live PostgreSQL database via Prisma ORM', '[]'::jsonb, '["Relational schema design and foreign keys","Complex SQL joins, grouping, and aggregations","Prisma ORM schema definition and migrations","Database indexing and connection pooling"]'::jsonb, '3 Weeks', '[{"title":"freeCodeCamp: Relational Databases","url":"https://www.freecodecamp.org/learn/relational-database","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000008' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000106', r.id, 6, 'Authentication, Security, Docker & Cloud Deployment', 'प्रमाणीकरण (JWT), डॉकर कंटेनर और क्लाउड डिप्लॉयमेंट', 'యూజర్ సెక్యూరిటీ (JWT), డాకర్ & క్లౌడ్ డిప్లాయ్‌మెంట్', 'Implement JWT authentication with refresh tokens, package the full stack in Docker, and deploy frontend to Vercel and backend to Render/AWS.', 'JWT ऑथेंटिकेशन, डॉकर कंटेनराइजेशन और वर्सेल/रेंडर पर फुल-स्टैक ऐप को लाइव करना।', 'JWT లాగిన్ సెక్యూరిటీ, డాకర్ కంటైనర్లు మరియు ఫుల్ స్టాక్ వెబ్ యాప్‌ను క్లౌడ్‌లో హోస్ట్ చేయడం.', 'Deploy a full-stack authenticated web app live on custom public URLs', '[]'::jsonb, '["JWT authentication and password hashing with bcrypt","CORS, helmet, and secure cookies","Docker containerization of client and server","Full stack cloud deployment (Vercel + Render + Supabase/PostgreSQL)"]'::jsonb, '4 Weeks', '[{"title":"Docker Getting Started Guide","url":"https://docs.docker.com","provider":"Docker","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000008' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000107', r.id, 7, 'Full Stack Capstone Portfolio & Job Applications', 'कैपस्टोन पोर्टफोलियो प्रोजेक्ट और फुल स्टैक नौकरी आवेदन', 'ఫుల్ స్టాక్ పోర్ట్‌ఫోలియో ప్రాజెక్ట్ & ఉద్యోగ దరఖాస్తులు', 'Polish an end-to-end full stack capstone application (e.g. Learning Management System / Rural Marketplace), build portfolio, and apply for roles.', 'एक संपूर्ण लाइव कैपस्टोन प्रोजेक्ट तैयार करें, तकनीकी रिज्यूमे बनाएं और सॉफ्टवेयर कंपनियों में आवेदन करें।', 'పూర్తి స్థాయి క్యాప్‌స్టోన్ ప్రాజెక్ట్‌ను పూర్తి చేసి, సాఫ్ట్‌వేర్ కంపెనీలలో ఉద్యోగాలకు దరఖాస్తు చేసుకోండి.', 'Apply to verified Junior Full Stack Developer positions with live demo links', '["NAPS Apprenticeship in Software Development"]'::jsonb, '["Building an end-to-end full stack capstone project","Writing comprehensive GitHub README documentation","Full stack technical interview preparation","Applying to 20+ Junior Full Stack roles on LinkedIn and Naukri"]'::jsonb, '3 Weeks', '[{"title":"LinkedIn India Full Stack Jobs","url":"https://www.linkedin.com/jobs","provider":"LinkedIn","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000008' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000023', 'Personalized Agriculture Extension Worker Learning Pathway', 5, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000231', r.id, 1, 'Soil Science, Soil Health Card Testing & Crop Nutrition', 'मृदा विज्ञान, सॉइल हेल्थ कार्ड परीक्षण और फसल पोषण', 'భూసార శాస్త్రం, సాయిల్ హెల్త్ కార్డ్ పరీక్షలు & పంట పోషణ', 'Understand soil textures (alluvial, black, red), pH levels, NPK macro-nutrients, micro-nutrients deficiency symptoms, and how to operate portable soil testing kits.', 'मिट्टी की बनावट, पीएच मान, एनपीके पोषक तत्व और सॉइल टेस्टिंग किट का उपयोग सीखें।', 'నేల రకాలు, pH విలువలు, NPK పోషకాలు మరియు భూసార పరీక్ష కిట్లను వాడటం నేర్చుకోండి.', 'Collect 3 soil samples and generate mock Soil Health Card advice', '["National Mission for Sustainable Agriculture (NMSA)"]'::jsonb, '["Soil sample collection protocol across 5-acre plots","Testing soil pH, electrical conductivity, and organic carbon","Interpreting Soil Health Card recommendations","Recommending organic compost vs chemical fertilizers"]'::jsonb, '4 Weeks', '[{"title":"Soil Health Card Portal Guide","url":"https://soilhealth.dac.gov.in","provider":"Ministry of Agriculture","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000023' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000232', r.id, 2, 'Modern Seed Selection, Germination & Integrated Pest Management (IPM)', 'उन्नत बीज चयन, अंकुरण और एकीकृत कीट प्रबंधन (IPM)', 'మేలైన విత్తనాల ఎంపిక & సమగ్ర సస్యరక్షణ (IPM)', 'Master certified hybrid seeds, seed treatment with Trichoderma, identifying destructive bollworms and stem borers, and preparing organic bio-pesticides (Neemastra/Brahmastra).', 'हाइब्रिड बीज चयन, बीजोपचार, कीटों की पहचान और जैविक कीटनाशक (नीमास्त्र/ब्रह्मास्त्र) बनाना सीखें।', 'హైబ్రిడ్ విత్తనాలు, విత్తన శుద్ధి, పురుగుల నివారణ మరియు సేంద్రీయ కషాయాలు తయారు చేయడం.', 'Formulate an Integrated Pest Management schedule for paddy/cotton', '["Paramparagat Krishi Vikas Yojana (PKVY)"]'::jsonb, '["Seed germination percentage testing methods","Seed inoculation with Rhizobium and Azotobacter","Identification of sucking pests, caterpillars, and fungal blights","Formulating neem-based bio-pesticides and pheromone traps"]'::jsonb, '4 Weeks', '[{"title":"ICAR Krishi Portal - Crop Protection","url":"https://krishi.icar.gov.in","provider":"ICAR","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000023' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000233', r.id, 3, 'Micro-Irrigation, Drip/Sprinkler Systems & Smart Water Management', 'सूक्ष्म सिंचाई, ड्रिप/स्प्रिंकलर सिस्टम और जल प्रबंधन', 'సూక్ష్మ సేద్యం, డ్రిప్/స్ప్రింక్లర్ వ్యవస్థలు & నీటి యాజమాన్యం', 'Design and install drip irrigation lateral pipes, venturi injectors for fertigation, sand filters, and solar-powered water pump setups under PM-KUSUM.', 'ड्रिप व स्प्रिंकलर सिंचाई प्रणाली का लेआउट, वेंचुरी फर्टिगेशन और सोलर पंप लगाना।', 'డ్రిప్ మరియు స్ప్రింక్లర్ పైపుల అమరిక, ఫెర్టిగేషన్ మరియు సోలార్ పంపుల నిర్వహణ.', 'Draft a 1-hectare drip irrigation layout plan with component cost estimate', '["Pradhan Mantri Krishi Sinchayee Yojana (PMKSY) & PM-KUSUM"]'::jsonb, '["Water discharge calculation per dripper / emitter","Installing screen and disc filters to prevent clogging","Fertigation dosing via Venturi injector","PM-KUSUM solar agricultural pump operation"]'::jsonb, '3 Weeks', '[{"title":"PM Krishi Sinchayee Yojana (PMKSY) Guidelines","url":"https://pmksy.gov.in","provider":"PMKSY","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000023' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000234', r.id, 4, 'Government Agri-Portals: e-NAM, PM-KISAN, e-Crop Booking & Subsidies', 'सरकारी कृषि पोर्टल: ई-नाम, पीएम-किसान, ई-क्रॉप बुकिंग व सब्सिडी', 'ప్రభుత్వ వ్యవసాయ పోర్టల్స్: e-NAM, PM-KISAN, ఈ-క్రాప్ బుకింగ్ & సబ్సిడీలు', 'Learn how to register village farmers on e-NAM digital mandi for fair pricing, verify land records on Webland/e-Crop, process PM-KISAN KYC, and file crop insurance claims (PMFBY).', 'ई-नाम मंडी पंजीकरण, ई-क्रॉप बुकिंग, पीएम-किसान केवाईसी और फसल बीमा (PMFBY) क्लेम प्रक्रिया।', 'e-NAM ఆన్‌లైన్ మార్కెట్, ఈ-క్రాప్ బుకింగ్, PM-KISAN ఈ-కేవైసీ మరియు పంట బీమా దరఖాస్తు.', 'Demonstrate registering a mock farmer profile on the e-NAM sandbox', '["PM-KISAN Samman Nidhi & PM Fasal Bima Yojana (PMFBY)"]'::jsonb, '["Farmer onboarding on e-NAM digital trading portal","e-Crop geo-tagging and crop survey verification","PM-KISAN eligibility criteria and dispute resolution","PMFBY crop loss assessment and claims filing"]'::jsonb, '3 Weeks', '[{"title":"National Agriculture Market (e-NAM)","url":"https://www.enam.gov.in","provider":"Ministry of Agriculture","is_free":true},{"title":"PM-KISAN Official Portal","url":"https://pmkisan.gov.in","provider":"Govt of India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000023' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000235', r.id, 5, 'Village Extension Practicum, Rythu Bharosa Kendram (RBK) & Employment', 'ग्राम विस्तार इंटर्नशिप, रायथू भरोसा केंद्र (RBK) और रोजगार', 'గ్రామ విస్తరణ ప్రాక్టికల్స్, రైతు భరోసా కేంద్రం (RBK) & ఉద్యోగం', 'Conduct field demonstrations for smallholder farmers, assist Village Agriculture Assistants at RBKs, prepare for state agriculture exams, and apply to agri-input companies.', 'किसानों के लिए फील्ड प्रदर्शन, आरबीके केंद्र पर सहायता और कृषि सहायक परीक्षा की तैयारी।', 'రైతులకు క్షేత్రస్థాయి ప్రదర్శనలు, RBK లలో అనుభవం మరియు అగ్రికల్చర్ అసిస్టెంట్ పరీక్షలు.', 'Complete a 15-day village field diary and submit your extension resume', '["AP Rythu Bharosa & NAPS Agriculture Apprenticeship"]'::jsonb, '["Conducting village farmer meetings (Kisan Gosthi)","Operating Custom Hiring Centre (CHC) farm machinery tools","Preparation for Village Agriculture Assistant (VAA) exam","Applying to certified seed, fertilizer, and irrigation companies"]'::jsonb, '4 Weeks', '[{"title":"AP Rythu Bharosa Kendram Portal","url":"https://rbk.ap.gov.in","provider":"Govt of AP","is_free":true},{"title":"NCS Agriculture Jobs","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000023' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000024', 'Personalized Certified Electrician Learning Pathway', 5, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000241', r.id, 1, 'Electrical Safety Standards, PPE & Industrial Tools Mastery', 'विद्युत सुरक्षा मानक, पीपीई और औद्योगिक औजारों का उपयोग', 'ఎలక్ట్రికల్ భద్రతా ప్రమాణాలు, PPE & టూల్స్ వాడకం', 'Master electrical safety protocols (IS 732), insulated screwdrivers, pliers, crimpers, wire strippers, digital multimeter, and tong tester usage.', 'विद्युत सुरक्षा नियम (IS 732), इंसुलेटेड टूल्स, मल्टीमीटर और टोंग टेस्टर का सही उपयोग।', 'విద్యుత్ భద్రతా నియమాలు (IS 732), ఇన్సులేటెడ్ పరికరాలు మరియు మల్టీమీటర్ వాడకం.', 'Inspect an electrical tool kit for insulation integrity and safety', '["PMKVY 4.0 Free Technical Training"]'::jsonb, '["Electrical shock resuscitation and first aid","IS 732 code for electrical wiring installations","Measuring voltage, AC/DC current, and continuity","Safe use of conduit benders and crimping tools"]'::jsonb, '3 Weeks', '[{"title":"Bharat Skills Electrician Trade Theory","url":"https://bharatskills.gov.in","provider":"DGT / Bharat Skills","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000024' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000242', r.id, 2, 'Domestic Conduit Routing, Concealed House Wiring & Distribution Boards', 'घरेलू वायरिंग, कंसील्ड पाइपिंग और वितरण बोर्ड (Distribution Board)', 'గృహ వైరింగ్, కన్సీల్డ్ పైపులు & డిస్ట్రిబ్యూషన్ బోర్డులు', 'Read architectural single-line electrical diagrams, route PVC conduits, install MCB/RCCB distribution boards, and wire 2-way staircase switches.', 'सिंगल-लाइन डायग्राम पढ़ना, पीवीसी पाइप बिछाना, एमसीबी/आरसीसीबी बोर्ड लगाना और सीढ़ियों की 2-वे वायरिंग।', 'ఎలక్ట్రికల్ ప్లాన్ చదవడం, కన్సీల్డ్ వైరింగ్ పైపులు వేయడం, MCB/RCCB బోర్డులు అమర్చడం.', 'Wire a practical 2-switch, 1-socket distribution board with MCB protection', '["PM Vishwakarma Toolkit Incentive Scheme (₹15,000)"]'::jsonb, '["Calculating domestic wire gauge (1.0 sq mm to 6.0 sq mm)","Sizing MCBs (6A, 16A, 32A) and RCCB (30mA residual current)","Concealed metal box fixing and conduit channeling","Wiring switches, 3-pin sockets, fans, and staircase light circuits"]'::jsonb, '4 Weeks', '[{"title":"NIMI Electrician Practical Modules","url":"https://nimi.gov.in","provider":"NIMI","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000024' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000243', r.id, 3, 'AC Motors, Submersible Starters & Industrial Control Panels', 'एसी मोटर, सबमर्सिबल स्टार्टर और कंट्रोल पैनल', 'AC మోటార్లు, సబ్‌మెర్సిబుల్ స్టార్టర్లు & కంట్రోల్ ప్యానెల్స్', 'Understand 1-phase and 3-phase induction motors, connect Direct-On-Line (DOL) and Star-Delta starters, and wire submersible pump control panels.', 'सिंगल व थ्री फेज मोटर, डीओएल और स्टार-डेल्टा स्टार्टर कनेक्शन और सबमर्सिबल पंप वायरिंग।', '1-ఫేజ్, 3-ఫేజ్ మోటార్లు, DOL & స్టార్-డెల్టా స్టార్టర్లు మరియు మోటార్ పంపుల కనెక్షన్లు.', 'Connect and test a 3-phase motor with forward-reverse and overload protection', '["PMKVY 4.0 Skill Certification"]'::jsonb, '["Working principle of single-phase capacitor-start motors","Wiring 3-phase induction motor with DOL starter and overload relay","Star-Delta starter control circuit testing","Troubleshooting agricultural pump starter capacitors and contractors"]'::jsonb, '4 Weeks', '[{"title":"Bharat Skills Motor & Transformer Labs","url":"https://bharatskills.gov.in","provider":"DGT","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000024' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000244', r.id, 4, 'Earthing Systems, Earth Resistance Megger Testing & Fault Clearance', 'अर्थिंग सिस्टम, मेगर अर्थ रेसिस्टेंस टेस्टिंग और फॉल्ट डायग्नोस्टिक्स', 'ఎర్తింగ్ విధానాలు, మెగ్గర్ టెస్టింగ్ & ఫాల్ట్ రిపేర్లు', 'Install chemical pipe earthing and plate earthing, measure earth resistance with a digital earth tester (Megger < 5 Ohms), and clear short circuits.', 'केमिकल पाइप और प्लेट अर्थिंग लगाना, मेगर से अर्थ रेसिस्टेंस नापना और शॉर्ट सर्किट ठीक करना।', 'పైప్ & ప్లేట్ ఎర్తింగ్ చేయడం, మెగ్గర్ ద్వారా ఎర్త్ రెసిస్టెన్స్ పరీక్షించడం, షార్ట్ సర్క్యూట్లను బాగు చేయడం.', 'Perform a live earth resistance test on a building electrode using a digital earth tester', '[]'::jsonb, '["Pipe earthing pit preparation with bentonite compound and salt","Megger earth electrode resistance measurement (< 5 Ohms)","Identifying neutral link breaks and leakage currents","Surge protection device (SPD) installation"]'::jsonb, '3 Weeks', '[{"title":"Central Electricity Authority Safety Regulations","url":"https://cea.nic.in","provider":"CEA","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000024' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000245', r.id, 5, 'State Wireman License, NAPS Apprenticeship & Professional Practice', 'स्टेट वायरमैन लाइसेंस, नैप्स अप्रेंटिसशिप और सरकारी/निजी रोजगार', 'స్టేట్ వైర్‌మెన్ లైసెన్స్, NAPS అప్రెంటిస్‌షిప్ & ఉద్యోగం', 'Prepare for the State Electrical Licensing Board Wireman examination, register for a paid industrial apprenticeship on NAPS, and start licensed practice.', 'वायरमैन लाइसेंस परीक्षा की तैयारी, नैप्स पोर्टल पर अप्रेंटिसशिप और डिस्कॉम/उद्योगों में रोजगार।', 'ఎలక్ట్రికల్ లైసెన్సింగ్ బోర్డు వైర్‌మెన్ పరీక్ష, NAPS అప్రెంటిస్‌షిప్ మరియు డిస్కామ్/ప్రైవేట్ ఉద్యోగాలు.', 'Apply for 2 certified electrical apprenticeships on the NAPS portal', '["National Apprenticeship Promotion Scheme (NAPS 2.0) with monthly stipend"]'::jsonb, '["State Wireman Competency Certificate syllabus preparation","Registration on National Apprenticeship Promotion Scheme (NAPS)","Applying for DISCOM junior lineman / substation attendant roles","Pricing domestic and commercial electrical contracting projects"]'::jsonb, '3 Weeks', '[{"title":"National Apprenticeship Portal (NAPS 2.0)","url":"https://www.apprenticeshipindia.gov.in","provider":"MSDE","is_free":true},{"title":"National Career Service Portal","url":"https://www.ncs.gov.in","provider":"Ministry of Labour","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000024' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000002', 'Personalized Organic Farm & Soil Supervisor Pathway', 4, '4 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000301', r.id, 1, 'Soil Sampling, pH Testing & Nutrient Diagnostics', 'मिट्टी का नमूना, पीएच परीक्षण और पोषक तत्व जांच', 'నేల నమూనా సేకరణ, pH పరీక్ష & పోషకాల విశ్లేషణ', 'Collect representative village farm soil samples, operate field soil testing kits for pH, EC, and NPK, and interpret Soil Health Cards.', 'गांव के खेतों से मिट्टी के नमूने लें, पीएच/एनपीके किट से जांच करें और मृदा स्वास्थ्य कार्ड पढ़ें।', 'పొలం మట్టి నమూనాలు సేకరించి, pH/NPK పరీక్షలు చేయడం మరియు సాయిల్ హెల్త్ కార్డ్ అర్థం చేసుకోవడం.', 'Test 3 local soil samples and draft fertilizer recommendations', '["Soil Health Card Scheme"]'::jsonb, '["Grid soil sampling across farmland","Measuring pH and organic carbon","Recommending organic compost amendments"]'::jsonb, '4 Weeks', '[{"title":"ICAR Soil Health Portal","url":"https://soilhealth.dac.gov.in","provider":"Ministry of Agriculture","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000002' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000302', r.id, 2, 'Vermicomposting, Bio-Fertilizers & Natural Inputs', 'वर्मीकम्पोस्ट, जैव-उर्वरक और प्राकृतिक खाद निर्माण', 'వర్మీ కంపోస్ట్, జీవ ఎరువులు & సహజ సాగు పద్ధతులు', 'Set up Eisenia fetida vermicompost pits, prepare Panchagavya and Jeevamrut bio-inputs, and manage natural crop residue decomposition.', 'केंचुआ खाद बेड तैयार करें और जीवामृत व जैव-उर्वरक बनाने की विधि सीखें।', 'వర్మీ కంపోస్ట్ బెడ్ల నిర్మాణం, జీవామృతం మరియు సేంద్రీయ ఎరువుల తయారీ.', 'Design a low-cost rural vermicompost pit blueprint', '["Paramparagat Krishi Vikas Yojana (PKVY)"]'::jsonb, '["Building shade-protected vermicompost beds","Moisture & temperature monitoring","Formulating bio-enriched organic manure"]'::jsonb, '4 Weeks', '[{"title":"ICAR Krishi Portal","url":"https://krishi.icar.gov.in","provider":"ICAR","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000002' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000303', r.id, 3, 'Drip Micro-Irrigation & Organic Pest Control (IPM)', 'ड्रिप सिंचाई और एकीकृत कीट प्रबंधन (IPM)', 'బిందు సేద్యం & సమగ్ర సస్యరక్షణ (IPM)', 'Maintain drip lateral lines and emitters, deploy pheromone traps, and formulate neem-based botanical sprays for organic certification compliance.', 'ड्रिप पाइप की सफाई और नीम आधारित जैविक कीट नियंत्रण विधियों का अभ्यास करें।', 'డ్రిప్ పైపుల నిర్వహణ, ఫెరోమోన్ ట్రాప్స్ మరియు వేప నూనె పిచికారీ విధానాలు.', 'Prepare an organic pest prevention calendar for 2 seasonal crops', '["PM Krishi Sinchayee Yojana"]'::jsonb, '["Drip emitter pressure & flush maintenance","Identifying pest life cycles","Preparing neem kernel extracts"]'::jsonb, '4 Weeks', '[{"title":"PMKSY Micro-Irrigation Guide","url":"https://pmksy.gov.in","provider":"Govt of India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000002' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000304', r.id, 4, 'PGS-India Organic Certification & FPO Employment', 'पीजीएस-इंडिया जैविक प्रमाणीकरण और एफपीओ रोजगार', 'PGS-ఇండియా ఆర్గానిక్ సర్టిఫికేషన్ & FPO ఉపాధి', 'Register farmer groups on PGS-India portal, maintain inspection logs for premium organic market pricing, and join Farmer Producer Organizations.', 'किसान समूहों को पीजीएस-इंडिया पोर्टल पर पंजीकृत करें और एफपीओ पर्यवेक्षक के रूप में कार्य करें।', 'PGS-ఇండియా పోర్టల్‌లో రైతు గ్రూపుల నమోదు మరియు FPO సూపర్‌వైజర్ ఉద్యోగ అవకాశాలు.', 'Complete sample documentation for an organic FPO cluster', '["PKVY & Mission Organic Value Chain"]'::jsonb, '["PGS-India peer review inspection forms","APEDA NPOP export standards","Connecting FPOs to e-NAM markets"]'::jsonb, '4 Weeks', '[{"title":"PGS-India Organic Portal","url":"https://pgsindia-ncof.gov.in","provider":"NCOF","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000002' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000003', 'Personalized EV Two-Wheeler Service Specialist Pathway', 4, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000305', r.id, 1, 'EV Powertrain Architecture & High-Voltage Safety', 'ईवी पावरट्रेन संरचना और हाई-वोल्टेज सुरक्षा', 'EV పవర్‌ట్రెయిన్ నిర్మాణం & హై-వోల్టేజ్ భద్రత', 'Learn BLDC hub motors, permanent magnet synchronous motors, sine-wave controllers, and personal insulated tool safety around 48V-72V DC traction systems.', 'बीएलडीसी मोटर, कंट्रोलर और 48V-72V बैटरी सिस्टम पर सुरक्षित कार्य के नियम सीखें।', 'BLDC హబ్ మోటార్లు, కంట్రోలర్లు మరియు 48V-72V బ్యాటరీ భద్రతా ప్రమాణాలు నేర్చుకోండి.', 'Inspect Hall sensors and phase resistance on an electric scooter motor', '["PMKVY 4.0 Automotive Skilling"]'::jsonb, '["BLDC motor phase & Hall sensor testing","DC-DC converter functioning","Insulated glove & arc-flash precautions"]'::jsonb, '4 Weeks', '[{"title":"Skill India EV Technician Modules","url":"https://www.skillindiadigital.gov.in","provider":"SIDH / ASDC","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000003' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000306', r.id, 2, 'Lithium-Ion Battery Packs & BMS Diagnostics', 'लिथियम-आयन बैटरी पैक और बीएमएस जांच', 'లిథియం-అయాన్ బ్యాటరీ & BMS డయాగ్నోస్టిక్స్', 'Understand LFP/NMC cell chemistry, Battery Management System (BMS) balancing, CAN-bus voltage monitoring, and thermal cutoff troubleshooting.', 'एलएफपी व एनएमसी सेल, बीएमएस सेल बैलेंसिंग और थर्मल सेंसर जांच करना सीखें।', 'లిథియం సెల్స్, BMS వోల్టేజ్ బ్యాలెన్సింగ్ మరియు టెంపరేచర్ సెన్సార్ తనిఖీ.', 'Measure cell-group balance across a 16S/20S EV battery pack', '["ASDC EV Specialization Grant"]'::jsonb, '["Testing individual cell series voltages","Diagnosing BMS cutoff faults","Safe lithium battery handling & storage"]'::jsonb, '6 Weeks', '[{"title":"NPTEL Electric Vehicle Fundamentals","url":"https://nptel.ac.in","provider":"NPTEL","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000003' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000307', r.id, 3, 'OBD Diagnostic Scanners & Throttle/Brake Servicing', 'ओबीडी स्कैनर डायग्नोस्टिक्स और मैकेनिकल सर्विसिंग', 'OBD స్కానర్ డయాగ్నోస్టిక్స్ & మెకానికల్ సర్వీసింగ్', 'Connect EV OBD-II diagnostic tools to clear fault codes, calibrate regenerative braking switches, and service combi-brakes and suspension.', 'ओबीडी स्कैनर से फॉल्ट कोड पढ़ना, थ्रॉटल सेंसर और ब्रेकिंग सिस्टम की सर्विसिंग करना।', 'OBD స్కానర్ ద్వారా ఎర్రర్ కోడ్లు సరిచేయడం, థ్రోటిల్ & బ్రేక్ సిస్టమ్ సర్వీసింగ్.', 'Diagnose and clear a simulated throttle/Hall-sensor error log', '[]'::jsonb, '["Reading CAN error codes with scanner","Testing side-stand & brake cut-off sensors","EV wheel bearing and disc pad servicing"]'::jsonb, '6 Weeks', '[{"title":"Bharat Skills Mechanic EV Content","url":"https://bharatskills.gov.in","provider":"DGT","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000003' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000308', r.id, 4, 'Dealership Apprenticeship (NAPS) & Independent EV Workshop', 'ईवी शोरूम अप्रेंटिसशिप (NAPS) और रोजगार', 'EV షోరూమ్ అప్రెంటిస్‌షిప్ (NAPS) & స్వయం ఉపాధి', 'Apply for stipended apprenticeships at Ola, Ather, TVS, Hero Electric, or Bajaj EV dealerships through NAPS 2.0 or launch a multi-brand EV garage.', 'नैप्स 2.0 के माध्यम से प्रमुख ईवी डीलरशिप में अप्रेंटिसशिप प्राप्त करें या अपना ईवी सर्विस सेंटर खोलें।', 'NAPS 2.0 ద్వారా ఈవీ కంపెనీలలో అప్రెంటిస్‌షిప్ మరియు సర్వీస్ టెక్నీషియన్ ఉద్యోగం.', 'Apply to 3 EV service technician openings on NAPS / NCS', '["NAPS 2.0 Stipend Scheme","PM MUDRA Yojana"]'::jsonb, '["Warranty documentation & customer service","NAPS portal EV dealership onboarding","Estimating MUDRA toolkit capital for EV garage"]'::jsonb, '4 Weeks', '[{"title":"Apprenticeship India (NAPS)","url":"https://www.apprenticeshipindia.gov.in","provider":"MSDE","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000003' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000004', 'Personalized Rural Community Health Facilitator Pathway', 4, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000309', r.id, 1, 'Human Anatomy, Hygiene & Essential Clinical Vitals', 'मानव शरीर रचना, स्वच्छता और वाइटल जांच', 'శరీర నిర్మాణం, పరిశుభ్రత & ప్రాథమిక ఆరోగ్య పరీక్షలు', 'Learn foundational anatomy, infection prevention, and accurate measurement of blood pressure, SpO2, temperature, pulse, and glucometer blood sugar.', 'बीपी, शुगर, ऑक्सीजन और तापमान सही ढंग से नापने तथा संक्रमण नियंत्रण के नियम सीखें।', 'బీపీ, షుగర్, పల్స్ ఆక్సిమీటర్ మరియు జ్వరం తనిఖీ చేయడం, శుభ్రతా నియమాలు నేర్చుకోవడం.', 'Record and log complete clinical vitals accurately for 5 practice profiles', '["Skill India HSSC Healthcare Program"]'::jsonb, '["Accurate BP & pulse oximeter readings","Biomedical waste color-coding rules","Infection control & hand hygiene"]'::jsonb, '5 Weeks', '[{"title":"National Health Mission Training Portal","url":"https://nhm.gov.in","provider":"MoHFW","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000004' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000310', r.id, 2, 'Maternal, Child Nutrition & Immunization Outreach', 'मातृ एवं शिशु पोषण व टीकाकरण अभियान', 'మాతా శిశు పోషణ & టీకాల కార్యక్రమం', 'Support pregnant mothers and infants under POSHAN Abhiyaan, track universal immunization schedules, and identify anemia/malnutrition early warning signs.', 'गर्भवती महिलाओं और बच्चों के पोषण व नियमित टीकाकरण शेड्यूल की निगरानी सीखें।', 'గర్భిణీలు & పిల్లల పోషకాహారం, టీకాల తేదీలు మరియు రక్తహీనత గుర్తింపు.', 'Draft an immunization & antenatal village follow-up checklist', '["National Health Mission & POSHAN Abhiyaan"]'::jsonb, '["Tracking Indradhanush vaccination milestones","ORS preparation & dehydration care","Nutrition counseling for rural families"]'::jsonb, '6 Weeks', '[{"title":"POSHAN & NHM Guidelines","url":"https://nhm.gov.in","provider":"NHM","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000004' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000311', r.id, 3, 'Digital Health Cards (ABHA), Telemedicine & First Aid', 'आयुष्मान भारत हेल्थ कार्ड (ABHA), टेलीमेडिसिन और प्राथमिक चिकित्सा', 'ఆయుష్మాన్ ABHA కార్డ్, టెలిమెడిసిన్ & ప్రథమ చికిత్స', 'Register villagers for Ayushman Bharat Health Account (ABHA) IDs, facilitate e-Sanjeevani doctor tele-consultations, and provide CPR/snakebite/fracture first aid.', 'ई-संजीवनी टेलीमेडिसिन पर डॉक्टर परामर्श करवाना और आभा हेल्थ कार्ड बनाना सीखें।', 'ABHA హెల్త్ ఐడీ నమోదు, e-Sanjeevani టెలిమెడిసిన్ కనెక్షన్ మరియు ప్రథమ చికిత్స.', 'Walk through a mock e-Sanjeevani rural clinic tele-consult workflow', '["Ayushman Bharat Digital Mission"]'::jsonb, '["e-Sanjeevani tele-consultation assistance","Creating ABHA digital IDs","Emergency CPR & wound bandaging"]'::jsonb, '5 Weeks', '[{"title":"e-Sanjeevani National Telemedicine","url":"https://esanjeevani.mohfw.gov.in","provider":"MoHFW","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000004' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000312', r.id, 4, 'PHC Practicum & Community Health Center Placement', 'प्राथमिक स्वास्थ्य केंद्र (PHC) प्रशिक्षण व रोजगार', 'PHC ప్రాక్టికల్స్ & ఆరోగ్య కేంద్రం ఉద్యోగ దరఖాస్తులు', 'Complete practical field observership at a local Primary Health Centre or Health & Wellness Centre and apply for contractual/NGO community health openings.', 'नजदीकी प्राथमिक स्वास्थ्य केंद्र में व्यावहारिक अनुभव लें और स्वास्थ्य सहायक पदों हेतु आवेदन करें।', 'స్థానిక PHC కేంద్రంలో ప్రాక్టికల్ శిక్షణ పూర్తి చేసి హెల్త్ అసిస్టెంట్ ఉద్యోగాలకు దరఖాస్తు.', 'Apply to 2 community health or NGO clinical coordinator postings', '["PMKVY 4.0 Healthcare Skilling"]'::jsonb, '["Village health & sanitation camp reporting","Maintaining patient follow-up registers","Applying to NHM & rural NGO clinics"]'::jsonb, '4 Weeks', '[{"title":"National Career Service Healthcare","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000004' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000005', 'Personalized Village CSC Operator (VLE) Pathway', 4, '2 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000313', r.id, 1, 'Computer Literacy, Vernacular Typing & Scanner Setup', 'कंप्यूटर साक्षरता, टाइपिंग और स्कैनर/बायोमेट्रिक सेटअप', 'కంప్యూటర్ పరిజ్ఞానం, టైపింగ్ & బయోమెట్రిక్ సెటప్', 'Build speed in English and regional typing, configure fingerprint RD biometric drivers, resize passport/document PDFs to portal KB limits, and manage printers.', 'तेज टाइपिंग, बायोमेट्रिक फिंगरप्रिंट ड्राइवर और पोर्टल के अनुसार दस्तावेज स्कैन/रीसाइज करना सीखें।', 'టైపింగ్, ఫింగర్‌ప్రింట్ బయోమెట్రిక్ సెటప్ మరియు సర్టిఫికెట్ల PDF సైజు మార్చడం.', 'Practice converting and compressing 5 application documents cleanly', '["PMGDISHA / SIDH Digital Literacy"]'::jsonb, '["Fast keyboard entry & MS Word/Excel","Installing Mantra/Morpho RD biometric drivers","Scanning & compressing PDFs under 200KB"]'::jsonb, '2 Weeks', '[{"title":"Skill India Digital Literacy","url":"https://www.skillindiadigital.gov.in","provider":"SIDH","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000005' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000314', r.id, 2, 'Telecentre Entrepreneur Course (TEC) & CSC Portal Services', 'टेलीकेंद्र उद्यमी कोर्स (TEC) और डिजिटल सेवा पोर्टल', 'టెలిసెంటర్ ఆంట్రప్రెన్యూర్ కోర్సు (TEC) & డిజిసేవా పోర్టల్', 'Complete the mandatory CSC Academy TEC certificate covering GST billing, PAN/Passport applications, e-Shram cards, and online PM-KISAN services.', 'सीएससी अकादमी का टीईसी सर्टिफिकेट पूरा करें और पैन, पासपोर्ट, ई-श्रम व सरकारी आवेदन प्रक्रिया सीखें।', 'TEC సర్టిఫికెట్ పూర్తి చేసి పాన్ కార్డు, పాస్‌పోర్ట్, ఈ-శ్రమ్ మరియు ప్రభుత్వ సేవల దరఖాస్తులు నేర్చుకోండి.', 'Enroll and review the 10 modules of CSC TEC syllabus', '["Digital India Common Service Centre Initiative"]'::jsonb, '["Passing the official CSC TEC assessment","Submitting PAN, caste, and income certificate requests","Managing CSC Digital Seva wallet accounting"]'::jsonb, '3 Weeks', '[{"title":"CSC Academy TEC Portal","url":"https://www.cscacademy.org","provider":"CSC Academy","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000005' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000315', r.id, 3, 'DigiPay Aadhaar Banking, Insurance & Bill Services', 'डिजीपे आधार बैंकिंग (AePS), बीमा और बिल सेवाएं', 'డిజీపే ఆధార్ బ్యాంకింగ్ (AePS), బీమా & బిల్లు చెల్లింపులు', 'Deliver rural doorstep banking via DigiPay AePS biometric cash deposits/withdrawals, PMFBY crop insurance, FASTag recharge, and IRCTC rail ticketing.', 'गांव में डिजीपे से आधार द्वारा लेन-देन, फसल बीमा (PMFBY), बिजली बिल व रेल टिकट सेवा देना सीखें।', 'డిజీపే ద్వారా బ్యాంకింగ్, పంట బీమా, విద్యుత్ బిల్లులు మరియు రైల్వే టికెట్ సేవలు.', 'Map out monthly commission streams from 5 core citizen services', '["PM MUDRA Shishu Loan for Cyber Cafe Setup"]'::jsonb, '["Processing compliant AePS banking transactions","Filing PMFBY crop insurance premiums","Maintaining daily KYC transaction register"]'::jsonb, '2 Weeks', '[{"title":"Digital Seva CSC Portal","url":"https://digitalseva.csc.gov.in","provider":"CSC e-Governance","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000005' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000316', r.id, 4, 'Launch & Scale Your Village CSC Digital Seva Center', 'ग्रामीण डिजिटल सेवा केंद्र की स्थापना व संचालन', 'గ్రామీణ డిజిటల్ సేవా కేంద్రాన్ని ప్రారంభించండి', 'Apply for CSC VLE ID or partner with an existing Gram Panchayat center, set transparent rate charts, and apply for PM MUDRA shop hardware funding.', 'वीएलई पंजीकरण करें, पंचायत क्षेत्र में सेवा केंद्र खोलें और मुद्रा ऋण से प्रिंटर/कंप्यूटर जुटाएं।', 'CSC VLE రిజిస్ట్రేషన్ పూర్తి చేసి సొంత డిజిటల్ సేవా కేంద్రాన్ని ప్రారంభించండి.', 'Prepare equipment checklist (Laptop, Printer, Biometric Scanner) and VLE plan', '["PM MUDRA Yojana","Digital India VLE Program"]'::jsonb, '["CSC VLE application verification steps","Citizen privacy and cyber safety norms","Applying for ₹50,000 MUDRA Shishu equipment loan"]'::jsonb, '1 Week', '[{"title":"PM MUDRA Yojana Portal","url":"https://www.mudra.org.in","provider":"DFS Govt of India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000005' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000009', 'Personalized Software Engineer Learning Pathway', 4, '8 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000317', r.id, 1, 'Core Programming Mastery (Python / Java / C++) & OOP', 'मुख्य प्रोग्रामिंग (Python / Java / C++) और OOP सिद्धांत', 'కోర్ ప్రోగ్రామింగ్ (Python / Java / C++) & OOP సూత్రాలు', 'Build rock-solid programming foundations: control flow, recursion, pointers/references, classes, inheritance, polymorphism, and exception handling.', 'फंक्शन्स, रिकर्शन, ऑब्जेक्ट-ओरिएंटेड प्रोग्रामिंग (OOP) और कोड डीबगिंग में महारत हासिल करें।', 'ఫంక్షన్లు, రికర్షన్ మరియు ఆబ్జెక్ట్ ఓరియెంటెడ్ ప్రోగ్రామింగ్ (OOP) పూర్తిగా నేర్చుకోండి.', 'Solve 30 foundational coding problems using OOP classes', '["SWAYAM / NPTEL Free IIT Certification"]'::jsonb, '["Clean modular functions and recursion","OOP encapsulation, inheritance & interfaces","Writing unit tests and reading stack traces"]'::jsonb, '6 Weeks', '[{"title":"NPTEL Programming & Data Structures (IIT Madras)","url":"https://nptel.ac.in/courses/106106145","provider":"NPTEL / IIT Madras","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000009' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000318', r.id, 2, 'Data Structures & Algorithms (DSA) for Interviews', 'डेटा स्ट्रक्चर्स और एल्गोरिदम (DSA) व समस्या समाधान', 'డేటా స్ట్రక్చర్స్ & అల్గోరిథమ్స్ (DSA) ఇంటర్వ్యూ సన్నద్ధత', 'Master Arrays, Linked Lists, Stacks, Queues, Hash Maps, Trees, Graphs, Sorting, Binary Search, and Dynamic Programming with Big-O complexity analysis.', 'एरे, लिंक्ड लिस्ट, हैश मैप, ट्री, ग्राफ और डायनेमिक प्रोग्रामिंग की समय जटिलता (Big-O) का अभ्यास करें।', 'అర్రేలు, లింక్డ్ లిస్టులు, ట్రీస్, గ్రాఫ్స్ మరియు బైనరీ సెర్చ్ అల్గోరిథంలు నేర్చుకోండి.', 'Implement Binary Search, HashMap, and BFS graph traversal from scratch', '["NASSCOM FutureSkills Prime"]'::jsonb, '["Analyzing Time & Space complexity O(n)","Implementing Trees, Graphs & BFS/DFS","Solving 100+ DSA coding interview problems"]'::jsonb, '8 Weeks', '[{"title":"freeCodeCamp Algorithms & Data Structures","url":"https://www.freecodecamp.org","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000009' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000319', r.id, 3, 'Relational Databases (SQL), Git & Production Engineering', 'डेटाबेस (SQL), गिट और सॉफ्टवेयर आर्किटेक्चर', 'SQL డేటాబేస్, గిట్ (Git) & సాఫ్ట్‌వేర్ ఇంజనీరింగ్', 'Write normalized SQL joins and indexes, design modular system APIs, collaborate via Git pull requests, and implement automated CI test pipelines.', 'SQL जॉइन्स, इंडेक्सिंग, गिट ब्रांचिंग और ऑटोमेटेड टेस्टिंग पाइपलाइन बनाना सीखें।', 'SQL క్వెరీలు, గిట్ వర్షన్ కంట్రోల్ మరియు ఆటోమేటెడ్ టెస్టింగ్ నేర్చుకోండి.', 'Build a tested CLI or Web service backed by SQL and hosted on GitHub', '[]'::jsonb, '["ACID transactions and SQL indexing","Git branching and code review workflows","System design fundamentals (caching, REST APIs)"]'::jsonb, '6 Weeks', '[{"title":"freeCodeCamp Relational Database Course","url":"https://www.freecodecamp.org/learn/relational-database","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000009' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000320', r.id, 4, 'System Projects, Mock Interviews & Campus/Tech Hiring', 'लाइव प्रोजेक्ट पोर्टफोलियो और सॉफ्टवेयर इंजीनियर भर्ती', 'ప్రాజెక్ట్ పోర్ట్‌ఫోలియో, మాక్ ఇంటర్వ్యూలు & ఉద్యోగ దరఖాస్తులు', 'Polish 2 scalable engineering projects on GitHub, practice behavioral & system-design interviews, and apply via NATS, AICTE Internships, LinkedIn, and NCS.', 'गिटहब पर 2 बड़े प्रोजेक्ट होस्ट करें और लिंक्डइन, एनसीएस व नैट्स 2.0 पर आवेदन करें।', 'గిట్‌హబ్ ప్రాజెక్టులు ప్రదర్శించి, LinkedIn మరియు NATS 2.0 ద్వారా సాఫ్ట్‌వేర్ ఉద్యోగాలకు దరఖాస్తు.', 'Submit applications to 10 verified Junior SDE / Internship roles', '["NATS 2.0 Graduate Apprenticeship","PM Internship Scheme"]'::jsonb, '["Building production-ready README & tests","Technical coding + behavioral interview prep","Applying on NATS 2.0, AICTE & LinkedIn"]'::jsonb, '6 Weeks', '[{"title":"AICTE National Internship Portal","url":"https://internship.aicte-india.org","provider":"AICTE","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000009' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000011', 'Personalized Data Scientist Learning Pathway', 4, '9 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000321', r.id, 1, 'Python Scientific Stack: NumPy, Pandas & Data Wrangling', 'पायथन डेटा साइंस स्टैक: NumPy और Pandas', 'పైథాన్ డేటా సైన్స్: NumPy & Pandas', 'Clean real-world messy CSV datasets, handle missing values, compute vectorized aggregations with NumPy/Pandas, and plot exploratory charts.', 'NumPy और Pandas से बड़े डेटासेट साफ करना, समूहीकरण और विज़ुअलाइज़ेशन सीखें।', 'NumPy & Pandas తో పెద్ద డేటాను శుభ్రపరచడం మరియు విశ్లేషించడం నేర్చుకోండి.', 'Analyze an Indian public agricultural or weather dataset in a Jupyter notebook', '["SWAYAM Free Data Science"]'::jsonb, '["Pandas DataFrames & groupby pipelines","Vectorized NumPy matrix operations","Matplotlib & Seaborn exploratory charts"]'::jsonb, '6 Weeks', '[{"title":"freeCodeCamp Data Analysis with Python","url":"https://www.freecodecamp.org/learn/data-analysis-with-python","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000011' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000322', r.id, 2, 'Probability, Statistics & SQL Analytical Queries', 'संभाव्यता (Probability), सांख्यिकी और SQL विश्लेषण', 'సంభావ్యత, స్టాటిస్టిక్స్ & SQL విశ్లేషణ', 'Master distributions, hypothesis testing, p-values, A/B experiment design, linear algebra vectors, and analytical SQL window functions.', 'सांख्यिकीय परीक्षण, संभाव्यता वितरण, ए/बी टेस्टिंग और SQL विंडो फंक्शन्स का अभ्यास करें।', 'స్టాటిస్టికల్ డిస్ట్రిబ్యూషన్లు, A/B టెస్టింగ్ మరియు SQL విండో ఫంక్షన్లు నేర్చుకోండి.', 'Run statistical significance tests on a sample A/B conversion dataset', '[]'::jsonb, '["Probability distributions & Bayes theorem","Hypothesis testing & confidence intervals","SQL window functions & CTEs"]'::jsonb, '6 Weeks', '[{"title":"Khan Academy Statistics & Probability","url":"https://www.khanacademy.org/math/statistics-probability","provider":"Khan Academy","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000011' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000323', r.id, 3, 'Supervised & Unsupervised Machine Learning (Scikit-Learn)', 'मशीन लर्निंग एल्गोरिदम (Scikit-Learn)', 'మెషిన్ లెర్నింగ్ అల్గోరిథమ్స్ (Scikit-Learn)', 'Train regression, decision trees, random forests, gradient boosting, and k-means clustering models, evaluating cross-validated precision, recall, and RMSE.', 'रिग्रेशन, रैंडम फॉरेस्ट और क्लस्टरिंग मॉडल ट्रेन करें और सटीकता का मूल्यांकन सीखें।', 'రిగ్రెషన్, రాండమ్ ఫారెస్ట్ మరియు క్లస్టరింగ్ మోడల్స్ తయారు చేసి పరీక్షించండి.', 'Build and evaluate a crop yield or house price prediction model', '["NPTEL IIT Certification"]'::jsonb, '["Train/validation/test splitting without leakage","Feature engineering & encoding pipelines","Model evaluation metrics (F1, ROC-AUC, RMSE)"]'::jsonb, '10 Weeks', '[{"title":"SWAYAM Machine Learning (IIT Kharagpur)","url":"https://swayam.gov.in","provider":"SWAYAM / IIT KGP","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000011' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000324', r.id, 4, 'Model Deployment (FastAPI), Portfolio & ML Internships', 'मॉडल डिप्लॉयमेंट (FastAPI) और डेटा साइंस इंटर्नशिप', 'మోడల్ డిప్లాయ్‌మెంట్ (FastAPI) & ఇంటర్న్‌షిప్ దరఖాస్తులు', 'Expose trained scikit-learn models behind a FastAPI REST microservice, document notebooks on GitHub, and apply to analytics/ML internships.', 'ट्रेन किए गए मॉडल को FastAPI एपीआई के रूप में लाइव करें और डेटा साइंस पदों पर आवेदन करें।', 'FastAPI ద్వారా ML మోడల్ API తయారు చేసి డేటా సైన్స్ ఉద్యోగాలకు దరఖాస్తు చేయండి.', 'Publish an end-to-end prediction API project on GitHub', '["Digital India Internship","NATS 2.0"]'::jsonb, '["Saving and serving ML pipelines in FastAPI","Presenting clear business insights from data","Applying via MeitY Digital India & LinkedIn"]'::jsonb, '6 Weeks', '[{"title":"Digital India Internship Scheme","url":"https://intern.meity.gov.in","provider":"MeitY","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000011' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000014', 'Personalized DevOps Engineer Learning Pathway', 4, '7 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000325', r.id, 1, 'Linux Administration, Bash Scripting & Networking', 'लिनक्स एडमिनिस्ट्रेशन, बैश स्क्रिप्टिंग और नेटवर्किंग', 'లైనక్స్ అడ్మినిస్ట్రేషన్, బాష్ స్క్రిప్టింగ్ & నెట్‌వర్కింగ్', 'Manage Ubuntu servers via SSH, file permissions, systemd services, DNS/HTTP reverse proxying with Nginx, and automate server backups with Bash.', 'SSH, लिनक्स परमिशन, Nginx रिवर्स प्रॉक्सी और बैश ऑटोमेशन स्क्रिप्ट्स लिखना सीखें।', 'SSH సర్వర్ నిర్వహణ, Nginx రివర్స్ ప్రాక్సీ మరియు బాష్ స్క్రిప్టింగ్ నేర్చుకోండి.', 'Provision an Nginx web server with automated log rotation script', '["SIDH Cloud & Linux Skilling"]'::jsonb, '["Linux process, user & systemd management","TCP/IP ports, DNS & SSL TLS setup","Automated Bash shell scripts"]'::jsonb, '6 Weeks', '[{"title":"freeCodeCamp Linux Command Line Guide","url":"https://www.freecodecamp.org/news/learn-the-command-line","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000014' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000326', r.id, 2, 'Docker Containers & Multi-Service Compose', 'डॉकर (Docker) कंटेनराइजेशन और डॉकर कंपोज़', 'డాకర్ (Docker) కంటైనర్లు & మల్టీ-సర్వీస్ కంపోజ్', 'Write multi-stage Dockerfiles to package Node/Python APIs reproducibly, configure bridge networks and volumes, and orchestrate stacks via Docker Compose.', 'मल्टी-स्टेज डॉकरफाइल लिखें और डॉकर कंपोज़ द्वारा डेटाबेस व बैकएंड कंटेनर चलाएं।', 'Dockerfiles రాయడం మరియు Docker Compose ద్వారా బ్యాకెండ్ + డేటాబేస్ రన్ చేయడం.', 'Containerize a multi-tier Node + PostgreSQL app with Docker Compose', '[]'::jsonb, '["Slim multi-stage production Dockerfiles","Persistent Docker volumes & env secrets","Orchestrating API + DB stacks"]'::jsonb, '6 Weeks', '[{"title":"Docker Official Documentation","url":"https://docs.docker.com/get-started","provider":"Docker","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000014' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000327', r.id, 3, 'CI/CD Pipelines (GitHub Actions) & Cloud Infrastructure', 'CI/CD पाइपलाइन (GitHub Actions) और क्लाउड होस्टिंग', 'CI/CD పైప్‌లైన్స్ (GitHub Actions) & క్లౌడ్ ఇన్‌ఫ్రా', 'Build automated test, lint, and deploy workflows with GitHub Actions, and learn cloud VPCs, IAM least-privilege policies, and Infrastructure as Code basics.', 'GitHub Actions से स्वचालित टेस्ट व डिप्लॉय पाइपलाइन तथा क्लाउड सुरक्षा नियम सीखें।', 'GitHub Actions ఆటోమేషన్ మరియు క్లౌడ్ IAM భద్రతా నియమాలు నేర్చుకోండి.', 'Set up a GitHub Actions workflow that runs tests on every push', '["NASSCOM FutureSkills Prime"]'::jsonb, '["Automated CI build & test YAML workflows","Zero-downtime deployment pipelines","Cloud IAM, VPC & secrets management"]'::jsonb, '8 Weeks', '[{"title":"GitHub Actions Quickstart Docs","url":"https://docs.github.com/actions","provider":"GitHub","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000014' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000328', r.id, 4, 'Monitoring, Kubernetes Basics & SRE Hiring', 'सर्वर मॉनिटरिंग, कुबेरनेट्स परिचय और रोजगार', 'మానిటరింగ్, కుబర్నెటిస్ బేసిక్స్ & ఉద్యోగ దరఖాస్తులు', 'Monitor uptime and logs using Prometheus/Grafana alerts, grasp Kubernetes pods/deployments, and apply for Junior DevOps / Cloud Ops roles.', 'प्रोमेथियस/ग्राफाना मॉनिटरिंग और कुबेरनेट्स पॉड्स की समझ विकसित कर रोजगार के लिए आवेदन करें।', 'సర్వర్ లాగ్స్ మానిటరింగ్, కుబర్నెటిస్ బేసిక్స్ నేర్చుకుని DevOps ఉద్యోగాలకు దరఖాస్తు.', 'Document an automated CI/CD + Docker deployment architecture on GitHub', '["NATS 2.0 Apprenticeship"]'::jsonb, '["Health check probes & metric dashboards","Kubernetes Pods, Services & Deployments","Applying for Cloud Support / DevOps roles"]'::jsonb, '6 Weeks', '[{"title":"Kubernetes Official Tutorials","url":"https://kubernetes.io/docs/tutorials","provider":"CNCF","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000014' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000015', 'Personalized Mobile Application Developer Pathway', 4, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000329', r.id, 1, 'TypeScript & React Core Component Architecture', 'टाइपस्क्रिप्ट (TypeScript) और रिएक्ट मूल सिद्धांत', 'టైప్‌స్క్రిప్ట్ & రియాక్ట్ కాంపోనెంట్ ఆర్కిటెక్చర్', 'Master TypeScript types/interfaces alongside functional React components, hooks, state updates, and asynchronous REST fetching.', 'टाइपस्क्रिप्ट और रिएक्ट कॉम्पोनेंट्स, हुक्स तथा एपीआई डेटा फेचिंग में दक्षता प्राप्त करें।', 'TypeScript మరియు React Hooks వాడుతూ రీయూజబుల్ కాంపోనెంట్లు నిర్మించడం నేర్చుకోండి.', 'Build a typed multi-card data dashboard in React', '["NASSCOM FutureSkills Prime"]'::jsonb, '["Strong typing with TypeScript interfaces","React useState, useEffect & custom hooks","Async JSON fetching & error state handling"]'::jsonb, '5 Weeks', '[{"title":"React Official Learn Guide","url":"https://react.dev/learn","provider":"React Community","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000015' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000330', r.id, 2, 'React Native, Expo Router & Responsive Mobile Layouts', 'रिएक्ट नेटिव, एक्सपो (Expo) और मोबाइल यूआई डिजाइन', 'రియాక్ట్ నేటివ్, ఎక్స్‌పో & రెస్పాన్సివ్ మొబైల్ డిజైన్', 'Develop cross-platform Android & iOS screens using View, ScrollView, FlatList, Flexbox, Expo Router navigation, and AsyncStorage offline caching.', 'View, FlatList, Expo Router नेविगेशन और ऑफलाइन स्टोरेज से एंड्रॉयड ऐप्स बनाना सीखें।', 'React Native & Expo Router తో ఆండ్రాయిడ్ & వెబ్ రెస్పాన్సివ్ స్క్రీన్లు నిర్మించండి.', 'Build a 3-tab mobile app with local persistence and clean form inputs', '[]'::jsonb, '["Mobile-first Flexbox & Safe Area layout","Expo Router stack & tab navigation","Offline persistence using AsyncStorage"]'::jsonb, '6 Weeks', '[{"title":"React Native Official Docs","url":"https://reactnative.dev/docs/getting-started","provider":"Meta Open Source","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000015' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000331', r.id, 3, 'API Integration, Auth Flows & Multilingual i18n', 'रेस्ट एपीआई, ऑथेंटिकेशन और बहुभाषी (i18n) समर्थन', 'API ఇంటిగ్రేషన్, లాగిన్ సెక్యూరిటీ & బహుభాషా సపోర్ట్', 'Connect mobile apps to Node.js/Supabase backends, implement JWT login persistence, and support regional Indian languages via i18next.', 'बैकएंड एपीआई कनेक्शन, सुरक्षित लॉगिन सेशन और हिंदी/तेलुगु भाषा स्विचिंग लागू करें।', 'బ్యాకెండ్ సర్వర్ కనెక్షన్, JWT లాగిన్ మరియు తెలుగు/హిందీ భాషా అనువాదం జోడించండి.', 'Connect your app to a REST backend with instant language switching', '[]'::jsonb, '["Bearer token auth & session recovery","Optimistic UI updates for mobile networks","Adding i18next multilingual locales"]'::jsonb, '6 Weeks', '[{"title":"Expo Official Documentation","url":"https://docs.expo.dev","provider":"Expo","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000015' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000332', r.id, 4, 'EAS Android APK Packaging & App Developer Hiring', 'एंड्रॉयड APK बिल्ड और मोबाइल ऐप डेवलपर रोजगार', 'ఆండ్రాయిడ్ APK బిల్డింగ్ & మొబైల్ డెవలపర్ ఉద్యోగాలు', 'Compile standalone Android APKs with Expo EAS Build, test on real Android devices, publish GitHub demos, and apply to junior mobile roles.', 'ईएएस द्वारा एंड्रॉयड एपीके बनाएं, फोन पर टेस्ट करें और मोबाइल डेवलपर इंटर्नशिप के लिए आवेदन करें।', 'Expo EAS ద్వారా Android APK తయారు చేసి, పోర్ట్‌ఫోలియోతో ఉద్యోగాలకు దరఖాస్తు చేయండి.', 'Generate a testable Android APK and publish source code on GitHub', '["AICTE & PM Internship Scheme"]'::jsonb, '["Building APK packages with EAS Build","Profiling FPS & list scroll smoothness","Applying on Internshala, LinkedIn & PM Internship"]'::jsonb, '4 Weeks', '[{"title":"Internshala Mobile App Internships","url":"https://internshala.com","provider":"Internshala","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000015' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000019', 'Personalized Business Analyst Learning Pathway', 4, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000333', r.id, 1, 'Advanced Excel, Pivot Tables & Financial KPI Modeling', 'एडवांस्ड एक्सेल, पिवट टेबल और KPI मॉडलिंग', 'అడ్వాన్స్‌డ్ ఎక్సెల్, పివట్ టేబుల్స్ & KPI మోడలింగ్', 'Master XLOOKUP, Index-Match, Pivot Tables, revenue cohort tracking, and executive spreadsheet reporting used across Indian enterprises.', 'XLOOKUP, पिवट टेबल और व्यावसायिक प्रदर्शन रिपोर्ट तैयार करने में दक्षता हासिल करें।', 'XLOOKUP, Pivot Tables మరియు వ్యాపార ఆదాయ నివేదికలు తయారు చేయడం నేర్చుకోండి.', 'Build a monthly retail sales & profit KPI dashboard in Excel', '["SWAYAM Management Certification"]'::jsonb, '["Dynamic Excel formulas & conditional audits","Building multi-sheet Pivot dashboards","Calculating CAC, ROI & profit margins"]'::jsonb, '5 Weeks', '[{"title":"SWAYAM Business Analytics Course","url":"https://swayam.gov.in/explorer?searchText=business+analytics","provider":"SWAYAM / IIMBx","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000019' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000334', r.id, 2, 'SQL Database Querying & Requirement Documentation', 'SQL डेटाबेस विश्लेषण और आवश्यकता दस्तावेज़ीकरण (BRD)', 'SQL డేటాబేస్ విశ్లేషణ & బిజినెస్ డాక్యుమెంటేషన్ (BRD)', 'Extract operational metrics directly from SQL databases and translate stakeholder interviews into clear Business Requirement Documents (BRD) and user stories.', 'SQL से डेटा निकालना और स्पष्ट बिजनेस रिक्वायरमेंट डॉक्यूमेंट (BRD) लिखना सीखें।', 'SQL ద్వారా వ్యాపార డేటా సేకరించడం మరియు BRD డాక్యుమెంట్లు రాయడం నేర్చుకోండి.', 'Write a 2-page BRD + SQL analysis query set for an e-commerce workflow', '[]'::jsonb, '["Writing SQL aggregations & multi-table joins","Creating BRDs, flowcharts & acceptance criteria","Stakeholder requirement interviews"]'::jsonb, '6 Weeks', '[{"title":"freeCodeCamp SQL Databases","url":"https://www.freecodecamp.org/learn/relational-database","provider":"freeCodeCamp","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000019' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000335', r.id, 3, 'BI Visualization Dashboards (Power BI / Tableau)', 'बिजनेस इंटेलिजेंस डैशबोर्ड (Power BI / Tableau)', 'BI డాష్‌బోర్డులు (Power BI / Tableau)', 'Build interactive Power BI dashboards with DAX measures and drill-down filters to present actionable insights to operations leaders.', 'पावर बीआई द्वारा इंटरैक्टिव रिपोर्ट और व्यावसायिक डैशबोर्ड बनाना सीखें।', 'Power BI ద్వారా ఇంటరాక్టివ్ బిజినెస్ డాష్‌బోర్డులను రూపొందించండి.', 'Design a 3-page interactive Power BI sales & inventory dashboard', '[]'::jsonb, '["Connecting Power BI to SQL/CSV data sources","Creating clear KPI cards and trend charts","Presenting executive decision summaries"]'::jsonb, '6 Weeks', '[{"title":"Microsoft Learn Data & BI Paths","url":"https://learn.microsoft.com/training","provider":"Microsoft Learn","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000019' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000336', r.id, 4, 'Case Studies, Resume & Business Analyst Hiring', 'केस स्टडी पोर्टफोलियो और बिजनेस एनालिस्ट भर्ती', 'కేస్ స్టడీస్ & బిజినెస్ అనలిస్ట్ ఉద్యోగ దరఖాస్తులు', 'Compile 2 business case studies (supply chain or fintech efficiency), practice estimation case interviews, and apply via NATS, Naukri & LinkedIn.', '2 व्यावहारिक केस स्टडी तैयार कर एनालिटिक्स कंपनियों और सरकारी परियोजनाओं में आवेदन करें।', '2 బిజినెస్ కేస్ స్టడీస్ పూర్తి చేసి ప్రైవేట్ మరియు కార్పొరేట్ ఉద్యోగాలకు దరఖాస్తు.', 'Publish a portfolio PDF showcasing 2 SQL + Power BI business case studies', '["NATS 2.0 Graduate Traineeship"]'::jsonb, '["Guesstimates and root-cause case interviews","Structuring quantified resume bullet points","Applying on Naukri, LinkedIn & NATS 2.0"]'::jsonb, '4 Weeks', '[{"title":"National Career Service","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000019' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000020', 'Personalized Government Administrative Services Pathway', 4, '9 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000337', r.id, 1, 'NCERT Core Foundations: Polity, History, Economy & Geography', 'NCERT आधार: राजव्यवस्था, इतिहास, अर्थव्यवस्था और भूगोल', 'NCERT బేసిక్స్: భారత రాజ్యాంగం, చరిత్ర, ఆర్థిక శాస్త్రం & భూగోళం', 'Build strong conceptual clarity from Class 6–12 NCERT books covering Indian Constitution, modern freedom struggle, budgets, and physical geography.', 'कक्षा 6 से 12 की एनसीईआरटी पुस्तकों से भारतीय संविधान, इतिहास और अर्थशास्त्र की नींव मजबूत करें।', '6 నుండి 12వ తరగతి NCERT పుస్తకాల ద్వారా రాజ్యాంగం, చరిత్ర మరియు ఆర్థిక శాస్త్రం చదవండి.', 'Summarize Polity Panchayati Raj articles & prepare crisp revision notes', '["Free State Competitive Exam Coaching Schemes"]'::jsonb, '["Constitutional Articles, Parliament & Panchayati Raj","Modern Indian history milestones","Union Budget & rural fiscal policies"]'::jsonb, '10 Weeks', '[{"title":"NCERT Free e-Books (DIKSHA)","url":"https://diksha.gov.in","provider":"NCERT","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000020' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000338', r.id, 2, 'Quantitative Aptitude, Logical Reasoning & State GK', 'गणित, तार्किक योग्यता (Reasoning) और राज्य सामान्य ज्ञान', 'క్వాంటిటేటివ్ ఆప్టిట్యూడ్, రీజనింగ్ & రాష్ట్ర జనరల్ నాలెడ్జ్', 'Practice percentage, ratio, data interpretation, syllogisms, state administrative history, and government welfare flagship schemes.', 'प्रतिशत, अनुपात, रीजनिंग और अपने राज्य के सामान्य ज्ञान व योजनाओं का नियमित अभ्यास करें।', 'గణితం, రీజనింగ్, రాష్ట్ర ప్రభుత్వ పథకాలు మరియు కరెంట్ అఫైర్స్ సాధన చేయండి.', 'Complete 15 timed 60-minute aptitude & GS sectional mock tests', '[]'::jsonb, '["Speed math for SSC/APPSC/TSPSC prelims","Analytical & logical reasoning puzzles","State welfare scheme beneficiary norms"]'::jsonb, '10 Weeks', '[{"title":"Khan Academy Math & Reasoning Foundations","url":"https://www.khanacademy.org","provider":"Khan Academy","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000020' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000339', r.id, 3, 'Answer Writing, Current Affairs & Essay Precision', 'मुख्य परीक्षा उत्तर लेखन, समसामयिकी और निबंध अभ्यास', 'మెయిన్స్ ఆన్సర్ రైటింగ్, కరెంట్ అఫైర్స్ & వ్యాస రచన', 'Track PIB government press releases monthly, practice structured 150-250 word administrative answers with data and Supreme Court articles.', 'पीआईबी (PIB) समसामयिकी नोट्स बनाएं और मुख्य परीक्षा हेतु सटीक उत्तर लेखन का अभ्यास करें।', 'PIB కరెంట్ అఫైర్స్ చదువుతూ, సమయానుకూలంగా మెయిన్స్ సమాధానాలు రాయడం సాధన చేయండి.', 'Write 10 timed analytical essays on rural governance and clean energy', '["State BC/SC/EBC Study Circles"]'::jsonb, '["Summarizing PIB policy updates monthly","Structuring intro-body-conclusion answers","Precise vernacular & English essay drafting"]'::jsonb, '8 Weeks', '[{"title":"Press Information Bureau (PIB)","url":"https://pib.gov.in","provider":"Govt of India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000020' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000340', r.id, 4, 'OTR Registration & SSC / APPSC / UPSC Applications', 'OTR पंजीकरण एवं SSC / राज्य PSC / UPSC परीक्षा आवेदन', 'OTR రిజిస్ట్రేషన్ & SSC / APPSC / UPSC పరీక్షల దరఖాస్తులు', 'Complete One Time Registration (OTR) on UPSC, SSC, and state PSC portals, keep verified community/income documents ready, and attempt full mock series.', 'यूपीएससी, एसएससी व राज्य लोक सेवा आयोग पोर्टलों पर ओटीआर पूरा कर परीक्षा फॉर्म भरें।', 'UPSC, SSC మరియు APPSC పోర్టల్స్‌లో OTR నమోదు పూర్తి చేసి పరీక్షలకు హాజరవండి.', 'Verify OTR registration on ssc.gov.in or your State PSC portal', '["Pre-Examination Coaching Scholarships"]'::jsonb, '["Accurate OTR & Aadhaar verification on ssc.gov.in / psc.ap.gov.in","Document readiness for verification round","Interview & personality test preparation"]'::jsonb, '6 Weeks', '[{"title":"Staff Selection Commission (SSC)","url":"https://ssc.gov.in","provider":"Govt of India","is_free":true},{"title":"UPSC Official Portal","url":"https://upsc.gov.in","provider":"UPSC","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000020' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000021', 'Personalized Teacher / Educator Learning Pathway', 4, '8 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000341', r.id, 1, 'Subject Mastery & NEP 2020 Experiential Pedagogy', 'विषय ज्ञान और एनईपी (NEP 2020) शिक्षण पद्धति', 'విషయ పరిజ్ఞానం & NEP 2020 ఆధునిక బోధనా పద్ధతులు', 'Master primary/secondary core subjects alongside National Education Policy (NEP 2020) activity-based learning, multilingual instruction, and lesson planning.', 'नई शिक्षा नीति 2020 के अनुसार गतिविधि-आधारित शिक्षण और पाठ योजना बनाना सीखें।', 'NEP 2020 ప్రకారం ఆనందదాయకమైన పాఠ్య ప్రణాళికలు మరియు బోధనా పద్ధతులు నేర్చుకోండి.', 'Create 3 interactive multilingual lesson plans with student activities', '["Samagra Shiksha & NISHTHA"]'::jsonb, '["Designing weekly outcome-based lesson plans","Foundational Literacy & Numeracy (FLN)","Interactive classroom engagement activities"]'::jsonb, '6 Weeks', '[{"title":"DIKSHA National Teacher Portal","url":"https://diksha.gov.in","provider":"NCERT / MoE","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000021' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000342', r.id, 2, 'D.El.Ed / B.Ed Qualification & Child Psychology', 'डी.एल.एड / बी.एड प्रशिक्षण और बाल मनोविज्ञान', 'D.El.Ed / B.Ed కోర్సు & పిల్లల మనోవిజ్ఞాన శాస్త్రం', 'Study cognitive development stages, inclusive classroom adaptation for diverse learners, formative assessment rubrics, and digital smartboard tools.', 'बाल मनोविज्ञान, समावेशी शिक्षा, मूल्यांकन तकनीक और स्मार्ट क्लास टूल्स का उपयोग सीखें।', 'పిల్లల వికాస దశలు, సమ్మిళిత విద్య మరియు ఆధునిక డిజిటల్ తరగతి నిర్వహణ.', 'Complete a NISHTHA continuous professional development module on DIKSHA', '["PM-USP / State Teacher Scholarships"]'::jsonb, '["Piaget & Vygotsky learning principles","Inclusive education & remedial support","Using DIKSHA digital QR-code modules"]'::jsonb, '8 Weeks', '[{"title":"SWAYAM Pedagogy & Education Courses","url":"https://swayam.gov.in","provider":"SWAYAM / IGNOU","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000021' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000343', r.id, 3, 'CTET / State TET Eligibility Examination Preparation', 'सीटीईटी (CTET) और राज्य टीईटी परीक्षा की तैयारी', 'CTET మరియు రాష్ట్ర TET అర్హత పరీక్ష సన్నద్ధత', 'Practice previous CTET & State TET Paper-I/Paper-II question papers covering Child Development & Pedagogy, Mathematics/Science/Social Studies, and Languages.', 'बाल विकास, शिक्षाशास्त्र और भाषा विषयों के पिछले वर्षों के सीटीईटी/टीईटी प्रश्नपत्र हल करें।', 'చైల్డ్ డెవలప్‌మెంట్, పెడగాజీ మరియు భాషా అంశాలతో గత TET/CTET పేపర్లు సాధన.', 'Attempt 5 full CTET/State TET timed mock papers', '[]'::jsonb, '["Solving 150-minute CTET mock exams","Mastering vernacular & English pedagogy questions","Achieving above 60% qualifying score"]'::jsonb, '10 Weeks', '[{"title":"CTET Official Portal","url":"https://ctet.nic.in","provider":"CBSE / Govt of India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000021' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000344', r.id, 4, 'Micro-Teaching Demo, DSC / KVS & School Applications', 'डेमो क्लास अभ्यास, डीएससी / केवीएस व विद्यालय नियुक्ति', 'డెమో టీచింగ్, DSC / KVS & పాఠశాల ఉద్యోగ దరఖాస్తులు', 'Deliver polished 15-minute blackboard/smartboard demonstration lessons and apply to State DSC Teacher Recruitment, KVS, Navodaya Vidyalayas, and private schools.', 'प्रभावी डेमो क्लास का अभ्यास करें और राज्य शिक्षक भर्ती (DSC), KVS व NVS में आवेदन करें।', 'డెమో క్లాస్ సిద్ధం చేసుకుని రాష్ట్ర DSC, KVS, NVS మరియు పాఠశాలల్లో ఉద్యోగాలకు దరఖాస్తు.', 'Record a 10-minute practice lesson and update your educator resume', '["State DSC / KVS Recruitment Drives"]'::jsonb, '["Structuring a clear 15-minute demo lecture","Parent-teacher communication best practices","Tracking state DSC & KVS recruitment notices"]'::jsonb, '6 Weeks', '[{"title":"National Career Service Teaching Jobs","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000021' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000022', 'Personalized Banking Professional (IBPS/SBI) Pathway', 4, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000345', r.id, 1, 'Quantitative Aptitude & Data Interpretation Speed', 'क्वांटिटेटिव एप्टीट्यूड और डेटा इंटरप्रिटेशन गति अभ्यास', 'క్వాంటిటేటివ్ ఆప్టిట్యూడ్ & డేటా ఇంటర్‌ప్రిటేషన్ వేగం', 'Build rapid accuracy in percentages, simple/compound interest, profit & loss, ratio, time & work, and multi-chart banking Data Interpretation.', 'प्रतिशत, ब्याज, लाभ-हानि, अनुपात और बैंकिंग डेटा इंटरप्रिटेशन प्रश्नों को कम समय में हल करें।', 'శాతాలు, వడ్డీ లెక్కలు, లాభనష్టాలు మరియు చార్ట్ డేటా విశ్లేషణ వేగంగా సాధన చేయండి.', 'Practice 25 Data Interpretation & Arithmetic drills daily for 2 weeks', '[]'::jsonb, '["Vedic calculation & percentage shortcuts","Pie, bar & tabular DI problem sets","Quadratic equations & number series"]'::jsonb, '7 Weeks', '[{"title":"Khan Academy Quantitative Foundations","url":"https://www.khanacademy.org","provider":"Khan Academy","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000022' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000346', r.id, 2, 'Logical Reasoning Puzzles & English Comprehension', 'तार्किक पहेलियाँ (Puzzles) और अंग्रेजी पठन अभ्यास', 'లాజికల్ రీజనింగ్ పజిల్స్ & ఇంగ్లీష్ కాంప్రహెన్షన్', 'Master floor/box seating puzzles, syllogisms, blood relations, inequalities, reading comprehension, and error spotting required for IBPS Prelims.', 'सिटिंग अरेंजमेंट, पहेलियाँ, सिलॉजिज्म और अंग्रेजी रीडिंग कॉम्प्रिहेंशन में गति बढ़ाएं।', 'సీటింగ్ అరేంజ్‌మెంట్, పజిల్స్, సిలోజిజమ్స్ మరియు ఇంగ్లీష్ రీడింగ్ సాధన చేయండి.', 'Complete 10 sectional reasoning & English tests targeting 85%+ accuracy', '[]'::jsonb, '["Solving 5-variable seating puzzles under 4 mins","Accuracy in syllogism & coding-decoding","Reading daily financial editorials"]'::jsonb, '7 Weeks', '[{"title":"SWAYAM Communication & Financial English","url":"https://swayam.gov.in","provider":"SWAYAM","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000022' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000347', r.id, 3, 'Banking Awareness, RBI Policy, FinTech & Digital Payments', 'बैंकिंग जागरूकता, आरबीआई नीति और डिजिटल भुगतान (UPI/NEFT)', 'బ్యాంకింగ్ అవేర్‌నెస్, RBI విధానాలు & డిజిటల్ చెల్లింపులు', 'Understand RBI monetary tools (Repo/CRR/SLR), Priority Sector Lending (agriculture/MSME), UPI/NPCI rails, NPA norms, and last 6 months economic current affairs.', 'आरबीआई की मौद्रिक नीति, प्राथमिकता क्षेत्र ऋण (कृषि/MSME) और यूपीआई व बैंकिंग शब्दावली सीखें।', 'RBI పాలసీ రేట్లు, వ్యవసాయ/MSME రుణాలు, UPI & NPCI మరియు గత 6 నెలల ఆర్థిక వార్తలు.', 'Create a 1-page cheat sheet of RBI rates & major govt banking schemes', '[]'::jsonb, '["RBI monetary policy tools & inflation control","Agricultural & MSME priority sector lending","Digital banking (UPI, RTGS, NEFT, IMPS)"]'::jsonb, '6 Weeks', '[{"title":"RBI Financial Education Portal","url":"https://www.rbi.org.in","provider":"Reserve Bank of India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000022' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000348', r.id, 4, 'IBPS RRB / Clerk / PO Full Mock Tests & Interview Prep', 'IBPS RRB / क्लर्क / पीओ मॉक टेस्ट और साक्षात्कार तैयारी', 'IBPS RRB / క్లర్క్ / PO మాక్ టెస్ట్స్ & ఇంటర్వ్యూ సన్నద్ధత', 'Take full-length Prelims & Mains mock tests, prepare regional Rural Bank (IBPS RRB) applications, and practice PO panel interviews.', 'क्षेत्रीय ग्रामीण बैंक (RRB) व राष्ट्रीयकृत बैंकों की मॉक परीक्षा दें और साक्षात्कार की तैयारी करें।', 'IBPS RRB గ్రామీణ బ్యాంకులు & SBI/IBPS పరీక్షలకు మాక్ టెస్ట్స్ రాసి దరఖాస్తు చేయండి.', 'Register and verify exam calendar alerts on ibps.in', '["IBPS RRB & SBI Annual Recruitment Cycles"]'::jsonb, '["Time allocation across Prelims sections","IBPS RRB Office Assistant & Officer Scale-I eligibility","Handling PO group discussion & panel interview"]'::jsonb, '4 Weeks', '[{"title":"IBPS Official Recruitment Portal","url":"https://www.ibps.in","provider":"IBPS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000022' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000025', 'Personalized Agricultural Drone Operator Pathway', 4, '3 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000349', r.id, 1, 'DGCA Drone Rules, Airspace Zones & UIN Compliance', 'डीजीसीए ड्रोन नियम, एयरस्पेस जोन और डिजिटलस्काई पंजीकरण', 'DGCA డ్రోన్ నియమాలు, ఎయిర్‌స్పేస్ జోన్లు & డిజిటల్‌స్కై నమోదు', 'Learn DigitalSky airspace classification (Green, Yellow, Red zones), weight categories, NPNT compliance, and basic aerodynamics of hexacopter agri-drones.', 'ग्रीन/येलो/रेड जोन नियम, ड्रोन पंजीकरण और कृषि ड्रोन के एयरोडायनामिक्स को समझें।', 'డిజిటల్‌స్కై ఎయిర్‌స్పేస్ జోన్లు, డ్రోన్ రిజిస్ట్రేషన్ మరియు హెక్సాకాప్టర్ ఫ్లైట్ సూత్రాలు.', 'Explore live Green/Red flight zone maps on DigitalSky portal', '["Kisan Drone Skill Initiative"]'::jsonb, '["Reading DigitalSky green/yellow airspace maps","Multi-rotor flight dynamics & wind limits","Pre-flight fail-safe RTH protocols"]'::jsonb, '2 Weeks', '[{"title":"DGCA DigitalSky Portal","url":"https://digitalsky.dgca.gov.in","provider":"DGCA India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000025' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000350', r.id, 2, 'Simulator & Live Field Piloting at DGCA-Approved RPTO', 'सिम्युलेटर व डीजीसीए अनुमोदित केंद्र (RPTO) पर उड़ान अभ्यास', 'సిమ्युలేటర్ & DGCA ఆమోదిత RPTO కేంద్రంలో ఫ్లైట్ శిక్షణ', 'Train on flight simulators before executing manual and autonomous waypoint flights, precision hovering, and safe landing to earn Remote Pilot Certificate (RPC).', 'फ्लाइट सिम्युलेटर व ग्राउंड ट्रेनिंग पूरा कर रिमोट पायलट सर्टिफिकेट (RPC) प्राप्त करें।', 'సిమ्युలేటర్ మరియు ప్రత్యక్ష డ్రోన్ ఫ్లైట్ పూర్తి చేసి రిమోట్ పైలట్ సర్టిఫికెట్ (RPC) పొందండి.', 'Locate nearest DGCA-authorized RPTO training center in your state', '["Namo Drone Didi & SMAM Agri-Drone Subsidy"]'::jsonb, '["Manual Loiter vs Autonomous Mission modes","Handling low-battery & GPS drop emergencies","Passing practical RPTO solo flight test"]'::jsonb, '4 Weeks', '[{"title":"Skill India Drone Pilot Training","url":"https://www.skillindiadigital.gov.in","provider":"SIDH / ASCI","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000025' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000351', r.id, 3, 'Spray Tank Calibration, LiPo Battery & Nozzle Maintenance', 'स्प्रे नोजल कैलिब्रेशन, लिपो बैटरी व पंप रखरखाव', 'స్ప్రే నాజిల్ కాలిబ్రేషన్, LiPo బ్యాటరీ & పంప్ మెయింటెనెన్స్', 'Calibrate nozzle flow rates (L/acre), mix safe Nano Urea dilutions, charge smart LiPo packs safely in the field, and clean clogged filters daily.', 'नैनो यूरिया घोल अनुपात, स्प्रे नोजल प्रवाह दर जांच और फील्ड में बैटरी सुरक्षा का अभ्यास करें।', 'నానో యూరియా ద్రావణం కలపడం, స్ప్రే నాజిల్ ప్రెషర్ సెట్టింగ్ మరియు LiPo బ్యాటరీ జాగ్రత్తలు.', 'Prepare a 10-point daily field drone maintenance & safety logbook', '[]'::jsonb, '["Calculating spray height & swath width","Preventing chemical drift during crosswinds","LiPo battery storage-charge health check"]'::jsonb, '3 Weeks', '[{"title":"ICAR Precision Agriculture Resources","url":"https://krishi.icar.gov.in","provider":"ICAR","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000025' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000352', r.id, 4, 'Commercial Spraying Contracts & CHC Agri Entrepreneurship', 'व्यावसायिक छिड़काव सेवाएं एवं कस्टम हायरिंग सेंटर उद्यमिता', 'రైతులకు డ్రోన్ స్ప్రే సేవలు & కస్టమ్ హైరింగ్ సెంటర్ వ్యాపారం', 'Join IFFCO/agri-tech drone fleet operations or form a rural Custom Hiring Center (CHC) leveraging central government agricultural drone subsidies.', 'इफको/एग्री-टेक कंपनियों में पायलट बनें या सरकारी सब्सिडी से अपना ड्रोन सेवा केंद्र शुरू करें।', 'IFFCO లేదా అగ్రి-టెక్ సంస్థలలో ఉద్యోగం లేదా ప్రభుత్వ రాయితీతో డ్రోన్ సేవా వ్యాపారం.', 'Draft a per-acre seasonal revenue model covering 200 acres/month', '["SMAM 40%-80% Kisan Drone Subsidy","Namo Drone Didi"]'::jsonb, '["Pricing per-acre drone spraying services","Applying via state SMAM/FPO drone subsidies","Building village farmer WhatsApp booking groups"]'::jsonb, '3 Weeks', '[{"title":"PM MUDRA & Agri-Tech Entrepreneurship","url":"https://www.mudra.org.in","provider":"Govt of India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000025' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000026', 'Personalized CNC Machine Operator Pathway', 4, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000353', r.id, 1, 'Engineering Drawings, Tolerances & Precision Measuring Tools', 'इंजीनियरिंग ड्राइंग, टॉलरेंस और माइक्रोमीटर/वर्नियर उपयोग', 'ఇంజనీరింగ్ డ్రాయింగ్, టాలరెన్స్ & మైక్రోమీటర్ వాడకం', 'Read 1st/3rd angle orthographic blueprints, interpret +/- 0.02mm tolerances, and measure shafts/bores using digital vernier calipers and outside micrometers.', 'ब्लूप्रिंट पढ़ना, टॉलरेंस समझना तथा वर्नियर कैलिपर व माइक्रोमीटर से सटीक माप लेना सीखें।', 'బ్లూప్రింట్ చదవడం, +/-0.02mm కొలతలు మరియు వెర్నియర్/మైక్రోమీటర్ వాడకం నేర్చుకోండి.', 'Take 10 precision shaft & bore measurements accurately using vernier/micrometer', '["PMKVY 4.0 Manufacturing Trades"]'::jsonb, '["Reading GD&T concentricity & surface finish symbols","Measuring to 0.01mm precision with micrometers","Calculating cutting speed (RPM) & feed rate"]'::jsonb, '5 Weeks', '[{"title":"Bharat Skills ITI Turner & Machinist e-Books","url":"https://bharatskills.gov.in","provider":"DGT / Bharat Skills","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000026' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000354', r.id, 2, 'CNC Turning Center Operations, Fanuc Panel & Tool Offsets', 'सीएनसी टर्निंग पैनल, टूल ऑफसेट और वर्कपीस क्लैम्पिंग', 'CNC టర్నింగ్ ప్యానెల్, టూల్ ఆఫ్‌సెట్స్ & వర్క్‌పీస్ క్లాంపింగ్', 'Operate CNC controller modes (JOG, MDI, AUTO, SINGLE BLOCK), perform zero-return homing, index turret carbide inserts, and enter wear/geometry offsets.', 'सीएनसी कंट्रोल पैनल मोड चलाना, कार्बाइड इन्सर्ट बदलना और ज्योमेट्री/वियर ऑफसेट भरना सीखें।', 'CNC కంట్రోల్ ప్యానెల్ మోడ్స్, కార్బైడ్ ఇన్‌సర్ట్ అమరిక మరియు టూల్ ఆఫ్‌సెట్స్ నేర్చుకోండి.', 'Walk through the 8-step safe CNC startup and first-part dry run checklist', '[]'::jsonb, '["Safely setting G54 work zero offset","Adjusting tool wear offsets to stay in tolerance","Executing dry-run single-block safety checks"]'::jsonb, '7 Weeks', '[{"title":"NIMI CNC Practical Resources","url":"https://bharatskills.gov.in","provider":"DGT / NIMI","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000026' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000355', r.id, 3, 'G-Code / M-Code Programming & Canned Cycles', 'जी-कोड / एम-कोड प्रोग्रामिंग और कैन्ड साइकल्स', 'G-కోడ్ / M-కోడ్ ప్రోగ్రామింగ్ & క్యాన్డ్ సైకిల్స్', 'Write and debug Fanuc/Siemens ISO G-codes (G00, G01, G02, G03, G71, G76 threading) and M-codes (M03, M08 coolant, M30) for stepped shafts and threading.', 'टर्निंग, चैंफरिंग, ग्रूविंग और थ्रेडिंग के लिए जी-कोड (G01, G71, G76) प्रोग्राम लिखना सीखें।', 'స్టెప్ టర్నింగ్, ఫేసింగ్ మరియు థ్రెడింగ్ కొరకు G-కోడ్ ప్రోగ్రాములు రాయండి.', 'Write a G-code program to turn a 3-stepped cylindrical pin with chamfer', '[]'::jsonb, '["Absolute (X, Z) vs Incremental (U, W) coordinates","Programming G71 rough turning & G76 threading cycles","Editing feed/speed overrides safely"]'::jsonb, '7 Weeks', '[{"title":"Skill India CNC Operator Courses","url":"https://www.skillindiadigital.gov.in","provider":"SIDH","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000026' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000356', r.id, 4, 'Auto-Component Factory Apprenticeship (NAPS) & Placement', 'ऑटो-कॉम्पोनेंट फैक्ट्री अप्रेंटिसशिप (NAPS) व नौकरी', 'ఆటో-కాంపోనెంట్ ఫ్యాక్టరీ అప్రెంటిస్‌షిప్ (NAPS) & ఉద్యోగం', 'Join precision machine shops, Tier-1 automotive suppliers, or aerospace/defence tool rooms under stipended NAPS apprenticeships.', 'औद्योगिक क्लस्टर में सीएनसी ऑपरेटर पद या नैप्स अप्रेंटिसशिप के लिए आवेदन करें।', 'పారిశ్రామిక వాడల్లో CNC ఆపరేటర్ ఉద్యోగాలు & NAPS అప్రెంటిస్‌షిప్‌కు దరఖాస్తు చేయండి.', 'Apply to 3 CNC Machinist / Turner apprenticeships on NAPS', '["NAPS 2.0 Industrial Apprenticeship Stipend"]'::jsonb, '["Shop-floor 5S safety & SPC quality logs","Registering on Apprenticeship India & NCS","Preparing for hands-on lathe trade tests"]'::jsonb, '5 Weeks', '[{"title":"Apprenticeship India (NAPS)","url":"https://www.apprenticeshipindia.gov.in","provider":"MSDE","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000026' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000027', 'Personalized Medical Laboratory Technician Pathway', 4, '12 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000357', r.id, 1, 'Phlebotomy, Sample Collection & Bio-Safety Protocols', 'रक्त संग्रह (Phlebotomy), सैंपल हैंडलिंग और लैब सुरक्षा', 'రక్త నమూనా సేకరణ, శాంపిల్ హ్యాండ్లింగ్ & ల్యాబ్ భద్రత', 'Master safe venipuncture blood draw techniques, vacutainer tube color-coding (EDTA, Fluoride, Serum), specimen labeling, and bio-waste sterilization.', 'सुरक्षित रक्त संग्रह, EDTA/फ्लोराइड ट्यूब पहचान, नमूना लेबलिंग व जैव-अपशिष्ट नियम सीखें।', 'సురక్షితంగా రక్తం తీయడం, ట్యూబ్ కలర్ కోడ్‌లు (EDTA/ఫ్లోరైడ్) మరియు స్టెరిలైజేషన్ నేర్చుకోండి.', 'Create a vacutainer anticoagulant color-code reference sheet', '["HSSC Healthcare Skilling"]'::jsonb, '["Vacuum vacutainer collection without hemolysis","Correct anticoagulant tube selection","Autoclave & biomedical waste segregation"]'::jsonb, '8 Weeks', '[{"title":"SWAYAM Healthcare & Lab Basics","url":"https://swayam.gov.in","provider":"SWAYAM","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000027' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000358', r.id, 2, 'Hematology, Microscopy & Clinical Biochemistry Analyzers', 'हेमेटोलॉजी, माइक्रोस्कोप जांच और बायोकेमिस्ट्री मशीन संचालन', 'హెమటాలజీ, మైక్రోస్కోప్ & బయోకెమిస్ట్రీ ఎనలైజర్ నిర్వహణ', 'Operate automated CBC cell counters, prepare and stain Leishman peripheral blood smears, estimate hemoglobin/ESR, and run liver/kidney/glucose panels.', 'सीबीसी मशीन चलाना, रक्त स्लाइड स्टेनिंग (Leishman) और लिवर/किडनी/शुगर जांच का अभ्यास करें।', 'CBC మెషిన్ నడపడం, బ్లడ్ స్మియర్ మైక్రోస్కోపీ మరియు షుగర్/లివర్ పరీక్షలు చేయడం.', 'Document normal adult clinical reference ranges for CBC, LFT, KFT & HbA1c', '["AP / National Post-Matric Scholarships"]'::jsonb, '["Preparing uniform peripheral blood smears","Calibrating semi-auto biochemistry analyzers","Blood grouping (ABO/Rh) & cross-matching"]'::jsonb, '12 Weeks', '[{"title":"Skill India Medical Lab Resources","url":"https://www.skillindiadigital.gov.in","provider":"SIDH","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000027' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000359', r.id, 3, 'Microbiology Culture Media, Staining & Serology Rapid Tests', 'माइक्रोबायोलॉजी कल्चर, ग्राम स्टेनिंग और सीरोलॉजी जांच', 'మైక్రోబయాలజీ కల్చర్, గ్రామ్ స్టెయినింగ్ & సీరాలజీ పరీక్షలు', 'Perform Gram and AFB Ziehl-Neelsen staining, inoculate sterile urine/sputum agar plates, and run ELISA/rapid antigen kits for dengue, malaria, and typhoid.', 'ग्राम स्टेनिंग, कल्चर प्लेट तैयार करना और डेंगू/मलेरिया/टाइफाइड किट जांच सीखें।', 'గ్రామ్ స్టెయినింగ్, యూరిన్ కల్చర్ మరియు డెంగ్యూ/మలేరియా ర్యాపిడ్ పరీక్షలు.', 'Review NABL internal quality control (IQC) documentation workflow', '[]'::jsonb, '["Gram-positive vs Gram-negative identification","Aseptic agar plating & incubation","Running ELISA & rapid immunochromatography tests"]'::jsonb, '12 Weeks', '[{"title":"National Health Mission Lab Quality Guidelines","url":"https://nhm.gov.in","provider":"NHM","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000027' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000360', r.id, 4, 'Hospital Clinical Internship & Diagnostic Lab Employment', 'अस्पताल लैब इंटर्नशिप एवं डायग्नोस्टिक सेंटर रोजगार', 'హాస్పిటల్ ల్యాబ్ ఇంటర్న్‌షిప్ & డయాగ్నస్టిక్ ఉద్యోగాలు', 'Complete 3-6 month supervised clinical rotations inside district government hospitals or NABL labs and apply for NHM/private lab technician openings.', 'जिला अस्पताल या NABL लैब में क्लिनिकल इंटर्नशिप पूरा कर लैब तकनीशियन पद हेतु आवेदन करें।', 'జిల్లా ఆసుపత్రి లేదా NABL ల్యాబ్‌లో ఇంటర్న్‌షిప్ పూర్తి చేసి ల్యాబ్ టెక్నీషియన్ ఉద్యోగాలకు దరఖాస్తు.', 'Prepare your clinical rotation logbook and apply to diagnostic lab roles', '["NAPS Healthcare Apprenticeships"]'::jsonb, '["Managing Laboratory Information Systems (LIS)","Reporting critical values promptly to physicians","Applying to NHM PHC/CHC & Dr. Lal / Apollo labs"]'::jsonb, '8 Weeks', '[{"title":"NCS Healthcare Lab Vacancies","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000027' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000028', 'Personalized Hospital Nursing Assistant (GDA) Pathway', 4, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000361', r.id, 1, 'Hospital Infection Control, Patient Bed & Hygiene Care', 'अस्पताल स्वच्छता, संक्रमण नियंत्रण और रोगी देखभाल आधार', 'ఆసుపత్రి పరిశుభ్రత, ఇన్ఫెక్షన్ నియంత్రణ & రోగి సంరక్షణ', 'Master therapeutic bed-making, sponge bathing, pressure ulcer prevention, wheelchair transfer techniques, and hospital biomedical safety.', 'मरीज का बिस्तर तैयार करना, स्वच्छता देखभाल, व्हीलचेयर ट्रांसफर और अस्पताल सुरक्षा नियम सीखें।', 'పేషెంట్ బెడ్ తయారీ, పరిశుభ్రత, వీల్‌చైర్ సహాయం మరియు ఆసుపత్రి భద్రతా నియమాలు.', 'Practice safe turning & wheelchair positioning ergonomics step-by-step', '["PMKVY 4.0 Free Healthcare Training"]'::jsonb, '["Safe patient lifting & bed-sore turning","5 moments of hospital hand hygiene","PPE donning/doffing protocols"]'::jsonb, '4 Weeks', '[{"title":"Skill India GDA Healthcare Handbook","url":"https://www.skillindiadigital.gov.in","provider":"HSSC / SIDH","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000028' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000362', r.id, 2, 'Clinical Vitals Charting, Dressing & Feeding Assistance', 'वाइटल साइन चार्टिंग, ड्रेसिंग सहायता और पोषण देखभाल', 'వైటల్స్ చార్టింగ్, డ్రెస్సింగ్ సహాయం & పోషణ సంరక్షణ', 'Record temperature, pulse, respiration, blood pressure, and intake/output fluid charts accurately, and assist nurses with sterile dressings.', 'तापमान, बीपी, पल्स चार्ट भरना और नर्स की देखरेख में ड्रेसिंग व दवा सहायता सीखें।', 'బీపీ, జ్వరం, ఇన్‌టేక్-అవుట్‌పుట్ చార్ట్ నమోదు మరియు స్టెరైల్ డ్రెస్సింగ్ సహాయం.', 'Fill a sample 24-hour TPR (Temp/Pulse/Respiration) nursing ward chart', '[]'::jsonb, '["Detecting abnormal fever/BP red flags immediately","Maintaining fluid intake-output ward logs","Safe oral and Ryles tube hygiene support"]'::jsonb, '6 Weeks', '[{"title":"NHM Ward Care Guidelines","url":"https://nhm.gov.in","provider":"MoHFW","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000028' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000363', r.id, 3, 'Emergency First Aid, BLS & Ward Communication', 'आपातकालीन प्राथमिक चिकित्सा (First Aid / BLS) और संवाद कौशल', 'అత్యవసర ప్రథమ చికిత్స (First Aid / BLS) & కమ్యూనికేషన్', 'Execute Basic Life Support (CPR), choking recovery, bleeding control, and compassionate communication with worried rural patients and families.', 'सीपीआर (CPR), रक्तस्राव रोकना और मरीजों व परिजनों से विनम्र व सहानुभूतिपूर्ण संवाद सीखें।', 'CPR ప్రథమ చికిత్స, రక్తస్రావం నియంత్రణ మరియు రోగుల కుటుంబాలతో మర్యాదపూర్వక సంభాషణ.', 'Review the 5 critical steps of emergency Basic Life Support (BLS)', '[]'::jsonb, '["Adult/pediatric CPR sequence steps","Emergency triage escalation to duty doctor","Empathetic regional language communication"]'::jsonb, '4 Weeks', '[{"title":"NHM Emergency Care Portal","url":"https://nhm.gov.in","provider":"MoHFW","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000028' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000364', r.id, 4, 'Supervised Hospital Ward Internship & Nursing Placement', 'अस्पताल वार्ड प्रशिक्षण और नर्सिंग सहायक नियुक्ति', 'హాస్పిటల్ వార్డు ట్రైనింగ్ & నర్సింగ్ అసిస్టెంట్ ఉద్యోగాలు', 'Complete practical ward shifts at multi-specialty/district hospitals, earn HSSC certification, and pursue ANM/GNM bridge progression or hospital jobs.', 'अस्पताल वार्ड में प्रैक्टिकल इंटर्नशिप पूरी कर एचएसएससी प्रमाणन और अस्पताल नौकरी प्राप्त करें।', 'ఆసుపత్రి వార్డులో ఇంటర్న్‌షిప్ పూర్తి చేసి సర్టిఫైడ్ GDA/ANM ఉద్యోగాలకు దరఖాస్తు.', 'Apply to local district hospitals, clinics, and NAPS healthcare slots', '["DDU-GKY / PMKVY Placement Support"]'::jsonb, '["Night/day ward handover routines","Earning HSSC GDA national skill certificate","Advancement track to ANM / Staff Nurse"]'::jsonb, '6 Weeks', '[{"title":"NCS Hospital & Nursing Care Jobs","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000028' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000029', 'Personalized Smartphone Repair Technician Pathway', 4, '4 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000365', r.id, 1, 'Mobile Electronics, SMD Components & Multimeter Testing', 'मोबाइल इलेक्ट्रॉनिक्स, एसएमडी पुर्जे और मल्टीमीटर जांच', 'మొబైల్ ఎలక్ట్రానిక్స్, SMD విడిభాగాలు & మల్టీమీటర్ టెస్టింగ్', 'Identify resistors, capacitors, diodes, coils, and PMICs on smartphone motherboards; check short-circuits via cold/hot multimeter testing and DC power supply.', 'मदरबोर्ड के छोटे पुर्जे पहचानना और मल्टीमीटर व डीसी पावर सप्लाई से शॉर्ट-सर्किट खोजना सीखें।', 'మదర్‌బోర్డ్ విడిభాగాల గుర్తింపు, మల్టీమీటర్ మరియు DC పవర్ సప్లైతో షార్ట్ సర్క్యూట్ పరీక్ష.', 'Test motherboard battery connector pins with a multimeter in diode mode', '["PMKVY 4.0 Electronics Skilling"]'::jsonb, '["Reading mobile schematic block diagrams","Detecting half-short & full-short leakage","ESD anti-static wrist strap discipline"]'::jsonb, '3 Weeks', '[{"title":"Bharat Skills Smartphone Repair Modules","url":"https://bharatskills.gov.in","provider":"DGT / Bharat Skills","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000029' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000366', r.id, 2, 'Safe Disassembly, Screen/Battery Replacement & Micro-Soldering', 'स्क्रीन व बैटरी बदलना और माइक्रो-सोल्डरिंग अभ्यास', 'డిస్‌ప్లే/బ్యాటరీ మార్పిడి & మైక్రో-సోల్డరింగ్ ప్రాక్టీస్', 'Disassemble modern glass-back devices without ribbon damage, replace displays and Li-Po batteries, and practice micro-soldering Type-C ports with SMD hot-air.', 'बिना नुकसान किए फोन खोलना, डिस्प्ले/बैटरी बदलना और टाइप-सी चार्जिंग जैक सोल्डरिंग सीखें।', 'సురక్షితంగా ఫోన్ ఓపెన్ చేయడం, డిస్‌ప్లే మార్పు మరియు Type-C ఛార్జింగ్ పిన్ సోల్డరింగ్.', 'Practice clean Type-C port desoldering and soldering on scrap PCBs', '["PM Vishwakarma / Toolkit Support"]'::jsonb, '["Heat separator screen lifting technique","SMD hot-air temperature & airflow control","Replacing Type-C charging connectors cleanly"]'::jsonb, '5 Weeks', '[{"title":"Skill India Electronics Technician Labs","url":"https://www.skillindiadigital.gov.in","provider":"SIDH / ESSCI","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000029' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000367', r.id, 3, 'Android/iOS Firmware Flashing, Diagnostics & FRP Recovery', 'सॉफ्टवेयर फ्लैशिंग, ईएमएमसी (eMMC) जांच और बूट रिकवरी', 'సాఫ్ట్‌వేర్ ఫ్లాషింగ్, డేటా బ్యాకప్ & OS రికవరీ', 'Safely flash stock official firmware on dead-boot/bootloop Android phones, perform owner-verified data backups, and resolve Wi-Fi/SIM baseband software errors.', 'बूटलूप फोन में आधिकारिक सॉफ्टवेयर डालना, डेटा बैकअप लेना और नेटवर्क बग ठीक करना सीखें।', 'బూట్‌లూప్ ఫోన్లకు అధికారిక OS ఫ్లాషింగ్, డేటా బ్యాకప్ మరియు సాఫ్ట్‌వేర్ రిపేర్.', 'Document the safe customer data-backup & firmware check protocol', '[]'::jsonb, '["Fastboot, EDL & official vendor flash tools","Legitimate customer ownership verification","Updating network baseband & Wi-Fi drivers"]'::jsonb, '3 Weeks', '[{"title":"Android Developers Platform Tools Guide","url":"https://developer.android.com/tools/adb","provider":"Android Open Source","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000029' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000368', r.id, 4, 'Service Center Employment or Own Rural Repair Shop (MUDRA)', 'सर्विस सेंटर नौकरी या स्वयं की मोबाइल रिपेयर शॉप (मुद्रा ऋण)', 'సర్వీస్ సెంటర్ ఉద్యోగం లేదా సొంత మొబైల్ షాప్ (ముద్ర లోన్)', 'Apply to authorized brand service centers (Samsung, Vivo, Xiaomi) or launch a rural smartphone repair & CSC counter with a MUDRA Shishu tool loan.', 'मोबाइल कंपनी के सर्विस सेंटर में नौकरी पाएं या मुद्रा ऋण से अपना रिपेयर व एक्सेसरी व्यवसाय शुरू करें।', 'బ్రాండెడ్ సర్వీస్ సెంటర్ ఉద్యోగం లేదా ముద్ర రుణంతో సొంత మొబైల్ రిపేర్ షాప్ ఏర్పాటు.', 'List essential starter bench tools (Microscope, SMD, Multimeter) and cost budget', '["PM MUDRA Shishu Loan","PMKVY Certification"]'::jsonb, '["Transparent job-card estimate & billing","Sourcing genuine OEM spare parts","Applying for ₹50,000 MUDRA toolkit loan"]'::jsonb, '3 Weeks', '[{"title":"PM MUDRA Yojana Portal","url":"https://www.mudra.org.in","provider":"Govt of India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000029' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000030', 'Personalized HVAC & Refrigeration Technician Pathway', 4, '6 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000369', r.id, 1, 'Refrigeration Cycle, Thermodynamics & RAC Safety Tools', 'रेफ्रिजरेशन चक्र, थर्मोडायनामिक्स और एसी सुरक्षा औजार', 'రిఫ్రిజరేషన్ సైకిల్, థర్మోడైనమిక్స్ & సేఫ్టీ టూల్స్', 'Master the 4 core stages (Compressor, Condenser, Expansion Valve, Evaporator), manifold gauge pressures, and safe handling of R32/R410A/R600a refrigerants.', 'कंप्रेसर, कंडेनसर, मैनिफोल्ड गेज और R32/R410a गैस के सुरक्षित उपयोग को समझें।', 'కంప్రెసర్, కండెన్సర్, మానిఫోల్డ్ గేజ్ మరియు R32/R410a గ్యాస్ భద్రతా నియమాలు నేర్చుకోండి.', 'Draw and label the complete 4-stage vapor compression cycle', '["PMKVY 4.0 RAC Technician"]'::jsonb, '["Tracing high-side vs low-side refrigerant pressure","Flammable R32/R600a brazing safety","Electrical clamp meter compressor amp check"]'::jsonb, '5 Weeks', '[{"title":"Bharat Skills ITI RAC Trade Theory","url":"https://bharatskills.gov.in","provider":"DGT / Bharat Skills","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000030' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000370', r.id, 2, 'Copper Pipe Flaring, Swaging, Brazing & Vacuum Leak Tests', 'कॉपर पाइप फ्लेयरिंग, ब्रेजिंग और वैक्यूम लीक परीक्षण', 'కాపర్ పైప్ ఫ్లేరింగ్, బ్రేజింగ్ & వాక్యూమ్ లీకేజీ పరీక్ష', 'Execute crack-free copper flaring, silver brazing joints under nitrogen purge, nitrogen pressure leak detection, and deep vacuum evacuation below 500 microns.', 'पाइप फ्लेयरिंग, मजबूत कॉपर ब्रेजिंग, नाइट्रोजन प्रेशर टेस्ट और वैक्यूम पंप चलाना सीखें।', 'కాపర్ పైప్ ఫ్లేరింగ్, బ్రేజింగ్, నైట్రోజన్ లీక్ టెస్టింగ్ మరియు వాక్యూమ్ పంప్ వినియోగం.', 'Practice flare connections and inspect smooth leak-proof sealing faces', '[]'::jsonb, '["Precision 45-degree flare nut joints","Silver alloy copper-to-copper brazing","Vacuum pump gauge holding test"]'::jsonb, '6 Weeks', '[{"title":"Skill India Field Technician RAC","url":"https://www.skillindiadigital.gov.in","provider":"SIDH / ESSCI","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000030' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000371', r.id, 3, 'Split/Inverter AC Installation, Gas Charging & PCB Diagnosis', 'स्प्लिट व इन्वर्टर एसी स्थापना, गैस चार्जिंग और पीसीबी जांच', 'స్ప్లిట్/ఇన్వర్టర్ AC ఇన్‌స్టాలేషన్, గ్యాస్ ఫిల్లింగ్ & PCB రిపేర్', 'Mount indoor wall plates level, insulate suction lines cleanly, pump down refrigerants without loss, weigh-in exact R32 charge, and test inverter IPM boards.', 'इनडोर/आउटडोर यूनिट लगाना, वजन अनुसार गैस चार्ज करना और इन्वर्टर पीसीबी एरर कोड जांचना सीखें।', 'ఇన్‌డోర్/అవుట్‌డోర్ యూనిట్ ఫిట్టింగ్, తూకంతో గ్యాస్ ఫిల్లింగ్ మరియు ఇన్వర్టర్ PCB లోపాల నిర్ధారణ.', 'Review the 12-point standard Split AC installation & commissioning protocol', '["PM Vishwakarma / Skilling Scheme"]'::jsonb, '["Water drain slope & vibration pad setup","Measuring superheat & subcooling","Testing DC inverter fan motors & thermistors"]'::jsonb, '7 Weeks', '[{"title":"NIMI RAC Practical Guide","url":"https://bharatskills.gov.in","provider":"NIMI / DGT","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000030' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000372', r.id, 4, 'NAPS OEM Apprenticeship & HVAC Contracting Career', 'एनएपीएस (NAPS) कंपनी अप्रेंटिसशिप और एसी सर्विस व्यवसाय', 'NAPS కంపెనీ అప్రెంటిస్‌షిప్ & స్వయం ఉపాధి', 'Join Voltas, Daikin, Blue Star, or LG service teams via NAPS apprenticeships or establish a seasonal residential/commercial cold-room maintenance business.', 'प्रमुख एसी कंपनियों में अप्रेंटिसशिप पाएं या अपना स्वतंत्र एसी व कोल्ड-रूम सर्विस व्यवसाय शुरू करें।', 'ప్రముఖ ఏసీ కంపెనీలలో NAPS అప్రెంటిస్‌షిప్ లేదా సొంత AC సర్వీస్ వ్యాపారం ప్రారంభించండి.', 'Register on Apprenticeship India and search local RAC vacancies', '["NAPS 2.0 Apprenticeship Stipend"]'::jsonb, '["Seasonal preventive maintenance contracts (AMC)","Warranty claim documentation with OEMs","Applying on Apprenticeship India & NCS"]'::jsonb, '4 Weeks', '[{"title":"Apprenticeship India Portal","url":"https://www.apprenticeshipindia.gov.in","provider":"MSDE","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000030' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000031', 'Personalized Dairy Farm & Livestock Supervisor Pathway', 4, '4 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000373', r.id, 1, 'Scientific Housing, Breed Selection & Clean Milk Production', 'पशु आवास प्रबंधन, नस्ल चयन और स्वच्छ दुग्ध उत्पादन', 'పశువుల షెడ్ నిర్మాణం, జాతుల ఎంపిక & పరిశుభ్రమైన పాల ఉత్పత్తి', 'Design ventilated, well-drained dairy cattle sheds, select high-yield indigenous/crossbred cows & buffaloes, and practice mastitis-free clean milking hygiene.', 'हवादार डेयरी शेड बनाना, उन्नत नस्ल चुनना और थनैला रोग से बचाव व स्वच्छ दुग्ध दोहन सीखें।', 'గాలి వెలుతురు ఉండే షెడ్ నిర్మాణం, అధిక పాల దిగుబడి జాతులు మరియు శుభ్రమైన పాలు పితకడం.', 'Draft a ventilated 10-animal rural dairy shed floor layout', '["Rashtriya Gokul Mission"]'::jsonb, '["Preventing heat stress & mastitis infection","Sanitizing stainless steel milking cans","Tracking calving & lactation intervals"]'::jsonb, '4 Weeks', '[{"title":"NDDB Clean Milk & Dairy Manuals","url":"https://www.nddb.coop","provider":"NDDB India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000031' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000374', r.id, 2, 'Balanced Cattle Ration, Silage Making & Hydroponic Fodder', 'संतुलित पशु आहार, साइलेज निर्माण और हरा चारा प्रबंधन', 'సమతుల్య పశుగ్రాసం, సైలేజ్ తయారీ & పోషకాహారం', 'Formulate cost-effective dry/green fodder + mineral mixture rations based on milk yield and preserve nutritious maize/sorghum silage for dry summer months.', 'दूध उत्पादन अनुसार संतुलित आहार व मिनरल मिक्सचर बनाना और गर्मियों के लिए साइलेज सुरक्षित करना सीखें।', 'పాల దిగుబడికి అనుగుణంగా దాణా తయారీ, ఖనిజ లవణాలు మరియు ఎండాకాలపు సైలేజ్ సంరక్షణ.', 'Calculate daily green, dry fodder & concentrate ration for a 12-liter cow', '[]'::jsonb, '["NDDB Ration Balancing Program (RBP) ratios","Bunker & pit maize silage fermentation","Bypass protein & mineral supplements"]'::jsonb, '4 Weeks', '[{"title":"NDDB Ration Balancing Portal","url":"https://www.nddb.coop","provider":"NDDB","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000031' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000375', r.id, 3, 'Milk Analyzer Fat/SNF Testing & Veterinary Bio-Security', 'मिल्क एनालाइजर फैट/एसएनएफ जांच और टीकाकरण प्रबंधन', 'మిల్క్ అనలైజర్ Fat/SNF పరీక్ష & పశు వ్యాధి నిరోధక టీకాలు', 'Operate ultrasonic automatic milk analyzers to test fat, SNF, and adulteration at village cooperative societies, and schedule FMD/Brucellosis vaccinations.', 'ऑटोमेटिक मिल्क एनालाइजर से फैट/SNF जांचना और एफएमडी व अन्य नियमित टीकाकरण शेड्यूल संभालें।', 'మిల్క్ అనలైజర్‌తో ఫ్యాట్/SNF పరీక్షలు చేయడం మరియు FMD వంటి వ్యాధి నిరోధక టీకాల నిర్వహణ.', 'Build an annual deworming and FMD vaccination calendar for a herd', '["National Livestock Mission"]'::jsonb, '["Calibrating & cleaning ultrasonic milk testers","Spotting early illness & coordinating vets","Maintaining village dairy passbook ledgers"]'::jsonb, '4 Weeks', '[{"title":"Department of Animal Husbandry & Dairying","url":"https://dahd.gov.in","provider":"Ministry of Fisheries & Dairying","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000031' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000376', r.id, 4, 'Dairy Cooperative Roles or Subsidized Dairy Unit Setup', 'डेयरी सहकारी नौकरी अथवा सब्सिडी युक्त डेयरी फार्म व्यवसाय', 'డెయిరీ సహకార ఉద్యోగాలు లేదా రాయితీ డెయిరీ యూనిట్ స్థాపన', 'Work as a Village Milk Collection Supervisor with Amul/Vijaya/Heritage cooperatives or obtain RSETI training to unlock NABARD/MUDRA dairy entrepreneurship loans.', 'सहकारी दुग्ध केंद्र में पर्यवेक्षक बनें या आरसेटी प्रशिक्षण से नाबार्ड/मुद्रा डेयरी ऋण प्राप्त करें।', 'పాల సహకార సంఘంలో సూపర్‌వైజర్ ఉద్యోగం లేదా RSETI/MUDRA లోన్ ద్వారా డెయిరీ ఫామ్ స్థాపన.', 'Prepare a 5-animal starter dairy unit cost and revenue projection', '["Animal Husbandry Infrastructure Fund","PM MUDRA Yojana"]'::jsonb, '["Setting up village bulk milk cooler hygiene","Preparing NABARD/MUDRA dairy project report","Value-added ghee/paneer hygiene basics"]'::jsonb, '4 Weeks', '[{"title":"National Dairy Development Board","url":"https://www.nddb.coop","provider":"NDDB","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000031' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000032', 'Personalized EV Battery & Charging Station Pathway', 4, '5 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000377', r.id, 1, 'High-Voltage DC Safety & EV Charger Standards (Bharat AC/CCS2)', 'हाई-वोल्टेज सुरक्षा और ईवी चार्जर मानक (Bharat AC / CCS2)', 'హై-వోల్టేజ్ భద్రత & EV ఛార్జర్ ప్రమాణాలు (Bharat AC / CCS2)', 'Understand India EVSE standards (Bharat AC-001, Type-2, Bharat DC-001, CCS2), contactor isolation relays, and insulated HV safety gear.', 'भारत एसी-001, टाइप-2 और सीसीएस-2 फास्ट चार्जर मानक व हाई-वोल्टेज सुरक्षा उपकरणों का उपयोग सीखें।', 'Bharat AC-001, Type-2, CCS2 ఫాస్ట్ ఛార్జర్ ప్రమాణాలు మరియు హై-వోల్టేజ్ సేఫ్టీ నియమాలు.', 'Compare pinouts and power ratings across Bharat AC-001, Type-2, and CCS2', '["PM E-DRIVE / EV Skilling Mission"]'::jsonb, '["AC Type-2 vs DC CCS2 connector pinouts","RCCB Type-B earth leakage & SPD protection","Lockout-Tagout (LOTO) HV isolation rules"]'::jsonb, '4 Weeks', '[{"title":"NPTEL Electric Vehicles Course","url":"https://nptel.ac.in","provider":"NPTEL / IIT","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000032' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000378', r.id, 2, 'EVSE Site Survey, Chemical Earthing & Charger Commissioning', 'चार्जिंग साइट सर्वे, केमिकल अर्थिंग और चार्जर इंस्टॉलेशन', 'ఛార్జింగ్ సైట్ సర్వే, కెమికల్ ఎర్తింగ్ & ఛార్జర్ కమిషనింగ్', 'Inspect 3-phase transformer load capacity, install chemical pipe earthing (< 2 Ohms), mount EVSE pedestals, and configure OCPP 1.6J/2.0J cloud telemetry.', '3-फेज लोड जांच, 2 ओम से कम केमिकल अर्थिंग और OCPP क्लाउड नेटवर्क कनेक्शन सेट करना सीखें।', '3-ఫేజ్ లోడ్ తనిఖీ, కెమికల్ ఎర్తింగ్ మరియు OCPP క్లౌడ్ కనెక్టివిటీ సెటప్ చేయడం.', 'Draft a complete 30kW DC public charger installation safety checklist', '[]'::jsonb, '["Site electrical load & cable sizing check","Testing low earth resistance with Megger","Connecting EV charger over 4G/LAN via OCPP"]'::jsonb, '6 Weeks', '[{"title":"Skill India EV Infrastructure Modules","url":"https://www.skillindiadigital.gov.in","provider":"SIDH / ASDC","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000032' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000379', r.id, 3, 'Battery Pack Telemetry, Thermal Cooling & Gun Repair', 'बैटरी पैक टेलीमेट्री, कूलिंग लूप और चार्जिंग गन मरम्मत', 'బ్యాటరీ ప్యాక్ టెలిమెట్రీ, కూలింగ్ & ఛార్జింగ్ గన్ రిపేర్', 'Diagnose pilot signal (CP/PP) handshake faults between EV car BMS and charger controller, maintain liquid cooling pumps, and service gun latches.', 'ईवी व चार्जर के बीच CP/PP सिग्नल त्रुटियां खोजना और कूलिंग पंप व चार्जिंग गन रिपेयर सीखें।', 'CP/PP కమ్యూనికేషన్ లోపాలు గుర్తించడం, కూలింగ్ పంప్ మరియు ఛార్జింగ్ గన్ సర్వీసింగ్.', 'Trace the 5-step CCS2 charging handshake sequence from plug-in to power flow', '[]'::jsonb, '["Decoding Control Pilot (CP) PWM signals","Inspecting DC rectifier power modules","Handling charger thermal derating errors"]'::jsonb, '6 Weeks', '[{"title":"Bureau of Energy Efficiency EV Portal","url":"https://beeindia.gov.in","provider":"Ministry of Power","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000032' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000380', r.id, 4, 'CPO Field Maintenance Apprenticeship & Highway EV Hub Jobs', 'सीपीओ (CPO) फील्ड रखरखाव और हाईवे ईवी चार्जिंग रोजगार', 'CPO ఫీల్డ్ మెయింటెనెన్స్ & హైవే EV ఛార్జింగ్ ఉద్యోగాలు', 'Apply to Charge Point Operators (Tata Power EZ Charge, Statiq, Jio-bp, ChargeZone) or DISCOM EV infrastructure maintenance contractors.', 'टाटा पावर, स्टेटिक व प्रमुख ईवी चार्जिंग ऑपरेटर कंपनियों में फील्ड तकनीशियन पदों पर आवेदन करें।', 'టాటా పవర్, జియో-బిపి వంటి EV ఛార్జింగ్ సంస్థలలో టెక్నీషియన్ ఉద్యోగాలకు దరఖాస్తు చేయండి.', 'Apply to 2 EV service or charging infrastructure openings', '["NAPS 2.0 Apprenticeship Scheme"]'::jsonb, '["SLA uptime SLA ticket turnaround","Maintaining preventive service schedules","Applying via NAPS & clean-tech portals"]'::jsonb, '4 Weeks', '[{"title":"Apprenticeship India EV Roles","url":"https://www.apprenticeshipindia.gov.in","provider":"MSDE","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000032' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000033', 'Personalized IT Helpdesk & Hardware Support Pathway', 4, '5 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000381', r.id, 1, 'PC Hardware Assembly, BIOS, SSD Upgrades & OS Setup', 'कंप्यूटर हार्डवेयर असेंबली, बायोस (BIOS) और ओएस इंस्टॉलेशन', 'PC హార్డ్‌వేర్ అసెంబ్లీ, BIOS & Windows/Linux OS సెటప్', 'Assemble PC components safely, diagnose RAM/PSU/storage POST beeps, partition NVMe SSDs, install Windows/Ubuntu, and configure drivers.', 'कंप्यूटर पुर्जे जोड़ना, रैम/एसएसडी दोष खोजना और विंडोज व उबंटू ओएस इंस्टॉल करना सीखें।', 'కంప్యూటర్ అసెంబుల్ చేయడం, RAM/SSD లోపాలు సరిచేయడం మరియు Windows/Linux ఇన్‌స్టాల్ చేయడం.', 'Create a complete Windows/Linux driver & troubleshooting checklist', '["PMKVY 4.0 IT Support"]'::jsonb, '["Motherboard, RAM, PSU & SSD diagnostics","Bootable USB OS deployment & partitioning","Driver updates & data backup recovery"]'::jsonb, '5 Weeks', '[{"title":"Cisco Computer Hardware Basics","url":"https://www.netacad.com","provider":"Cisco Networking Academy","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000033' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000382', r.id, 2, 'LAN Networking, Wi-Fi Routers, Printers & IP Troubleshooting', 'लैन नेटवर्किंग, वाई-फाई राउटर, प्रिंटर व आईपी जांच', 'LAN నెట్‌వర్కింగ్, వై-ఫై రౌటర్లు, ప్రింటర్ & IP సమస్యల పరిష్కారం', 'Crimp Cat6 RJ45 Ethernet cables, configure DHCP/Static IPs, use ping/tracert/ipconfig diagnostics, and deploy shared network office printers.', 'ईथरनेट केबल क्रिम्प करना, राउटर सेटअप, IP जांच व नेटवर्क प्रिंटर साझा करना सीखें।', 'RJ45 కేబుల్ క్రింపింగ్, రౌటర్ IP సెటప్ మరియు నెట్‌వర్క్ ప్రింటర్ సమస్యలను పరిష్కరించండి.', 'Practice troubleshooting offline internet symptoms with ping and nslookup', '[]'::jsonb, '["Cat6 T568B crimping & LAN cable testing","Diagnosing DNS & gateway drops via CLI","Sharing network printers & scanner folders"]'::jsonb, '5 Weeks', '[{"title":"Cisco Networking Basics Course","url":"https://www.netacad.com/courses/networking/networking-basics","provider":"Cisco Networking Academy","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000033' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000383', r.id, 3, 'Active Directory Basics, Cybersecurity Hygiene & Ticketing', 'यूजर अकाउंट प्रबंधन, साइबर सुरक्षा और टिकटिंग सिस्टम', 'యూజర్ అకౌంట్లు, సైబర్ భద్రత & హెల్ప్‌డెస్క్ టికెటింగ్', 'Reset user passwords safely, protect desktops from phishing/malware, manage Microsoft 365/Google Workspace users, and log clear IT support tickets.', 'पासवर्ड सुरक्षा, मैलवेयर हटाना, ईमेल अकाउंट प्रबंधन व हेल्पडेस्क टिकट हल करना सीखें।', 'పాస్‌వర్డ్ రిసెట్, మాల్వేర్ రక్షణ మరియు క్రమబద్ధంగా హెల్ప్‌డెస్క్ టికెట్లు పరిష్కరించడం.', 'Complete Cisco Introduction to Cybersecurity free badge', '[]'::jsonb, '["Two-factor auth & endpoint antivirus hygiene","Remote desktop support etiquette","Writing concise SLA resolution notes"]'::jsonb, '5 Weeks', '[{"title":"Skill India IT Helpdesk Attendant Guide","url":"https://www.skillindiadigital.gov.in","provider":"SIDH / NASSCOM","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000033' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000384', r.id, 4, 'IT Support Internships & District e-Governance / BPO Hiring', 'आईटी सपोर्ट इंटर्नशिप और जिला/कॉर्पोरेट टेक रोजगार', 'IT సపోర్ట్ ఇంటర్న్‌షిప్ & జిల్లా/కార్పొరేట్ ఉద్యోగ దరఖాస్తులు', 'Apply for L1 IT Helpdesk, hospital/school computer lab support, and corporate desktop engineer internships across NCS, NAPS, and Internshala.', 'अस्पतालों, कॉलेजों और आईटी कंपनियों में L1 हेल्पडेस्क व सिस्टम सपोर्ट पदों हेतु आवेदन करें।', 'కళాశాలలు, ఆసుపత్రులు మరియు ఐటీ కంపెనీలలో IT సపోర్ట్ ఉద్యోగాలకు దరఖాస్తు చేయండి.', 'Apply to 5 IT Helpdesk or Desktop Support openings', '["NAPS 2.0 & AICTE Internships"]'::jsonb, '["Building a practical hardware/network resume","Handling live troubleshooting interview scenarios","Applying on NCS, NAPS & Naukri"]'::jsonb, '4 Weeks', '[{"title":"National Career Service IT Jobs","url":"https://www.ncs.gov.in","provider":"NCS","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000033' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000034', 'Personalized Gramin Dak Sevak (India Post) Pathway', 4, '2 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000385', r.id, 1, 'Verify Class 10 Eligibility, Local Language & Merit Criteria', '10वीं कक्षा योग्यता, स्थानीय भाषा व मेरिट मानदंड जांच', '10వ తరగతి అర్హత, స్థానిక భాష & మెరిట్ ప్రమాణాల పరిశీలన', 'Ensure 10th matriculation marksheet has Mathematics and English plus studied state regional language, prepare Aadhaar/caste/residence certificates.', 'गणित व अंग्रेजी सहित 10वीं अंकतालिका, स्थानीय भाषा योग्यता और जाति/निवास प्रमाण पत्र तैयार रखें।', 'గణితం, ఇంగ్లీష్ మరియు స్థానిక భాషతో 10వ తరగతి మార్కుల లిస్ట్ మరియు సర్టిఫికెట్లు సిద్ధం చేయండి.', 'Verify your certificates & circle eligibility rules at indiapostgdsonline.gov.in', '["Central Government Rural Employment"]'::jsonb, '["Verifying state circle language rules","Checking bicycle riding & local residence criteria","Keeping original 10th & category docs updated"]'::jsonb, '2 Weeks', '[{"title":"India Post GDS Official Portal","url":"https://indiapostgdsonline.gov.in","provider":"Department of Posts","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000034' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000386', r.id, 2, 'Computer Certificate, Darpan Device & IPPB Digital Banking', 'कंप्यूटर ज्ञान, दर्पण डिवाइस और इंडिया पोस्ट पेमेंट्स बैंक (IPPB)', 'కంప్యూటర్ పరిజ్ఞానం, దర్పణ్ పరికరం & IPPB బ్యాంకింగ్', 'Learn basic desktop/Android operations, Aadhaar AePS biometric cash transactions under India Post Payments Bank (IPPB), and Sukanya Samriddhi savings accounts.', 'दर्पण हैंडहेल्ड डिवाइस चलाना, IPPB आधार बैंकिंग और सुकन्या समृद्धि खाता सेवा समझें।', 'దర్పణ్ పరికరం ద్వారా IPPB ఆధార్ బ్యాంకింగ్, సుకన్య సమృద్ధి మరియు పోస్టల్ ఖాతాలు నేర్చుకోండి.', 'Review key savings schemes: SSA, PPF, RD & Postal Life Insurance', '[]'::jsonb, '["Basic computer certificate readiness (60+ days)","Understanding IPPB QR & AePS cash deposits","Learning PLI / RPLI rural insurance benefits"]'::jsonb, '3 Weeks', '[{"title":"India Post Payments Bank (IPPB)","url":"https://www.ippbonline.com","provider":"India Post","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000034' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000387', r.id, 3, 'Online Portal Application & District Post Office Preferences', 'ऑनलाइन जीडीएस आवेदन एवं जिला डाकघर वरीयता चयन', 'ఆన్‌లైన్ GDS దరఖాస్తు & జిల్లా పోస్ట్ ఆఫీస్ ప్రాధాన్యతలు', 'Track national GDS Schedule notifications, fill accurate registration details without typos, and carefully prioritize nearby village Branch Post Offices (BPM/ABPM).', 'आधिकारिक पोर्टल पर त्रुटिहीन फॉर्म भरें और अपने जिले के नजदीकी डाकघरों की प्राथमिकता चुनें।', 'తప్పులు లేకుండా ఆన్‌లైన్ దరఖాస్తు పూర్తి చేసి మీ జిల్లాలోని పోస్ట్ ఆఫీసులను ఎంచుకోండి.', 'Bookmark official notification calendar and check state vacancy matrix', '[]'::jsonb, '["Accurate percentage/grade entry without mismatch","Selecting optimal local division BO preferences","Monitoring shortlist SMS & email notifications"]'::jsonb, '2 Weeks', '[{"title":"India Post GDS Online Portal","url":"https://indiapostgdsonline.gov.in","provider":"Department of Posts","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000034' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000388', r.id, 4, 'Document Verification, Dak Karmayogi & Departmental Promotion', 'दस्तावेज सत्यापन, डाक कर्मयोगी और विभागीय पदोन्नति', 'సర్టిఫికెట్ వెరిఫికేషన్, డాక్ కర్మయోగి & శాఖాపరమైన ప్రమోషన్లు', 'Complete physical verification cleanly, finish Dak Karmayogi induction modules, and prepare for departmental LGO exams after 3–5 years to become Postman/MTS/PA.', 'सफल सत्यापन के बाद डाक कर्मयोगी प्रशिक्षण लें और विभागीय परीक्षा से पोस्टमैन/पीए बनें।', 'వెరిఫికేషన్ తర్వాత డాక్ కర్మయోగి ట్రైనింగ్ పూర్తి చేసి పోస్ట్‌మ్యాన్/PA ప్రమోషన్ పరీక్షలకు సిద్ధమవండి.', 'Prepare your verification document folder checklist', '["Departmental LGO Career Progression"]'::jsonb, '["Preparing original + 2 attested document sets","Completing Dak Karmayogi online courses","Understanding 3-year/5-year MTS/Postman exam track"]'::jsonb, '1 Week', '[{"title":"Department of Posts India","url":"https://www.indiapost.gov.in","provider":"Govt of India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000034' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000035', 'Personalized Solar Water Pump & Micro-Irrigation Pathway', 4, '4 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000389', r.id, 1, 'Solar PV Array Sizing & Farm Borewell Head Calculation', 'सोलर पैनल साइजिंग और बोरवेल हेड/वाटर पंप गणना', 'సోలార్ ప్యానెల్ సైజింగ్ & బోరుబావి పంప్ లెక్కింపు', 'Calculate total dynamic head (TDH), daily water demand in liters, and choose matching 2HP/3HP/5HP/7.5HP DC or AC solar pump configurations under PM-KUSUM.', 'बोरवेल की गहराई (Head) के अनुसार 2HP से 7.5HP सोलर पंप और पैनल क्षमता चुनना सीखें।', 'బోరు లోతును బట్టి 2HP నుండి 7.5HP సోలార్ పంప్ & ప్యానెళ్ల సామర్థ్యాన్ని లెక్కించండి.', 'Compute required solar array kWp for a 5HP borewell pump at 60m head', '["PM-KUSUM Solar Pump Scheme"]'::jsonb, '["Calculating Total Dynamic Head & flow discharge","Matching solar wattage (Wp) to pump HP","Understanding DC vs AC submersible motors"]'::jsonb, '3 Weeks', '[{"title":"MNRE PM-KUSUM Portal","url":"https://pmkusum.mnre.gov.in","provider":"MNRE","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000035' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000390', r.id, 2, 'Dual-Axis Pole Mounting, Borewell Lowering & VFD Wiring', 'सोलर पोल स्थापना, पंप उतारना और VFD कंट्रोलर वायरिंग', 'సోలార్ పోల్ నిర్మాణం, పంప్ దించడం & VFD కంట్రోలర్ వైరింగ్', 'Cement galvanized solar mast foundations, assemble seasonal manual-tracking array racks, wire solar VFD pump inverters, and protect against dry-run borewells.', 'सीमेंट नींव पर सोलर स्ट्रक्चर लगाना, ट्रैकिंग एंगल सेट करना और VFD कंट्रोलर वायरिंग सीखें।', 'సిమెంట్ ఫౌండేషన్‌పై సోలార్ స్టాండ్ ఏర్పాటు, మోటార్ దించడం మరియు VFD కంట్రోలర్ కనెక్షన్.', 'Draw a full wiring schematic from solar strings -> DC SPD -> VFD -> 3-wire pump', '["Suryamitra / SCGJ Certification"]'::jsonb, '["Concrete foundation & wind-load anchoring","Setting dry-run & tank-full float sensors","Installing DC surge arresters & earthing"]'::jsonb, '5 Weeks', '[{"title":"NISE Solar Pump Training Resources","url":"https://nise.res.in","provider":"NISE","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000035' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000391', r.id, 3, 'Drip & Sprinkler Lateral Integration with Hydrocyclone Filters', 'ड्रिप/स्प्रिंकलर सिंचाई और हाइड्रोसाइक्लोन फिल्टर जुड़ाव', 'డ్రిప్/స్ప్రింక్లర్ లైన్లు & ఫిల్టర్ల అనుసంధానం', 'Connect solar pump delivery headers cleanly to sand/hydrocyclone filters, screen filters, pressure relief valves, and farm drip micro-irrigation grids.', 'सोलर पंप आउटलेट को सैंड/स्क्रीन फिल्टर और खेत की ड्रिप सिंचाई लाइन से सुरक्षित जोड़ना सीखें।', 'సోలార్ పంప్ అవుట్‌లెట్‌ను ఫిల్టర్లు మరియు పొలంలోని డ్రిప్ పైపులతో అనుసంధానం చేయడం.', 'Inspect filter maintenance and flushing intervals on a drip pipeline setup', '["PMKSY Drip Irrigation Subsidy"]'::jsonb, '["Removing borewell sand via hydrocyclone filters","Balancing pressure across drip sub-mains","Testing water output uniformity across rows"]'::jsonb, '4 Weeks', '[{"title":"PMKSY Micro-Irrigation Guidelines","url":"https://pmksy.gov.in","provider":"Ministry of Agriculture","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000035' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000392', r.id, 4, 'PM-KUSUM Vendor Field Team & Rural Maintenance Business', 'पीएम-कुसुम कंपनी रोजगार एवं जिला मरम्मत सेवा व्यवसाय', 'PM-KUSUM వెండర్ ఉద్యోగం & గ్రామీణ సర్వీస్ కాంట్రాక్టులు', 'Work with state empanelled PM-KUSUM solar pump EPC vendors or offer district-wide VFD inverter repair and seasonal panel cleaning contracts.', 'पीएम-कुसुम कंपनियों में इंस्टॉलर बनें या जिले में पंप व कंट्रोलर रखरखाव का अनुबंध व्यवसाय चलाएं।', 'PM-KUSUM వెండర్ కంపెనీలలో ఇన్‌స్టాలర్ ఉద్యోగం లేదా జిల్లా స్థాయి రిపేర్ సర్వీసు.', 'Connect with local DISCOM / Renewable Energy Development Corp vendor offices', '["PM-KUSUM & PM MUDRA Loan"]'::jsonb, '["Commissioning GPS photo verification logs","Customer farmer training on VFD fault codes","Registering on Skill India & NAPS portals"]'::jsonb, '3 Weeks', '[{"title":"Skill India Digital Hub","url":"https://www.skillindiadigital.gov.in","provider":"SIDH","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000035' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmaps (id, career_id, title, total_stages, estimated_duration) VALUES ('d1000000-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000036', 'Personalized Plumber & Nal Jal Mitra Pathway', 4, '4 Months') ON CONFLICT (career_id) DO UPDATE SET title = EXCLUDED.title, total_stages = EXCLUDED.total_stages, estimated_duration = EXCLUDED.estimated_duration;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000393', r.id, 1, 'Plumbing Tools, Pipe Types (HDPE/UPVC/CPVC) & Blueprints', 'प्लंबिंग औजार, पाइप प्रकार (HDPE/UPVC/CPVC) और नक्शा ज्ञान', 'ప్లంబింగ్ టూల్స్, పైపుల రకాలు (HDPE/UPVC/CPVC) & డ్రాయింగ్', 'Identify pipe pressure ratings, operate pipe wrenches, dies, CPVC solvent cement, and electrofusion couplers used in rural water distribution grids.', 'पाइप प्रेशर ग्रेड, सॉल्वेंट वेल्डिंग, और ग्रामीण पेयजल पाइपलाइन नक्शा समझना सीखें।', 'పైపుల గ్రేడ్‌లు, సాల్వెంట్ జాయింటింగ్ మరియు గ్రామ నీటి సరఫరా పైప్‌లైన్ ప్లాన్ చదవడం.', 'Assemble a test loop with elbow, tee, union, and ball valve joints cleanly', '["Jal Jeevan Mission Nal Jal Mitra"]'::jsonb, '["Differentiating HDPE, UPVC, CPVC & GI pipes","Leak-proof solvent cementing & thread taping","Reading village distribution pipe maps"]'::jsonb, '3 Weeks', '[{"title":"Bharat Skills Plumber Study e-Books","url":"https://bharatskills.gov.in","provider":"DGT / Bharat Skills","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000036' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000394', r.id, 2, 'Village Overhead Tank Valves, Tap Connections (FHTC) & Pumps', 'ओवरहेड टैंक वाल्व, घरेलू नल कनेक्शन (FHTC) और पंप संचालन', 'ఓవర్‌హెడ్ ట్యాంక్ వాల్వ్‌లు, ఇంటి నల్లా కనెక్షన్లు & పంప్ నిర్వహణ', 'Install household Functional Household Tap Connections (FHTC), water flow meters, non-return check valves, sluice gate valves, and air-release valves.', 'हर घर नल कनेक्शन, वॉटर मीटर, स्लुइस वाल्व और एयर-रिलीज़ वाल्व लगाना व रखरखाव सीखें।', 'ఇంటి నల్లా కనెక్షన్ (FHTC), వాటర్ మీటర్, గేట్ వాల్వ్ మరియు పంప్ మోటార్ నిర్వహణ.', 'Map the valve layout from village pump house to ward street distribution', '["Har Ghar Jal / Nal Jal Mitra"]'::jsonb, '["Tapping distribution mains without contamination","Servicing jammed gate & air valves","Checking overhead tank water level floats"]'::jsonb, '5 Weeks', '[{"title":"Jal Jeevan Mission Official Guidelines","url":"https://jaljeevanmission.gov.in","provider":"Ministry of Jal Shakti","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000036' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000395', r.id, 3, 'Water Quality Testing (Chlorine/FTK) & Leak Detection', 'पेयजल गुणवत्ता जांच (क्लोरीन/FTK किट) और लीकेज मरम्मत', 'నీటి నాణ్యత పరీక్షలు (క్లోరిన్/FTK) & పైప్ లీకేజీ మరమ్మతు', 'Test residual free chlorine using ortho-tolidine / Field Test Kits (FTK), isolate underground pipeline bursts, and flush dead-end mains cleanly.', 'फील्ड टेस्ट किट (FTK) से पानी में क्लोरीन व शुद्धता जांचना और भूमिगत रिसाव सुधारना सीखें।', 'FTK కిట్‌తో నీటి క్లోరిన్/శుభ్రత పరీక్షించడం మరియు భూగర్భ పైప్ లీకేజీలు సరిచేయడం.', 'Practice logging 5 household tap water chlorine & pressure readings', '[]'::jsonb, '["Maintaining safe 0.2–0.5 ppm chlorine","Pinpointing and clamping pipe cracks","Sanitizing repaired rural distribution lines"]'::jsonb, '4 Weeks', '[{"title":"JJM Water Quality Portal","url":"https://jaljeevanmission.gov.in","provider":"DDWS India","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000036' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.roadmap_steps (id, roadmap_id, step_number, title, title_hi, title_te, description, description_hi, description_te, action_cta, schemes_applicable, learning_objectives, estimated_duration, resource_links) SELECT 'd2000000-0000-0000-0000-000000000396', r.id, 4, 'Gram Panchayat Water O&M & Plumbing Contractor Enterprise', 'ग्राम पंचायत जल संचालन रोजगार एवं स्वतंत्र प्लंबिंग व्यवसाय', 'గ్రామ పంచాయతీ నీటి సరఫరా ఉద్యోగం లేదా స్వంత ప్లంబింగ్ వ్యాపారం', 'Secure Village Water & Sanitation Committee (VWSC) O&M contracts as certified Nal Jal Mitra or offer residential bathroom/kitchen plumbing installations.', 'ग्राम पंचायत में नल जल मित्र के रूप में कार्य करें या पीएम विश्वकर्मा टूलकिट से प्लंबिंग व्यवसाय शुरू करें।', 'గ్రామ పంచాయతీ నల్ జల్ మిత్ర బాధ్యతలు లేదా పీఎం విశ్వకర్మ టూల్‌కిట్‌తో స్వయం ఉపాధి.', 'Apply through your district ITI / Gram Panchayat Nal Jal Mitra batch', '["PM Vishwakarma ₹15,000 Toolkit Scheme","Jal Jeevan Mission"]'::jsonb, '["Preparing monthly Panchayat pipeline maintenance logs","Estimating household bathroom & sanitary jobs","Claiming PM Vishwakarma Toolkit support"]'::jsonb, '3 Weeks', '[{"title":"PM Vishwakarma Portal","url":"https://pmvishwakarma.gov.in","provider":"MoMSME","is_free":true}]'::jsonb FROM public.roadmaps r WHERE r.career_id = 'a1000000-0000-0000-0000-000000000036' ON CONFLICT (roadmap_id, step_number) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, action_cta = EXCLUDED.action_cta, schemes_applicable = EXCLUDED.schemes_applicable, learning_objectives = EXCLUDED.learning_objectives, estimated_duration = EXCLUDED.estimated_duration, resource_links = EXCLUDED.resource_links;
INSERT INTO public.opportunities (id, title, title_hi, title_te, ministry_or_agency, category, financial_benefit, eligibility_criteria, portal_url, deadline_notice, is_active, verification_status, source_url, last_verified_date) VALUES ('f1000000-0000-0000-0000-000000000015', 'PM Internship Scheme (Top 500 Indian Companies)', 'पीएम इंटर्नशिप योजना (शीर्ष 500 भारतीय कंपनियों में प्रशिक्षण)', 'పీఎం ఇంటర్న్‌షిప్ స్కీమ్ (భారతదేశపు టాప్ 500 కంపెనీలలో ఇంటర్న్‌షిప్)', 'Ministry of Corporate Affairs (MCA), Govt of India', 'internship', '₹5,000/month financial assistance (₹4,500 DBT from Govt + ₹500 from company) + ₹6,000 one-time incidental grant', 'Indian youth aged 21-24 who passed 10th, 12th, ITI, Polytechnic Diploma, or non-premier Bachelor degree and are not in full-time employment.', 'https://pminternship.mca.gov.in', 'Rolling application rounds active on MCA PM Internship Portal', true, 'OFFICIAL_VERIFIED', 'https://pminternship.mca.gov.in', '2026-11-26') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, ministry_or_agency = EXCLUDED.ministry_or_agency, category = EXCLUDED.category, financial_benefit = EXCLUDED.financial_benefit, eligibility_criteria = EXCLUDED.eligibility_criteria, portal_url = EXCLUDED.portal_url, deadline_notice = EXCLUDED.deadline_notice, is_active = EXCLUDED.is_active, verification_status = EXCLUDED.verification_status, source_url = EXCLUDED.source_url, last_verified_date = EXCLUDED.last_verified_date;
INSERT INTO public.opportunities (id, title, title_hi, title_te, ministry_or_agency, category, financial_benefit, eligibility_criteria, portal_url, deadline_notice, is_active, verification_status, source_url, last_verified_date) VALUES ('f1000000-0000-0000-0000-000000000016', 'AICTE National Internship Portal (Technical & Rural Sectors)', 'एआईसीटीई राष्ट्रीय इंटर्नशिप पोर्टल (तकनीकी व ग्रामीण विकास)', 'AICTE నేషనల్ ఇంటర్న్‌షిప్ పోర్టల్ (టెక్నికల్ & గ్రామీణ రంగాలు)', 'All India Council for Technical Education (AICTE)', 'internship', 'Verified paid and certificate internships across software, EV, smart cities, telecom, and ULB municipalities', 'Diploma, Polytechnic, B.E/B.Tech, BCA, B.Sc, and ITI students enrolled in recognized institutions', 'https://internship.aicte-india.org', 'Continuous company & municipal internship openings year-round', true, 'OFFICIAL_VERIFIED', 'https://internship.aicte-india.org', '2026-11-26') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, title_te = EXCLUDED.title_te, ministry_or_agency = EXCLUDED.ministry_or_agency, category = EXCLUDED.category, financial_benefit = EXCLUDED.financial_benefit, eligibility_criteria = EXCLUDED.eligibility_criteria, portal_url = EXCLUDED.portal_url, deadline_notice = EXCLUDED.deadline_notice, is_active = EXCLUDED.is_active, verification_status = EXCLUDED.verification_status, source_url = EXCLUDED.source_url, last_verified_date = EXCLUDED.last_verified_date;
