INSERT INTO public.job_portals (id, name, url, portal_type, description, description_hi, description_te, target_users, opportunity_categories, geographic_coverage, application_method, language_availability, verification_status, last_checked_date) VALUES ('f3000000-0000-0000-0000-000000000013', 'PM Internship Scheme Portal (MCA)', 'https://pminternship.mca.gov.in', 'apprenticeship', 'Central Government portal connecting youth aged 21-24 with 12-month paid internships across India Top 500 companies with ₹5,000 monthly stipend.', 'कॉर्पोरेट कार्य मंत्रालय का आधिकारिक पोर्टल जो युवाओं को शीर्ष 500 कंपनियों में ₹5,000 मासिक वजीफे के साथ 12 महीने की इंटर्नशिप प्रदान करता है।', 'కేంద్ర కార్పొరేట్ వ్యవహారాల మంత్రిత్వ శాఖ పోర్టల్, యువతకు నెలకు ₹5,000 స్టైపెండ్‌తో 12 నెలల ఇంటర్న్‌షిప్ అవకాశాలు కల్పిస్తుంది.', '10th, 12th, ITI, Polytechnic Diploma & Graduate youth aged 21-24', '["paid_internships","corporate_training","govt_stipend"]'::jsonb, 'Pan-India (All Districts)', 'Online Aadhaar eKYC & Candidate Profile Selection', '["en","hi","te"]'::jsonb, 'OFFICIAL_VERIFIED', '2026-11-26') ON CONFLICT (name) DO UPDATE SET url = EXCLUDED.url, portal_type = EXCLUDED.portal_type, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, target_users = EXCLUDED.target_users, opportunity_categories = EXCLUDED.opportunity_categories, geographic_coverage = EXCLUDED.geographic_coverage, application_method = EXCLUDED.application_method, language_availability = EXCLUDED.language_availability, verification_status = EXCLUDED.verification_status, last_checked_date = EXCLUDED.last_checked_date;
INSERT INTO public.job_portals (id, name, url, portal_type, description, description_hi, description_te, target_users, opportunity_categories, geographic_coverage, application_method, language_availability, verification_status, last_checked_date) VALUES ('f3000000-0000-0000-0000-000000000014', 'AICTE National Internship Portal', 'https://internship.aicte-india.org', 'skilling', 'Official All India Council for Technical Education hub offering verified virtual and on-site internships across government departments, smart cities, and companies.', 'एआईसीटीई का आधिकारिक इंटर्नशिप पोर्टल जहां छात्र सरकारी विभागों, स्मार्ट सिटी और तकनीकी कंपनियों में इंटर्नशिप पा सकते हैं।', 'AICTE అధికారిక జాతీయ ఇంటర్న్‌షిప్ పోర్టల్, ప్రభుత్వ శాఖలు, స్మార్ట్ సిటీలు మరియు టెక్ కంపెనీలలో ఇంటర్న్‌షిప్‌లు అందిస్తుంది.', 'Polytechnic Diploma, B.Tech, BCA, B.Sc, and ITI students', '["technical_internships","smart_city_projects","virtual_internships"]'::jsonb, 'Pan-India', 'Student Email Registration & Online Apply', '["en","hi"]'::jsonb, 'OFFICIAL_VERIFIED', '2026-11-26') ON CONFLICT (name) DO UPDATE SET url = EXCLUDED.url, portal_type = EXCLUDED.portal_type, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, target_users = EXCLUDED.target_users, opportunity_categories = EXCLUDED.opportunity_categories, geographic_coverage = EXCLUDED.geographic_coverage, application_method = EXCLUDED.application_method, language_availability = EXCLUDED.language_availability, verification_status = EXCLUDED.verification_status, last_checked_date = EXCLUDED.last_checked_date;
INSERT INTO public.job_portals (id, name, url, portal_type, description, description_hi, description_te, target_users, opportunity_categories, geographic_coverage, application_method, language_availability, verification_status, last_checked_date) VALUES ('f3000000-0000-0000-0000-000000000015', 'India Post GDS Online Engagement Portal', 'https://indiapostgdsonline.gov.in', 'government', 'Official recruitment portal of Department of Posts for Gramin Dak Sevak (BPM & ABPM) positions across rural post offices in India.', 'भारतीय डाक विभाग का आधिकारिक भर्ती पोर्टल जहां ग्रामीण डाक सेवक (BPM/ABPM) पदों के लिए 10वीं मेरिट के आधार पर चयन होता है।', 'భారత తపాలా శాఖ అధికారిక పోర్టల్, గ్రామీణ డాక్ సేవక్ (BPM/ABPM) ప్రభుత్వ ఉద్యోగాల కోసం 10వ తరగతి మెరిట్ ద్వారా భర్తీ చేస్తుంది.', '10th Pass candidates with knowledge of local state language', '["rural_government_jobs","postal_services"]'::jsonb, 'Pan-India (All Village Post Offices)', 'Online Merit Registration', '["en","hi"]'::jsonb, 'OFFICIAL_VERIFIED', '2026-11-26') ON CONFLICT (name) DO UPDATE SET url = EXCLUDED.url, portal_type = EXCLUDED.portal_type, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, target_users = EXCLUDED.target_users, opportunity_categories = EXCLUDED.opportunity_categories, geographic_coverage = EXCLUDED.geographic_coverage, application_method = EXCLUDED.application_method, language_availability = EXCLUDED.language_availability, verification_status = EXCLUDED.verification_status, last_checked_date = EXCLUDED.last_checked_date;
INSERT INTO public.job_portals (id, name, url, portal_type, description, description_hi, description_te, target_users, opportunity_categories, geographic_coverage, application_method, language_availability, verification_status, last_checked_date) VALUES ('f3000000-0000-0000-0000-000000000016', 'NATS 2.0 (National Apprenticeship Training Portal)', 'https://nats.education.gov.in', 'apprenticeship', 'Ministry of Education national apprenticeship portal for engineering, polytechnic diploma, and general stream graduates seeking 1-year paid industrial training.', 'शिक्षा मंत्रालय का नैट्स 2.0 पोर्टल जो इंजीनियरिंग, पॉलिटेक्निक डिप्लोमा और स्नातक छात्रों को सवेतन उद्योग प्रशिक्षण देता है।', 'కేంద్ర విద్యా మంత్రిత్వ శాఖ NATS 2.0 పోర్టల్, డిప్లొమా మరియు డిగ్రీ విద్యార్థులకు స్టైపెండ్‌తో కూడిన పారిశ్రామిక శిక్షణ అందిస్తుంది.', 'Polytechnic Diploma & Degree Graduates', '["engineering_apprenticeship","graduate_stipend_training"]'::jsonb, 'Pan-India', 'Candidate Enrollment ID & Industry Application', '["en","hi"]'::jsonb, 'OFFICIAL_VERIFIED', '2026-11-26') ON CONFLICT (name) DO UPDATE SET url = EXCLUDED.url, portal_type = EXCLUDED.portal_type, description = EXCLUDED.description, description_hi = EXCLUDED.description_hi, description_te = EXCLUDED.description_te, target_users = EXCLUDED.target_users, opportunity_categories = EXCLUDED.opportunity_categories, geographic_coverage = EXCLUDED.geographic_coverage, application_method = EXCLUDED.application_method, language_availability = EXCLUDED.language_availability, verification_status = EXCLUDED.verification_status, last_checked_date = EXCLUDED.last_checked_date;
